	//{{{ processKeyEvent() method
	/**
	 * Forwards key events directly to the input handler.
	 * This is slightly faster than using a KeyListener
	 * because some Swing overhead is avoided.
	 */
	public void processKeyEvent(KeyEvent evt)
	{
		if(isClosed())
			return;

		if(isHandledByFocusOwner(evt))
			return;

		if(evt.isConsumed())
			return;

		evt = KeyEventWorkaround.processKeyEvent(evt);
		if(evt == null)
			return;

		dispatchKeyEvent(evt);

		if(!evt.isConsumed())
			super.processKeyEvent(evt);
	} //}}}

	//{{{ isHandledByFocusOwner() method
	/**
	 * Returns true if the focus owner already handles this key event.
	 */
	private boolean isHandledByFocusOwner(KeyEvent evt)
	{
		Component focusOwner = getFocusOwner();

		if(focusOwner instanceof JComponent
			&& isBoundInActionMap((JComponent)focusOwner, evt))
			return true;

		if(focusOwner instanceof JTextComponent
			&& isHandledByTextComponent((JTextComponent)focusOwner, evt))
			return true;

		return false;
	} //}}}

	//{{{ isBoundInActionMap() method
	/**
	 * Returns true if the given component has a binding for this key event.
	 */
	private boolean isBoundInActionMap(JComponent comp, KeyEvent evt)
	{
		InputMap map = comp.getInputMap();
		ActionMap am = comp.getActionMap();

		if(map == null || am == null || !comp.isEnabled())
			return false;

		Object binding = map.get(KeyStroke.getKeyStrokeForEvent(evt));
		return binding != null && am.get(binding) != null;
	} //}}}

	//{{{ isHandledByTextComponent() method
	/**
	 * Returns true if the given text component handles this key event.
	 */
	private boolean isHandledByTextComponent(JTextComponent comp, KeyEvent evt)
	{
		// fix for the bug where key events in JTextComponents
		// inside views are also handled by the input handler
		if(evt.getID() == KeyEvent.KEY_PRESSED)
		{
			int keyCode = evt.getKeyCode();
			if(keyCode == KeyEvent.VK_BACK_SPACE
				|| keyCode == KeyEvent.VK_TAB
				|| keyCode == KeyEvent.VK_ENTER)
			{
				return true;
			}
		}

		Keymap keymap = comp.getKeymap();
		return keymap.getAction(KeyStroke.getKeyStrokeForEvent(evt)) != null;
	} //}}}

	//{{{ dispatchKeyEvent() method
	/**
	 * Dispatches a key event to the interceptor or input handler.
	 */
	private void dispatchKeyEvent(KeyEvent evt)
	{
		switch(evt.getID())
		{
		case KeyEvent.KEY_TYPED:
			handleKeyTyped(evt);
			break;
		case KeyEvent.KEY_PRESSED:
			handleKeyPressed(evt);
			break;
		case KeyEvent.KEY_RELEASED:
			handleKeyReleased(evt);
			break;
		}
	} //}}}

	//{{{ handleKeyTyped() method
	/**
	 * Handles a KEY_TYPED event.
	 */
	private void handleKeyTyped(KeyEvent evt)
	{
		// Handled in text area
		if(keyEventInterceptor != null)
			/* keyEventInterceptor.keyTyped(evt) */;
		else if(inputHandler.isPrefixActive()
			&& !getTextArea().hasFocus())
			inputHandler.keyTyped(evt);
	} //}}}

	//{{{ handleKeyPressed() method
	/**
	 * Handles a KEY_PRESSED event.
	 */
	private void handleKeyPressed(KeyEvent evt)
	{
		if(keyEventInterceptor != null)
			keyEventInterceptor.keyPressed(evt);
		else
			inputHandler.keyPressed(evt);
	} //}}}

	//{{{ handleKeyReleased() method
	/**
	 * Handles a KEY_RELEASED event.
	 */
	private void handleKeyReleased(KeyEvent evt)
	{
		if(keyEventInterceptor != null)
			keyEventInterceptor.keyReleased(evt);
		else
			inputHandler.keyReleased(evt);
	} //}}}

