	/**
	 * Returns true if the currently focused component has its own
	 * binding for this key event, in which case the view should not
	 * process it further.
	 */
	private boolean isFocusOwnerActionBound(KeyEvent evt)
	{
		Component focusOwner = getFocusOwner();
		if(!(focusOwner instanceof JComponent))
			return false;

		JComponent comp = (JComponent)focusOwner;
		InputMap map = comp.getInputMap();
		ActionMap am = comp.getActionMap();

		if(map == null || am == null || !comp.isEnabled())
			return false;

		Object binding = map.get(KeyStroke.getKeyStrokeForEvent(evt));
		return binding != null && am.get(binding) != null;
	}

	/**
	 * Returns true if the currently focused text component will
	 * handle this key event itself.
	 */
	private boolean isFocusOwnerTextComponentEventHandled(KeyEvent evt)
	{
		Component focusOwner = getFocusOwner();
		if(!(focusOwner instanceof JTextComponent))
			return false;

		if(evt.getID() == KeyEvent.KEY_PRESSED)
		{
			switch(evt.getKeyCode())
			{
			case KeyEvent.VK_BACK_SPACE:
			case KeyEvent.VK_TAB:
			case KeyEvent.VK_ENTER:
				return true;
			}
		}

		Keymap keymap = ((JTextComponent)focusOwner).getKeymap();
		return keymap.getAction(KeyStroke.getKeyStrokeForEvent(evt)) != null;
	}

