	private boolean isFocusOwnerBindingHandled(Component focusOwner, KeyEvent evt)
	{
		if(focusOwner instanceof JComponent)
		{
			JComponent comp = (JComponent)focusOwner;
			InputMap map = comp.getInputMap();
			ActionMap am = comp.getActionMap();

			if(map != null && am != null && comp.isEnabled())
			{
				Object binding = map.get(KeyStroke.getKeyStrokeForEvent(evt));
				if(binding != null && am.get(binding) != null)
					return true;
			}
		}

		return false;
	} //}}}

	//{{{ isTextComponentEventHandled() method
	/**
	 * Returns true if the focused text component handles this key event
	 * itself, preventing the view's input handler from seeing it.
	 */
	private boolean isTextComponentEventHandled(Component focusOwner, KeyEvent evt)
	{
		if(focusOwner instanceof JTextComponent)
		{
			if(evt.getID() == KeyEvent.KEY_PRESSED)
			{
				switch(evt.getKeyCode())
				{
				case KeyEvent.VK_BACK_SPACE:
				case KeyEvent.VK_TAB:
				case KeyEvent.VK_ENTER:
					return true;
				}
			}

			Keymap keymap = ((JTextComponent)focusOwner)
				.getKeymap();
			if(keymap.getAction(KeyStroke.getKeyStrokeForEvent(evt)) != null)
				return true;
		}

		return false;
	} //}}}

