	//{{{ processKeyEvent() method
	/**
	 * Forwards key events directly to the input handler.
	 * This is slightly faster than using a KeyListener
	 * because some Swing overhead is avoided.
	 */
	public void processKeyEvent(KeyEvent evt)
	{
		if(isClosed())
			return;

		if(focusOwnerHasBinding(evt))
			return;

		if(textComponentConsumesEvent(evt))
			return;

		if(evt.isConsumed())
			return;

		evt = KeyEventWorkaround.processKeyEvent(evt);
		if(evt == null)
			return;

		dispatchProcessedKeyEvent(evt);

		if(!evt.isConsumed())
			super.processKeyEvent(evt);
	} //}}}

	//{{{ focusOwnerHasBinding() method
	/**
	 * Returns true if the focused component has a Swing input/action
	 * binding for the given key event.
	 */
	private boolean focusOwnerHasBinding(KeyEvent evt)
	{
		Component focusOwner = getFocusOwner();
		if(!(focusOwner instanceof JComponent))
			return false;

		JComponent comp = (JComponent)focusOwner;
		InputMap map = comp.getInputMap();
		ActionMap am = comp.getActionMap();

		if(map == null || am == null || !comp.isEnabled())
			return false;

		Object binding = map.get(KeyStroke.getKeyStrokeForEvent(evt));
		return binding != null && am.get(binding) != null;
	} //}}}

	//{{{ textComponentConsumesEvent() method
	/**
	 * Returns true if the focused text component handles this key event
	 * itself via a special key or its keymap.
	 */
	private boolean textComponentConsumesEvent(KeyEvent evt)
	{
		Component focusOwner = getFocusOwner();
		if(!(focusOwner instanceof JTextComponent))
			return false;

		if(evt.getID() == KeyEvent.KEY_PRESSED && isSpecialTextKey(evt))
			return true;

		Keymap keymap = ((JTextComponent)focusOwner).getKeymap();
		return keymap.getAction(KeyStroke.getKeyStrokeForEvent(evt)) != null;
	} //}}}

	//{{{ isSpecialTextKey() method
	/**
	 * Returns true if the key event is one of the special keys that
	 * text components always handle themselves.
	 */
	private boolean isSpecialTextKey(KeyEvent evt)
	{
		int keyCode = evt.getKeyCode();
		return keyCode == KeyEvent.VK_BACK_SPACE
			|| keyCode == KeyEvent.VK_TAB
			|| keyCode == KeyEvent.VK_ENTER;
	} //}}}

	//{{{ dispatchProcessedKeyEvent() method
	/**
	 * Dispatches a processed key event to the interceptor or input handler.
	 */
	private void dispatchProcessedKeyEvent(KeyEvent evt)
	{
		int index = evt.getID() - KeyEvent.KEY_TYPED;
		if(index >= 0 && index < keyEventProcessors.length)
		{
			KeyEventProcessor processor = keyEventProcessors[index];
			if(processor != null)
				processor.process(evt);
		}
	} //}}}

