calculateLinkArea:

private Rectangle2D calculateLinkArea(Rectangle2D plotArea) {
    double labelReserve = 0.0;
    if (this.labelGenerator != null && !this.simpleLabels) {
        labelReserve = this.labelGap + this.maximumLabelWidth;
    }
    double gapHorizontal = plotArea.getWidth() * labelReserve * 2.0;
    double gapVertical = plotArea.getHeight() * this.interiorGap * 2.0;
    double linkX = plotArea.getX() + gapHorizontal / 2;
    double linkY = plotArea.getY() + gapVertical / 2;
    double linkW = plotArea.getWidth() - gapHorizontal;
    double linkH = plotArea.getHeight() - gapVertical;
    if (this.circular) {
        double min = Math.min(linkW, linkH) / 2;
        linkX = (linkX + linkX + linkW) / 2 - min;
        linkY = (linkY + linkY + linkH) / 2 - min;
        linkW = 2 * min;
        linkH = 2 * min;
    }
    return new Rectangle2D.Double(linkX, linkY, linkW, linkH);
}

calculateExplodeArea:

private Rectangle2D calculateExplodeArea(Rectangle2D linkArea) {
    double lm = this.simpleLabels ? 0.0 : this.labelLinkMargin;
    double hh = linkArea.getWidth() * lm * 2.0;
    double vv = linkArea.getHeight() * lm * 2.0;
    return new Rectangle2D.Double(linkArea.getX() + hh / 2.0,
            linkArea.getY() + vv / 2.0, linkArea.getWidth() - hh,
            linkArea.getHeight() - vv);
}

