private void drawPieData(Graphics2D g2, Rectangle2D plotArea, Rectangle2D linkArea, Rectangle2D explodeArea, PiePlotState state) {
    if (this.dataset == null || this.dataset.getKeys().size() == 0) {
        drawNoDataMessage(g2, plotArea);
        return;
    }
    List keys = this.dataset.getKeys();
    double totalValue = DatasetUtilities.calculatePieDatasetTotal(this.dataset);
    int passesRequired = state.getPassesRequired();
    for (int pass = 0; pass < passesRequired; pass++) {
        drawPieSectionsForPass(g2, keys, explodeArea, state, pass);
    }
    if (this.simpleLabels) {
        drawSimpleLabels(g2, keys, totalValue, plotArea, linkArea, state);
    } else {
        drawLabels(g2, keys, totalValue, plotArea, linkArea, state);
    }
}

private void drawPieSectionsForPass(Graphics2D g2, List keys, Rectangle2D explodeArea, PiePlotState state, int pass) {
    double runningTotal = 0.0;
    for (int section = 0; section < keys.size(); section++) {
        Number n = this.dataset.getValue(section);
        if (n != null) {
            double value = n.doubleValue();
            if (value > 0.0) {
                runningTotal += value;
                drawItem(g2, section, explodeArea, state, pass);
            }
        }
    }
}

