private Point2D calculateExplodedCenter(PiePlotState state, Comparable key, double explodePercent) {
    Number n = this.dataset.getValue(key);
    double value = n.doubleValue();
    double[] angles = calculateSectionAngles(value, state);
    double angle1 = angles[0];
    double angle = angles[1] - angle1;
    Rectangle2D pieArea = state.getPieArea();
    Rectangle2D expPieArea = state.getExplodedPieArea();
    Arc2D arc1 = new Arc2D.Double(pieArea, angle1, angle / 2, Arc2D.OPEN);
    Point2D point1 = arc1.getEndPoint();
    Arc2D.Double arc2 = new Arc2D.Double(expPieArea, angle1, angle / 2, Arc2D.OPEN);
    Point2D point2 = arc2.getEndPoint();
    double deltaX = (point1.getX() - point2.getX()) * explodePercent;
    double deltaY = (point1.getY() - point2.getY()) * explodePercent;
    return new Point2D.Double(state.getPieCenterX() - deltaX,
            state.getPieCenterY() - deltaY);
}

