createLabelRecord:

private PieLabelRecord createLabelRecord(Comparable key, double midAngle,
        String label, Graphics2D g2, double verticalLinkRadius,
        double lGap, boolean leftSide, PiePlotState state,
        float maxLabelWidth) {
    TextBox labelBox = createLabelBox(g2, label, maxLabelWidth);
    double theta = Math.toRadians(midAngle);
    double baseY = state.getPieCenterY() - Math.sin(theta) * verticalLinkRadius;
    double hh = labelBox.getHeight(g2);
    double gap = lGap / 2.0 + lGap / 2.0
            * (leftSide ? -Math.cos(theta) : Math.cos(theta));
    double linkPercent = 1.0 - getLabelLinkDepth()
            + getExplodePercent(key);
    return new PieLabelRecord(key, theta, baseY, labelBox, hh, gap,
            linkPercent);
}

