protected void drawItem(Graphics2D g2, int section, Rectangle2D dataArea,
                        PiePlotState state, int currentPass) {
    Number n = this.dataset.getValue(section);
    if (n == null) {
        return;
    }
    double value = n.doubleValue();
    double[] angles = calculateSectionAngles(value, state);
    double angle1 = angles[0];
    double angle2 = angles[1];
    double angle = angle2 - angle1;
    if (Math.abs(angle) > getMinimumArcAngleToDraw()) {
        double explodePercent = calculateExplodePercentForSection(section);
        Rectangle2D arcBounds = getArcBounds(state.getPieArea(),
                state.getExplodedPieArea(), angle1, angle, explodePercent);
        Arc2D.Double arc = new Arc2D.Double(arcBounds, angle1, angle,
                Arc2D.PIE);
        drawItemPass(g2, section, arc, state, currentPass);
    }
    state.setLatestAngle(angle2);
}

private double[] calculateSectionAngles(double value, PiePlotState state) {
    double angle1 = state.getLatestAngle();
    double angle2;
    if (this.direction == Rotation.CLOCKWISE) {
        angle2 = angle1 - value / state.getTotal() * 360.0;
    } else if (this.direction == Rotation.ANTICLOCKWISE) {
        angle2 = angle1 + value / state.getTotal() * 360.0;
    } else {
        throw new IllegalStateException("Rotation type not recognised.");
    }
    return new double[] { angle1, angle2 };
}

private double calculateExplodePercentForSection(int section) {
    double ep = 0.0;
    double mep = getMaximumExplodePercent();
    if (mep > 0.0) {
        ep = getExplodePercent(section) / mep;
    }
    return ep;
}

private void drawItemPass(Graphics2D g2, int section, Arc2D.Double arc,
                          PiePlotState state, int currentPass) {
    if (currentPass == 0) {
        drawItemShadow(g2, arc);
    } else if (currentPass == 1) {
        drawItemSection(g2, section, arc, state);
    }
}

private void drawItemShadow(Graphics2D g2, Arc2D.Double arc) {
    if (this.shadowPaint != null && this.shadowGenerator == null) {
        Shape shadowArc = ShapeUtilities.createTranslatedShape(arc,
                (float) this.shadowXOffset, (float) this.shadowYOffset);
        g2.setPaint(this.shadowPaint);
        g2.fill(shadowArc);
    }
}

private void drawItemSection(Graphics2D g2, int section, Arc2D.Double arc,
                             PiePlotState state) {
    Comparable key = getSectionKey(section);
    Paint paint = lookupSectionPaint(key, state);
    g2.setPaint(paint);
    g2.fill(arc);
    if (this.sectionOutlinesVisible) {
        Paint outlinePaint = lookupSectionOutlinePaint(key);
        Stroke outlineStroke = lookupSectionOutlineStroke(key);
        g2.setPaint(outlinePaint);
        g2.setStroke(outlineStroke);
        g2.draw(arc);
    }
    addSectionEntity(g2, section, key, arc, state);
}

private void addSectionEntity(Graphics2D g2, int section, Comparable key,
                              Arc2D.Double arc, PiePlotState state) {
    if (state.getInfo() != null) {
        EntityCollection entities = state.getEntityCollection();
        if (entities != null) {
            String tip = null;
            if (this.toolTipGenerator != null) {
                tip = this.toolTipGenerator.generateToolTip(this.dataset, key);
            }
            String url = null;
            if (this.urlGenerator != null) {
                url = this.urlGenerator.generateURL(this.dataset, key,
                        this.pieIndex);
            }
            PieSectionEntity entity = new PieSectionEntity(arc,
                    this.dataset, this.pieIndex, section, key, tip, url);
            entities.add(entity);
        }
    }
}

