protected void drawSimpleLabels(Graphics2D g2, List keys,
        double totalValue, Rectangle2D plotArea, Rectangle2D pieArea,
        PiePlotState state) {
    Composite originalComposite = g2.getComposite();
    g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER,
            1.0f));
    Rectangle2D labelsArea = this.simpleLabelOffset.createInsetRectangle(
            pieArea);
    double runningTotal = 0.0;
    Iterator iterator = keys.iterator();
    while (iterator.hasNext()) {
        Comparable key = (Comparable) iterator.next();
        double v = getSectionValue(key);
        if (!includeSection(v)) {
            continue;
        }
        runningTotal += v;
        Point2D point = calculateSimpleLabelPoint(labelsArea, runningTotal,
                v, totalValue);
        drawSimpleLabel(g2, key, point);
    }
    g2.setComposite(originalComposite);
}

private double getSectionValue(Comparable key) {
    Number n = this.dataset.getValue(key);
    return n == null ? Double.NaN : n.doubleValue();
}

private boolean includeSection(double value) {
    if (Double.isNaN(value)) {
        return !getIgnoreNullValues();
    }
    return getIgnoreZeroValues() ? value > 0.0 : value >= 0.0;
}

private Point2D calculateSimpleLabelPoint(Rectangle2D labelsArea,
        double runningTotal, double value, double totalValue) {
    double mid = getStartAngle() + (getDirection().getFactor()
            * ((runningTotal - value / 2.0) * 360) / totalValue);
    Arc2D arc = new Arc2D.Double(labelsArea, getStartAngle(),
            mid - getStartAngle(), Arc2D.OPEN);
    return arc.getEndPoint();
}

private void drawSimpleLabel(Graphics2D g2, Comparable key, Point2D point) {
    PieSectionLabelGenerator myLabelGenerator = getLabelGenerator();
    if (myLabelGenerator == null) {
        return;
    }
    String label = myLabelGenerator.generateSectionLabel(this.dataset, key);
    if (label == null) {
        return;
    }
    g2.setFont(this.labelFont);
    FontMetrics fm = g2.getFontMetrics();
    Rectangle2D bounds = TextUtilities.getTextBounds(label, g2, fm);
    Rectangle2D out = this.labelPadding.createOutsetRectangle(bounds);
    Shape bg = ShapeUtilities.createTranslatedShape(out,
            point.getX() - bounds.getCenterX(),
            point.getY() - bounds.getCenterY());
    drawSimpleLabelBackground(g2, bg);
    g2.setPaint(this.labelPaint);
    g2.setFont(this.labelFont);
    TextUtilities.drawAlignedString(label, g2, (int) point.getX(),
            (int) point.getY(), TextAnchor.CENTER);
}

private void drawSimpleLabelBackground(Graphics2D g2, Shape bg) {
    if (this.labelShadowPaint != null && this.shadowGenerator == null) {
        Shape shadow = ShapeUtilities.createTranslatedShape(bg,
                this.shadowXOffset, this.shadowYOffset);
        g2.setPaint(this.labelShadowPaint);
        g2.fill(shadow);
    }
    if (this.labelBackgroundPaint != null) {
        g2.setPaint(this.labelBackgroundPaint);
        g2.fill(bg);
    }
    if (this.labelOutlinePaint != null
            && this.labelOutlineStroke != null) {
        g2.setPaint(this.labelOutlinePaint);
        g2.setStroke(this.labelOutlineStroke);
        g2.draw(bg);
    }
}

