protected void drawLabels(Graphics2D g2, List keys, double totalValue,
                          Rectangle2D plotArea, Rectangle2D linkArea,
                          PiePlotState state) {
    Composite originalComposite = g2.getComposite();
    g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER,
            1.0f));
    DefaultKeyedValues leftKeys = new DefaultKeyedValues();
    DefaultKeyedValues rightKeys = new DefaultKeyedValues();
    classifyKeys(keys, totalValue, leftKeys, rightKeys);
    g2.setFont(getLabelFont());
    float labelWidth = (float) calculateMaxLabelWidth(plotArea, linkArea);
    if (this.labelGenerator != null) {
        drawLeftLabels(leftKeys, g2, plotArea, linkArea, labelWidth, state);
        drawRightLabels(rightKeys, g2, plotArea, linkArea, labelWidth, state);
    }
    g2.setComposite(originalComposite);
}

private void classifyKeys(List keys, double totalValue,
        DefaultKeyedValues leftKeys, DefaultKeyedValues rightKeys) {
    double runningTotal = 0.0;
    Iterator iterator = keys.iterator();
    while (iterator.hasNext()) {
        Comparable key = (Comparable) iterator.next();
        double v = getSectionValue(key);
        if (!includeSection(v)) {
            continue;
        }
        runningTotal += v;
        double mid = this.startAngle + (this.direction.getFactor()
                * ((runningTotal - v / 2.0) * 360) / totalValue);
        if (Math.cos(Math.toRadians(mid)) < 0.0) {
            leftKeys.addValue(key, new Double(mid));
        } else {
            rightKeys.addValue(key, new Double(mid));
        }
    }
}

private double calculateMaxLabelWidth(Rectangle2D plotArea,
        Rectangle2D linkArea) {
    double marginX = plotArea.getX();
    double gap = plotArea.getWidth() * this.labelGap;
    double ww = linkArea.getX() - gap - marginX;
    return this.labelPadding.trimWidth(ww);
}

