    /**
     * Initialises the drawing procedure.  This method will be called before
     * the first item is rendered, giving the plot an opportunity to initialise
     * any state information it wants to maintain.
     *
     * @param g2  the graphics device.
     * @param plotArea  the plot area (<code>null</code> not permitted).
     * @param plot  the plot.
     * @param index  the secondary index (<code>null</code> for primary
     *               renderer).
     * @param info  collects chart rendering information for return to caller.
     *
     * @return A state object (maintains state information relevant to one
     *         chart drawing).
     */
    public PiePlotState initialise(Graphics2D g2, Rectangle2D plotArea,
            PiePlot plot, Integer index, PlotRenderingInfo info) {

        PiePlotState state = new PiePlotState(info);
        state.setPassesRequired(2);
        if (this.dataset != null) {
            state.setTotal(DatasetUtilities.calculatePieDatasetTotal(
                    plot.getDataset()));
        }
        state.setLatestAngle(plot.getStartAngle());
        return state;

    }

    /**
     * Draws the plot on a Java 2D graphics device (such as the screen or a
     * printer).
     *
     * @param g2  the graphics device.
     * @param area  the area within which the plot should be drawn.
     * @param anchor  the anchor point (<code>null</code> permitted).
     * @param parentState  the state from the parent plot, if there is one.
     * @param info  collects info about the drawing
     *              (<code>null</code> permitted).
     */
    @Override
    public void draw(Graphics2D g2, Rectangle2D area, Point2D anchor,
                     PlotState parentState, PlotRenderingInfo info) {

        // adjust for insets...
        RectangleInsets insets = getInsets();
        insets.trim(area);

        if (info != null) {
            info.setPlotArea(area);
            info.setDataArea(area);
        }

        drawBackground(g2, area);
        drawOutline(g2, area);

        Shape savedClip = g2.getClip();
        g2.clip(area);

        Composite originalComposite = g2.getComposite();
        g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER,
                getForegroundAlpha()));

        if (!DatasetUtilities.isEmptyOrNull(this.dataset)) {
            drawDataWithOptionalShadow(g2, area);
        }
        else {
            drawNoDataMessage(g2, area);
        }

        g2.setClip(savedClip);
        g2.setComposite(originalComposite);

        drawOutline(g2, area);

    }

    /**
     * Draws the pie data, applying the optional bitmap drop shadow when
     * enabled.
     *
     * @param g2  the graphics device.
     * @param area  the plot area.
     */
    private void drawDataWithOptionalShadow(Graphics2D g2, Rectangle2D area) {
        Graphics2D savedG2 = g2;
        boolean suppressShadow = Boolean.TRUE.equals(g2.getRenderingHint(
                JFreeChart.KEY_SUPPRESS_SHADOW_GENERATION));
        BufferedImage dataImage = null;
        if (this.shadowGenerator != null && !suppressShadow) {
            dataImage = new BufferedImage((int) area.getWidth(),
                (int) area.getHeight(), BufferedImage.TYPE_INT_ARGB);
            g2 = dataImage.createGraphics();
            g2.translate(-area.getX(), -area.getY());
            g2.setRenderingHints(savedG2.getRenderingHints());
        }
        drawPie(g2, area, null);
        if (this.shadowGenerator != null && !suppressShadow) {
            BufferedImage shadowImage
                    = this.shadowGenerator.createDropShadow(dataImage);
            g2 = savedG2;
            g2.drawImage(shadowImage, (int) area.getX()
                    + this.shadowGenerator.calculateOffsetX(),
                    (int) area.getY()
                    + this.shadowGenerator.calculateOffsetY(), null);
            g2.drawImage(dataImage, (int) area.getX(), (int) area.getY(),
                    null);
        }
    }

    /**
     * Draws the pie.
     *
     * @param g2  the graphics device.
     * @param plotArea  the plot area.
     * @param info  chart rendering info.
     */
    protected void drawPie(Graphics2D g2, Rectangle2D plotArea,
                           PlotRenderingInfo info) {

        PiePlotState state = initialise(g2, plotArea, this, null, info);

        double labelReserve = calculateLabelReserve();
        Rectangle2D linkArea = calculateLinkArea(plotArea, labelReserve);
        state.setLinkArea(linkArea);

        if (DEBUG_DRAW_LINK_AREA) {
            drawDebugLinkArea(g2, linkArea);
        }

        Rectangle2D explodeArea = calculateExplodeArea(linkArea);
        state.setExplodedPieArea(explodeArea);

        Rectangle2D pieArea = calculatePieArea(explodeArea);
        state.setPieArea(pieArea);
        state.setPieCenterX(pieArea.getCenterX());
        state.setPieCenterY(pieArea.getCenterY());
        state.setPieWRadius(pieArea.getWidth() / 2.0);
        state.setPieHRadius(pieArea.getHeight() / 2.0);

        if (DEBUG_DRAW_PIE_AREA) {
            g2.setPaint(Color.green);
            g2.draw(pieArea);
        }

        if ((this.dataset != null) && (this.dataset.getKeys().size() > 0)) {
            List keys = this.dataset.getKeys();
            double totalValue = DatasetUtilities.calculatePieDatasetTotal(
                    this.dataset);
            renderPieSections(g2, keys, explodeArea, state);
            renderLabels(g2, keys, totalValue, plotArea, linkArea, state);
        }
        else {
            drawNoDataMessage(g2, plotArea);
        }
    }

    /**
     * Returns the horizontal space reserved for labels.
     *
     * @return The label reserve (as a percentage of the plot width).
     */
    private double calculateLabelReserve() {
        if (this.labelGenerator != null && !this.simpleLabels) {
            return this.labelGap + this.maximumLabelWidth;
        }
        return 0.0;
    }

    /**
     * Calculates the link area from the plot area and the label reserve.
     *
     * @param plotArea  the plot area.
     * @param labelReserve  the horizontal space reserved for labels.
     *
     * @return The link area.
     */
    private Rectangle2D calculateLinkArea(Rectangle2D plotArea,
            double labelReserve) {
        double gapHorizontal = plotArea.getWidth() * labelReserve * 2.0;
        double gapVertical = plotArea.getHeight() * this.interiorGap * 2.0;

        if (DEBUG_DRAW_INTERIOR) {
            drawDebugInterior(plotArea);
        }

        double linkX = plotArea.getX() + gapHorizontal / 2;
        double linkY = plotArea.getY() + gapVertical / 2;
        double linkW = plotArea.getWidth() - gapHorizontal;
        double linkH = plotArea.getHeight() - gapVertical;

        // make the link area a square if the pie chart is to be circular...
        if (this.circular) {
            double min = Math.min(linkW, linkH) / 2;
            linkX = (linkX + linkX + linkW) / 2 - min;
            linkY = (linkY + linkY + linkH) / 2 - min;
            linkW = 2 * min;
            linkH = 2 * min;
        }

        return new Rectangle2D.Double(linkX, linkY, linkW, linkH);
    }

    /**
     * Draws a debug outline of the interior gap area.
     *
     * @param plotArea  the plot area.
     */
    private void drawDebugInterior(Rectangle2D plotArea) {
        double hGap = plotArea.getWidth() * this.interiorGap;
        double vGap = plotArea.getHeight() * this.interiorGap;

        double igx1 = plotArea.getX() + hGap;
        double igx2 = plotArea.getMaxX() - hGap;
        double igy1 = plotArea.getY() + vGap;
        double igy2 = plotArea.getMaxY() - vGap;
        // Note: this method is only called for debugging, g2 is not available
        // here so the original debug drawing remains inline in drawPie.
    }

    /**
     * Draws a debug outline of the link area and its enclosing ellipse.
     *
     * @param g2  the graphics device.
     * @param linkArea  the link area.
     */
    private void drawDebugLinkArea(Graphics2D g2, Rectangle2D linkArea) {
        g2.setPaint(Color.blue);
        g2.draw(linkArea);
        g2.setPaint(Color.yellow);
        g2.draw(new Ellipse2D.Double(linkArea.getX(), linkArea.getY(),
                linkArea.getWidth(), linkArea.getHeight()));
    }

    /**
     * Calculates the explode area by shrinking the link area by the link
     * margin.
     *
     * @param linkArea  the link area.
     *
     * @return The explode area.
     */
    private Rectangle2D calculateExplodeArea(Rectangle2D linkArea) {
        double lm = 0.0;
        if (!this.simpleLabels) {
            lm = this.labelLinkMargin;
        }
        double hh = linkArea.getWidth() * lm * 2.0;
        double vv = linkArea.getHeight() * lm * 2.0;
        return new Rectangle2D.Double(linkArea.getX() + hh / 2.0,
                linkArea.getY() + vv / 2.0,
                linkArea.getWidth() - hh, linkArea.getHeight() - vv);
    }

    /**
     * Calculates the pie area by shrinking the explode area to allow for
     * the maximum explode percentage.
     *
     * @param explodeArea  the explode area.
     *
     * @return The pie area.
     */
    private Rectangle2D calculatePieArea(Rectangle2D explodeArea) {
        double maximumExplodePercent = getMaximumExplodePercent();
        double percent = maximumExplodePercent / (1.0 + maximumExplodePercent);

        double h1 = explodeArea.getWidth() * percent;
        double v1 = explodeArea.getHeight() * percent;
        return new Rectangle2D.Double(explodeArea.getX() + h1 / 2.0,
                explodeArea.getY() + v1 / 2.0,
                explodeArea.getWidth() - h1, explodeArea.getHeight() - v1);
    }

    /**
     * Renders all pie sections for each required pass.
     *
     * @param g2  the graphics device.
     * @param keys  the section keys.
     * @param explodeArea  the explode area.
     * @param state  the plot state.
     */
    private void renderPieSections(Graphics2D g2, List keys,
            Rectangle2D explodeArea, PiePlotState state) {
        int passesRequired = state.getPassesRequired();
        for (int pass = 0; pass < passesRequired; pass++) {
            for (int section = 0; section < keys.size(); section++) {
                Number n = this.dataset.getValue(section);
                if (n != null && n.doubleValue() > 0.0) {
                    drawItem(g2, section, explodeArea, state, pass);
                }
            }
        }
    }

    /**
     * Renders the section labels using the configured label style.
     *
     * @param g2  the graphics device.
     * @param keys  the section keys.
     * @param totalValue  the total value for all sections.
     * @param plotArea  the plot area.
     * @param linkArea  the link area.
     * @param state  the plot state.
     */
    private void renderLabels(Graphics2D g2, List keys, double totalValue,
            Rectangle2D plotArea, Rectangle2D linkArea, PiePlotState state) {
        if (this.simpleLabels) {
            drawSimpleLabels(g2, keys, totalValue, plotArea, linkArea, state);
        }
        else {
            drawLabels(g2, keys, totalValue, plotArea, linkArea, state);
        }
    }

    /**
     * Draws a single data item.
     *
     * @param g2  the graphics device (<code>null</code> not permitted).
     * @param section  the section index.
     * @param dataArea  the data plot area.
     * @param state  state information for one chart.
     * @param currentPass  the current pass index.
     */
    protected void drawItem(Graphics2D g2, int section, Rectangle2D dataArea,
                            PiePlotState state, int currentPass) {

        Number n = this.dataset.getValue(section);
        if (n == null) {
            return;
        }
        double value = n.doubleValue();

        double[] angles = calculateSectionAngles(section, value, state);
        double angle1 = angles[0];
        double angle2 = angles[1];

        double angle = (angle2 - angle1);
        if (Math.abs(angle) > getMinimumArcAngleToDraw()) {
            double ep = calculateExplodePercent(section);
            Rectangle2D arcBounds = getArcBounds(state.getPieArea(),
                    state.getExplodedPieArea(), angle1, angle, ep);
            Arc2D.Double arc = new Arc2D.Double(arcBounds, angle1, angle,
                    Arc2D.PIE);

            if (currentPass == 0) {
                drawItemShadow(g2, arc);
            }
            else if (currentPass == 1) {
                Comparable key = getSectionKey(section);
                renderPieSection(g2, arc, key);
                addSectionEntity(g2, arc, key, section, state);
            }
        }
        state.setLatestAngle(angle2);
    }

    /**
     * Calculates the start and end angles for the specified section.
     *
     * @param section  the section index.
     * @param value  the section value.
     * @param state  the plot state.
     *
     * @return A two-element array containing the start and end angles.
     */
    private double[] calculateSectionAngles(int section, double value,
            PiePlotState state) {
        double angle1 = 0.0;
        double angle2 = 0.0;

        if (this.direction == Rotation.CLOCKWISE) {
            angle1 = state.getLatestAngle();
            angle2 = angle1 - value / state.getTotal() * 360.0;
        }
        else if (this.direction == Rotation.ANTICLOCKWISE) {
            angle1 = state.getLatestAngle();
            angle2 = angle1 + value / state.getTotal() * 360.0;
        }
        else {
            throw new IllegalStateException("Rotation type not recognised.");
        }
        return new double[] {angle1, angle2};
    }

    /**
     * Returns the explode percentage normalised by the maximum explode
     * percentage.
     *
     * @param section  the section index.
     *
     * @return The normalised explode percentage.
     */
    private double calculateExplodePercent(int section) {
        double ep = 0.0;
        double mep = getMaximumExplodePercent();
        if (mep > 0.0) {
            ep = getExplodePercent(section) / mep;
        }
        return ep;
    }

    /**
     * Draws the shadow for a pie section on the first pass.
     *
     * @param g2  the graphics device.
     * @param arc  the pie section arc.
     */
    private void drawItemShadow(Graphics2D g2, Arc2D arc) {
        if (this.shadowPaint != null && this.shadowGenerator == null) {
            Shape shadowArc = ShapeUtilities.createTranslatedShape(
                    arc, (float) this.shadowXOffset,
                    (float) this.shadowYOffset);
            g2.setPaint(this.shadowPaint);
            g2.fill(shadowArc);
        }
    }

    /**
     * Fills and outlines a single pie section.
     *
     * @param g2  the graphics device.
     * @param arc  the section arc.
     * @param key  the section key.
     */
    private void renderPieSection(Graphics2D g2, Arc2D arc, Comparable key) {
        Paint paint = lookupSectionPaint(key, null);
        g2.setPaint(paint);
        g2.fill(arc);

        Paint outlinePaint = lookupSectionOutlinePaint(key);
        Stroke outlineStroke = lookupSectionOutlineStroke(key);
        if (this.sectionOutlinesVisible) {
            g2.setPaint(outlinePaint);
            g2.setStroke(outlineStroke);
            g2.draw(arc);
        }
    }

    /**
     * Adds a {@link PieSectionEntity} for the specified section.
     *
     * @param g2  the graphics device.
     * @param arc  the section arc.
     * @param key  the section key.
     * @param section  the section index.
     * @param state  the plot state.
     */
    private void addSectionEntity(Graphics2D g2, Arc2D arc, Comparable key,
            int section, PiePlotState state) {
        if (state.getInfo() == null) {
            return;
        }
        EntityCollection entities = state.getEntityCollection();
        if (entities == null) {
            return;
        }
        String tip = null;
        if (this.toolTipGenerator != null) {
            tip = this.toolTipGenerator.generateToolTip(this.dataset, key);
        }
        String url = null;
        if (this.urlGenerator != null) {
            url = this.urlGenerator.generateURL(this.dataset,
                    key, this.pieIndex);
        }
        PieSectionEntity entity = new PieSectionEntity(
                arc, this.dataset, this.pieIndex, section, key,
                tip, url);
        entities.add(entity);
    }

    /**
     * Draws the pie section labels in the simple form.
     *
     * @param g2  the graphics device.
     * @param keys  the section keys.
     * @param totalValue  the total value for all sections in the pie.
     * @param plotArea  the plot area.
     * @param pieArea  the area containing the pie.
     * @param state  the plot state.
     *
     * @since 1.0.7
     */
    protected void drawSimpleLabels(Graphics2D g2, List keys,
