                    LegendItem item = createLegendItem(key, shape, label);
                    item.setDataset(getDataset());
                    item.setSeriesIndex(this.dataset.getIndex(key));
                    item.setSeriesKey(key);
                    result.add(item);
                }
            }
            section++;
