    /**
     * Strategy interface for rendering the line that connects a pie section to
     * its label.
     */
    private interface PieLabelLinkRenderer {

        /**
         * Draws the link line for a single label.
         *
         * @param g2  the graphics device.
         * @param linkX  the link x-coordinate.
         * @param linkY  the link y-coordinate.
         * @param elbowX  the elbow x-coordinate.
         * @param elbowY  the elbow y-coordinate.
         * @param anchorX  the anchor x-coordinate.
         * @param anchorY  the anchor y-coordinate.
         * @param targetX  the target x-coordinate.
         * @param targetY  the target y-coordinate.
         */
        void drawLink(Graphics2D g2, double linkX, double linkY,
                double elbowX, double elbowY, double anchorX,
                double anchorY, double targetX, double targetY);
    }

    /**
     * A lookup table that maps each label link style to the object that
     * renders it.
     */
    private static final Map<PieLabelLinkStyle, PieLabelLinkRenderer>
            LINK_RENDERERS = new TreeMap<PieLabelLinkStyle, PieLabelLinkRenderer>();

    static {
        LINK_RENDERERS.put(PieLabelLinkStyle.STANDARD,
                new PieLabelLinkRenderer() {
            public void drawLink(Graphics2D g2, double linkX, double linkY,
                    double elbowX, double elbowY, double anchorX,
                    double anchorY, double targetX, double targetY) {
                g2.draw(new Line2D.Double(linkX, linkY, elbowX, elbowY));
                g2.draw(new Line2D.Double(anchorX, anchorY, elbowX, elbowY));
                g2.draw(new Line2D.Double(anchorX, anchorY, targetX, targetY));
            }
        });
        LINK_RENDERERS.put(PieLabelLinkStyle.QUAD_CURVE,
                new PieLabelLinkRenderer() {
            public void drawLink(Graphics2D g2, double linkX, double linkY,
                    double elbowX, double elbowY, double anchorX,
                    double anchorY, double targetX, double targetY) {
                QuadCurve2D q = new QuadCurve2D.Float();
                q.setCurve(targetX, targetY, anchorX, anchorY, elbowX, elbowY);
                g2.draw(q);
                g2.draw(new Line2D.Double(elbowX, elbowY, linkX, linkY));
            }
        });
        LINK_RENDERERS.put(PieLabelLinkStyle.CUBIC_CURVE,
                new PieLabelLinkRenderer() {
            public void drawLink(Graphics2D g2, double linkX, double linkY,
                    double elbowX, double elbowY, double anchorX,
                    double anchorY, double targetX, double targetY) {
                CubicCurve2D c = new CubicCurve2D.Float();
                c.setCurve(targetX, targetY, anchorX, anchorY, elbowX, elbowY,
                        linkX, linkY);
                g2.draw(c);
            }
        });
    }

