/**
 * Returns <code>true</code> if the section with the given value should be
 * included when drawing labels or legend items.
 *
 * @param n  the section value (<code>null</code> permitted).
 *
 * @return A boolean.
 */
private boolean isSectionIncluded(Number n) {
    if (n == null) {
        return !getIgnoreNullValues();
    }
    double v = n.doubleValue();
    return getIgnoreZeroValues() ? v > 0.0 : v >= 0.0;
}

/**
 * Creates a label box for the specified label.
 *
 * @param label  the label.
 * @param g2  the graphics device.
 * @param maxLabelWidth  the maximum label width.
 *
 * @return A label box.
 */
private TextBox createLabelBox(String label, Graphics2D g2,
        float maxLabelWidth) {
    TextBlock block = TextUtilities.createTextBlock(label, this.labelFont,
            this.labelPaint, maxLabelWidth, new G2TextMeasurer(g2));
    TextBox labelBox = new TextBox(block);
    labelBox.setBackgroundPaint(this.labelBackgroundPaint);
    labelBox.setOutlinePaint(this.labelOutlinePaint);
    labelBox.setOutlineStroke(this.labelOutlineStroke);
    if (this.shadowGenerator == null) {
        labelBox.setShadowPaint(this.labelShadowPaint);
    }
    else {
        labelBox.setShadowPaint(null);
    }
    labelBox.setInteriorGap(this.labelPadding);
    return labelBox;
}

/**
 * Copies the mutable state from the specified source plot into this plot.
 *
 * @param source  the source plot (<code>null</code> not permitted).
 *
 * @throws CloneNotSupportedException if some component does not support
 *         cloning.
 */
private void copyFrom(PiePlot source) throws CloneNotSupportedException {
    this.sectionPaintMap = (PaintMap) source.sectionPaintMap.clone();
    this.sectionOutlinePaintMap = (PaintMap) source.sectionOutlinePaintMap.clone();
    this.sectionOutlineStrokeMap = (StrokeMap) source.sectionOutlineStrokeMap.clone();
    this.explodePercentages = new TreeMap<Comparable<?>, Number>(
            source.explodePercentages);
    if (source.labelGenerator != null) {
        this.labelGenerator = (PieSectionLabelGenerator)
                ObjectUtilities.clone(source.labelGenerator);
    }
    if (this.dataset != null) {
        this.dataset.addChangeListener(this);
    }
    if (source.urlGenerator instanceof PublicCloneable) {
        this.urlGenerator = (PieURLGenerator)
                ObjectUtilities.clone(source.urlGenerator);
    }
    this.legendItemShape = ShapeUtilities.clone(source.legendItemShape);
    if (source.legendLabelGenerator != null) {
        this.legendLabelGenerator = (PieSectionLabelGenerator)
                ObjectUtilities.clone(source.legendLabelGenerator);
    }
    if (source.legendLabelToolTipGenerator != null) {
        this.legendLabelToolTipGenerator = (PieSectionLabelGenerator)
                ObjectUtilities.clone(source.legendLabelToolTipGenerator);
    }
    if (source.legendLabelURLGenerator instanceof PublicCloneable) {
        this.legendLabelURLGenerator = (PieURLGenerator)
                ObjectUtilities.clone(source.legendLabelURLGenerator);
    }
}

