    /**
     * Strategy for drawing the path that links a pie section to its label.
     */
    private interface LinkPathStrategy {

        /**
         * Draws the link path for a single label.
         *
         * @param g2  the graphics device.
         * @param linkX  the link x-coordinate.
         * @param linkY  the link y-coordinate.
         * @param elbowX  the elbow x-coordinate.
         * @param elbowY  the elbow y-coordinate.
         * @param anchorX  the anchor x-coordinate.
         * @param anchorY  the anchor y-coordinate.
         * @param targetX  the target x-coordinate.
         * @param targetY  the target y-coordinate.
         */
        void drawLink(Graphics2D g2, double linkX, double linkY,
                double elbowX, double elbowY, double anchorX, double anchorY,
                double targetX, double targetY);
    }

    /**
     * Standard straight-line link path.
     */
    private static final class StandardLinkPathStrategy implements
            LinkPathStrategy, Serializable {

        /** For serialization. */
        private static final long serialVersionUID = 1L;

        /**
         * {@inheritDoc}
         */
        @Override
        public void drawLink(Graphics2D g2, double linkX, double linkY,
                double elbowX, double elbowY, double anchorX, double anchorY,
                double targetX, double targetY) {
            g2.draw(new Line2D.Double(linkX, linkY, elbowX, elbowY));
            g2.draw(new Line2D.Double(anchorX, anchorY, elbowX, elbowY));
            g2.draw(new Line2D.Double(anchorX, anchorY, targetX, targetY));
        }
    }

    /**
     * Quad-curve link path.
     */
    private static final class QuadCurveLinkPathStrategy implements
            LinkPathStrategy, Serializable {

        /** For serialization. */
        private static final long serialVersionUID = 1L;

        /**
         * {@inheritDoc}
         */
        @Override
        public void drawLink(Graphics2D g2, double linkX, double linkY,
                double elbowX, double elbowY, double anchorX, double anchorY,
                double targetX, double targetY) {
            QuadCurve2D q = new QuadCurve2D.Float();
            q.setCurve(targetX, targetY, anchorX, anchorY, elbowX, elbowY);
            g2.draw(q);
            g2.draw(new Line2D.Double(elbowX, elbowY, linkX, linkY));
        }
    }

    /**
     * Cubic-curve link path.
     */
    private static final class CubicCurveLinkPathStrategy implements
            LinkPathStrategy, Serializable {

        /** For serialization. */
        private static final long serialVersionUID = 1L;

        /**
         * {@inheritDoc}
         */
        @Override
        public void drawLink(Graphics2D g2, double linkX, double linkY,
                double elbowX, double elbowY, double anchorX, double anchorY,
                double targetX, double targetY) {
            CubicCurve2D c = new CubicCurve2D.Float();
            c.setCurve(targetX, targetY, anchorX, anchorY, elbowX, elbowY,
                    linkX, linkY);
            g2.draw(c);
        }
    }

    /** Lookup table that maps label link styles to drawing strategies. */
    private static final Map<PieLabelLinkStyle, LinkPathStrategy>
            LINK_STYLE_STRATEGIES;
    static {
        Map<PieLabelLinkStyle, LinkPathStrategy> map
                = new java.util.HashMap<PieLabelLinkStyle, LinkPathStrategy>();
        map.put(PieLabelLinkStyle.STANDARD, new StandardLinkPathStrategy());
        map.put(PieLabelLinkStyle.QUAD_CURVE, new QuadCurveLinkPathStrategy());
        map.put(PieLabelLinkStyle.CUBIC_CURVE,
                new CubicCurveLinkPathStrategy());
        LINK_STYLE_STRATEGIES = java.util.Collections.unmodifiableMap(map);
    }

