    /**
     * Determines whether the section with the given value should be included
     * in the rendered pie, taking into account the ignore-null and
     * ignore-zero settings.
     *
     * @param value  the section value (<code>null</code> permitted).
     *
     * @return The inclusion result.
     */
    private SectionInclusion evaluateSectionInclusion(Number value) {
        if (value == null) {
            return new SectionInclusion(!this.ignoreNullValues, 0.0);
        }
        double v = value.doubleValue();
        return new SectionInclusion(this.ignoreZeroValues ? v > 0.0 : v >= 0.0, v);
    }

