     * Draws a section label on the specified side of the pie chart.
     *
     * @param g2  the graphics device.
     * @param state  the state.
     * @param record  the label record.
     * @param left  <code>true</code> for the left side, <code>false</code> for
     *              the right side.
     */
    private void drawSideLabel(Graphics2D g2, PiePlotState state,
            PieLabelRecord record, boolean left) {
        Rectangle2D linkArea = state.getLinkArea();
        double anchorX = left ? linkArea.getMinX() : linkArea.getMaxX();
        double targetX = left ? anchorX - record.getGap()
                : anchorX + record.getGap();
        double targetY = record.getAllocatedY();
        RectangleAnchor anchor = left ? RectangleAnchor.RIGHT
                : RectangleAnchor.LEFT;

        if (this.labelLinksVisible) {
            double theta = record.getAngle();
            double linkX = state.getPieCenterX() + Math.cos(theta)
                    * state.getPieWRadius() * record.getLinkPercent();
            double linkY = state.getPieCenterY() - Math.sin(theta)
                    * state.getPieHRadius() * record.getLinkPercent();
            double elbowX = state.getPieCenterX() + Math.cos(theta)
                    * linkArea.getWidth() / 2.0;
            double elbowY = state.getPieCenterY() - Math.sin(theta)
                    * linkArea.getHeight() / 2.0;
            double anchorY = elbowY;
            g2.setPaint(this.labelLinkPaint);
            g2.setStroke(this.labelLinkStroke);
            PieLabelLinkRenderer renderer = LABEL_LINK_RENDERERS.get(
                    getLabelLinkStyle());
            if (renderer != null) {
                renderer.drawLink(g2, linkX, linkY, elbowX, elbowY,
                        anchorX, anchorY, targetX, targetY);
            }
        }

        TextBox tb = record.getLabel();
        tb.draw(g2, (float) targetX, (float) targetY, anchor);
    }

