    private Paint adjustRadialGradientPaint(Paint paint, PiePlotState state,
            Comparable key) {
        if (paint instanceof RadialGradientPaint) {
            RadialGradientPaint rgp = (RadialGradientPaint) paint;
            Point2D center = getArcCenter(state, key);
            float radius = (float) Math.max(state.getPieHRadius(),
                    state.getPieWRadius());
            float[] fractions = rgp.getFractions();
            Color[] colors = rgp.getColors();
            return new RadialGradientPaint(center, radius, fractions, colors);
        }
        return paint;
    }

