    /**
     * Tests geometric and directional attributes for equality.
     *
     * @param that  the other plot.
     *
     * @return <code>true</code> if equal.
     */
    private boolean equalGeometry(PiePlot that) {
        if (this.pieIndex != that.pieIndex) {
            return false;
        }
        if (this.interiorGap != that.interiorGap) {
            return false;
        }
        if (this.circular != that.circular) {
            return false;
        }
        if (this.startAngle != that.startAngle) {
            return false;
        }
        if (this.direction != that.direction) {
            return false;
        }
        if (this.ignoreZeroValues != that.ignoreZeroValues) {
            return false;
        }
        if (this.ignoreNullValues != that.ignoreNullValues) {
            return false;
        }
        return true;
    }

    /**
     * Tests section paint attributes for equality.
     *
     * @param that  the other plot.
     *
     * @return <code>true</code> if equal.
     */
    private boolean equalSectionPaints(PiePlot that) {
        if (!PaintUtilities.equal(this.sectionPaint, that.sectionPaint)) {
            return false;
        }
        if (!ObjectUtilities.equal(this.sectionPaintMap, that.sectionPaintMap)) {
            return false;
        }
        if (!PaintUtilities.equal(this.baseSectionPaint,
                that.baseSectionPaint)) {
            return false;
        }
        return true;
    }

