     * @param overlay  the overlay to remove (<code>null</code> not permitted).
     *
     * @since 1.0.13
     */
    public void removeOverlay(Overlay overlay) {
        ParamChecks.nullNotPermitted(overlay, "overlay");
        boolean removed = this.overlays.remove(overlay);
        if (removed) {
            overlay.removeChangeListener(this);
            repaint();
        }
    }

    /**
     * Handles a change to an overlay by repainting the panel.
     *
     * @param event  the event.
     *
     * @since 1.0.13
     */
    @Override
    public void overlayChanged(OverlayChangeEvent event) {
        repaint();
    }

    /**
     * Switches the display of tooltips for the panel on or off.  Note that
     * tooltips can only be displayed if the chart has been configured to
     * generate tooltip items.
     *
     * @param flag  <code>true</code> to enable tooltips, <code>false</code> to
     *              disable tooltips.
     */
    public void setDisplayToolTips(boolean flag) {
        if (flag) {
            ToolTipManager.sharedInstance().registerComponent(this);
        }
        else {
            ToolTipManager.sharedInstance().unregisterComponent(this);
        }
    }

    /**
     * Returns a string for the tooltip.
     *
     * @param e  the mouse event.
     *
     * @return A tool tip or <code>null</code> if no tooltip is available.
     */
    @Override
    public String getToolTipText(MouseEvent e) {
        String result = null;
        if (this.info != null) {
            EntityCollection entities = this.info.getEntityCollection();
            if (entities != null) {
                Insets insets = getInsets();
                ChartEntity entity = entities.getEntity(
                        (int) ((e.getX() - insets.left) / this.scaleX),
                        (int) ((e.getY() - insets.top) / this.scaleY));
                if (entity != null) {
                    result = entity.getToolTipText();
                }
            }
        }
        return result;
    }

    /**
     * Translates a Java2D point on the chart to a screen location.
     *
     * @param java2DPoint  the Java2D point.
     *
     * @return The screen location.
     */
    public Point translateJava2DToScreen(Point2D java2DPoint) {
        Insets insets = getInsets();
        int x = (int) (java2DPoint.getX() * this.scaleX + insets.left);
        int y = (int) (java2DPoint.getY() * this.scaleY + insets.top);
        return new Point(x, y);
    }

    /**
     * Translates a panel (component) location to a Java2D point.
     *
     * @param screenPoint  the screen location (<code>null</code> not
     *                     permitted).
     *
     * @return The Java2D coordinates.
     */
    public Point2D translateScreenToJava2D(Point screenPoint) {
        Insets insets = getInsets();
        double x = (screenPoint.getX() - insets.left) / this.scaleX;
        double y = (screenPoint.getY() - insets.top) / this.scaleY;
        return new Point2D.Double(x, y);
    }

    /**
     * Applies any scaling that is in effect for the chart drawing to the
     * given rectangle.
     *
     * @param rect  the rectangle (<code>null</code> not permitted).
     *
     * @return A new scaled rectangle.
     */
    public Rectangle2D scale(Rectangle2D rect) {
        Insets insets = getInsets();
        double x = rect.getX() * getScaleX() + insets.left;
        double y = rect.getY() * getScaleY() + insets.top;
        double w = rect.getWidth() * getScaleX();
        double h = rect.getHeight() * getScaleY();
        return new Rectangle2D.Double(x, y, w, h);
    }

    /**
     * Returns the chart entity at a given point.
     * <P>
     * This method will return null if there is (a) no entity at the given
     * point, or (b) no entity collection has been generated.
     *
     * @param viewX  the x-coordinate.
     * @param viewY  the y-coordinate.
     *
     * @return The chart entity (possibly <code>null</code>).
     */
    public ChartEntity getEntityForPoint(int viewX, int viewY) {

        ChartEntity result = null;
        if (this.info != null) {
            Insets insets = getInsets();
            double x = (viewX - insets.left) / this.scaleX;
            double y = (viewY - insets.top) / this.scaleY;
            EntityCollection entities = this.info.getEntityCollection();
            result = entities != null ? entities.getEntity(x, y) : null;
        }
        return result;

    }

    /**
     * Returns the flag that controls whether or not the offscreen buffer
     * needs to be refreshed.
     *
     * @return A boolean.
     */
    public boolean getRefreshBuffer() {
        return this.refreshBuffer;
    }

    /**
     * Sets the refresh buffer flag.  This flag is used to avoid unnecessary
     * redrawing of the chart when the offscreen image buffer is used.
     *
     * @param flag  <code>true</code> indicates that the buffer should be
     *              refreshed.
     */
    public void setRefreshBuffer(boolean flag) {
        this.refreshBuffer = flag;
    }

    /**
     * Paints the component by drawing the chart to fill the entire component,
     * but allowing for the insets (which will be non-zero if a border has been
     * set for this component).  To increase performance (at the expense of
     * memory), an off-screen buffer image can be used.
     *
     * @param g  the graphics device for drawing on.
     */
    @Override
    public void paintComponent(Graphics g) {
        super.paintComponent(g);
        if (this.chart == null) {
            return;
        }
        Graphics2D g2 = (Graphics2D) g.create();
        try {
            Dimension size = getSize();
            Insets insets = getInsets();
            Rectangle2D available = new Rectangle2D.Double(insets.left, insets.top,
                    size.getWidth() - insets.left - insets.right,
                    size.getHeight() - insets.top - insets.bottom);

            boolean scale = false;
            double drawWidth = available.getWidth();
            double drawHeight = available.getHeight();
            this.scaleX = 1.0;
            this.scaleY = 1.0;

            if (drawWidth < this.minimumDrawWidth) {
                this.scaleX = drawWidth / this.minimumDrawWidth;
                drawWidth = this.minimumDrawWidth;
                scale = true;
            }
            else if (drawWidth > this.maximumDrawWidth) {
                this.scaleX = drawWidth / this.maximumDrawWidth;
                drawWidth = this.maximumDrawWidth;
                scale = true;
            }

            if (drawHeight < this.minimumDrawHeight) {
                this.scaleY = drawHeight / this.minimumDrawHeight;
                drawHeight = this.minimumDrawHeight;
                scale = true;
            }
            else if (drawHeight > this.maximumDrawHeight) {
                this.scaleY = drawHeight / this.maximumDrawHeight;
                drawHeight = this.maximumDrawHeight;
                scale = true;
            }

            Rectangle2D chartArea = new Rectangle2D.Double(0.0, 0.0, drawWidth,
                    drawHeight);

            if (this.useBuffer) {
                drawChartToBuffer(g2, available, insets, scale, chartArea);
            }
            else {
                drawChartDirectly(g2, insets, scale, chartArea);
            }

            paintOverlays(g2);
            drawZoomRectangle(g2, !this.useBuffer);
        }
        finally {
            g2.dispose();
        }

        resetTransientState();
    }

    /**
     * Draws the chart into the off-screen buffer and then paints the buffer
     * onto the panel.
     *
     * @param g2  the graphics device.
     * @param available  the available panel area.
     * @param insets  the panel insets.
     * @param scale  a flag indicating whether scaling is required.
     * @param chartArea  the chart drawing area.
     */
    private void drawChartToBuffer(Graphics2D g2, Rectangle2D available,
            Insets insets, boolean scale, Rectangle2D chartArea) {
        createOrResizeBuffer(g2, available);
        redrawBufferIfNecessary(scale, chartArea);
        g2.drawImage(this.chartBuffer, insets.left, insets.top, this);
    }

    /**
     * Creates or resizes the off-screen chart buffer to match the available
     * panel area.
     *
     * @param g2  the graphics device.
     * @param available  the available panel area.
     */
    private void createOrResizeBuffer(Graphics2D g2, Rectangle2D available) {
        if ((this.chartBuffer == null)
                || (this.chartBufferWidth != available.getWidth())
                || (this.chartBufferHeight != available.getHeight())) {
            this.chartBufferWidth = (int) available.getWidth();
            this.chartBufferHeight = (int) available.getHeight();
            GraphicsConfiguration gc = g2.getDeviceConfiguration();
            this.chartBuffer = gc.createCompatibleImage(
                    this.chartBufferWidth, this.chartBufferHeight,
                    Transparency.TRANSLUCENT);
            this.refreshBuffer = true;
        }
    }

    /**
     * Redraws the chart into the off-screen buffer if the refresh flag is set.
     *
     * @param scale  a flag indicating whether scaling is required.
     * @param chartArea  the chart drawing area.
     */
    private void redrawBufferIfNecessary(boolean scale, Rectangle2D chartArea) {
        if (this.refreshBuffer) {
            this.refreshBuffer = false;

            Rectangle2D bufferArea = new Rectangle2D.Double(
                    0, 0, this.chartBufferWidth, this.chartBufferHeight);

            Graphics2D bufferG2 = (Graphics2D) this.chartBuffer.getGraphics();
            try {
                clearBuffer(bufferG2);
                if (scale) {
                    drawScaledChart(bufferG2, chartArea);
                }
                else {
                    this.chart.draw(bufferG2, bufferArea, this.anchor, this.info);
                }
            }
            finally {
                bufferG2.dispose();
            }
        }
    }

    /**
     * Clears the off-screen chart buffer to a fully transparent background.
     *
     * @param bufferG2  the graphics device for the buffer.
     */
    private void clearBuffer(Graphics2D bufferG2) {
        Composite savedComposite = bufferG2.getComposite();
        bufferG2.setComposite(AlphaComposite.getInstance(
                AlphaComposite.CLEAR, 0.0f));
        Rectangle r = new Rectangle(0, 0, this.chartBufferWidth,
                this.chartBufferHeight);
        bufferG2.fill(r);
        bufferG2.setComposite(savedComposite);
    }

    /**
     * Draws the chart with the current scale transform applied.
     *
     * @param g2  the graphics device.
     * @param chartArea  the chart drawing area.
     */
    private void drawScaledChart(Graphics2D g2, Rectangle2D chartArea) {
        AffineTransform saved = g2.getTransform();
        AffineTransform st = AffineTransform.getScaleInstance(
                this.scaleX, this.scaleY);
        g2.transform(st);
        this.chart.draw(g2, chartArea, this.anchor, this.info);
        g2.setTransform(saved);
    }

    /**
     * Draws the chart directly onto the panel graphics device.
     *
     * @param g2  the graphics device.
     * @param insets  the panel insets.
     * @param scale  a flag indicating whether scaling is required.
     * @param chartArea  the chart drawing area.
     */
    private void drawChartDirectly(Graphics2D g2, Insets insets, boolean scale,
            Rectangle2D chartArea) {
        AffineTransform saved = g2.getTransform();
        g2.translate(insets.left, insets.top);
        if (scale) {
            AffineTransform st = AffineTransform.getScaleInstance(
                    this.scaleX, this.scaleY);
            g2.transform(st);
        }
        this.chart.draw(g2, chartArea, this.anchor, this.info);
        g2.setTransform(saved);
    }

    /**
     * Paints any registered overlays onto the panel.
     *
     * @param g2  the graphics device.
     */
    private void paintOverlays(Graphics2D g2) {
        Iterator iterator = this.overlays.iterator();
        while (iterator.hasNext()) {
            Overlay overlay = (Overlay) iterator.next();
            overlay.paintOverlay(g2, this);
        }
    }

    /**
     * Resets the transient state used during rendering.
     */
    private void resetTransientState() {
        this.anchor = null;
        this.verticalTraceLine = null;
        this.horizontalTraceLine = null;
    }

    /**
     * Receives notification of changes to the chart, and redraws the chart.
     *
     * @param event  details of the chart change event.
     */
    @Override
    public void chartChanged(ChartChangeEvent event) {
        this.refreshBuffer = true;
        Plot plot = this.chart.getPlot();
        if (plot instanceof Zoomable) {
            Zoomable z = (Zoomable) plot;
            this.orientation = z.getOrientation();
        }
        repaint();
    }

    /**
     * Receives notification of a chart progress event.
     *
     * @param event  the event.
     */
    @Override
    public void chartProgress(ChartProgressEvent event) {
        // does nothing - override if necessary
    }

    /**
     * Handles action events generated by the popup menu.
     *
     * @param event  the event.
     */
    @Override
    public void actionPerformed(ActionEvent event) {

        String command = event.getActionCommand();

        // many of the zoom methods need a screen location - all we have is
        // the zoomPoint, but it might be null.  Here we grab the x and y
        // coordinates, or use defaults...
        double screenX = -1.0;
        double screenY = -1.0;
        if (this.zoomPoint != null) {
            screenX = this.zoomPoint.getX();
            screenY = this.zoomPoint.getY();
        }

        if (command.equals(PROPERTIES_COMMAND)) {
            doEditChartProperties();
        }
        else if (command.equals(COPY_COMMAND)) {
            doCopy();
        }
        else if (command.equals(SAVE_AS_PNG_COMMAND)) {
            doSaveAsWithErrorHandling();
        }
        else if (command.equals(SAVE_AS_SVG_COMMAND)) {
            saveAsSVGWithErrorHandling();
        }
        else if (command.equals(SAVE_AS_PDF_COMMAND)) {
            saveAsPDF(null);
        }
        else if (command.equals(PRINT_COMMAND)) {
            createChartPrintJob();
        }
        else {
            handleZoomCommand(command, screenX, screenY);
        }

    }

    /**
     * Saves the chart as a PNG, displaying a warning dialog if an I/O error
     * occurs.
     */
    private void doSaveAsWithErrorHandling() {
        try {
            doSaveAs();
        }
        catch (IOException e) {
            JOptionPane.showMessageDialog(this, "I/O error occurred.",
                    "Save As PNG", JOptionPane.WARNING_MESSAGE);
        }
    }

    /**
     * Saves the chart as an SVG, displaying a warning dialog if an I/O error
     * occurs.
     */
    private void saveAsSVGWithErrorHandling() {
        try {
            saveAsSVG(null);
        }
        catch (IOException e) {
            JOptionPane.showMessageDialog(this, "I/O error occurred.",
                    "Save As SVG", JOptionPane.WARNING_MESSAGE);
        }
    }

    /**
     * Executes a zoom-related popup menu command.
     *
     * @param command  the action command.
     * @param screenX  the x-coordinate of the zoom anchor.
     * @param screenY  the y-coordinate of the zoom anchor.
     */
    private void handleZoomCommand(String command, double screenX, double screenY) {
        if (command.equals(ZOOM_IN_BOTH_COMMAND)) {
            zoomInBoth(screenX, screenY);
        }
        else if (command.equals(ZOOM_IN_DOMAIN_COMMAND)) {
            zoomInDomain(screenX, screenY);
        }
        else if (command.equals(ZOOM_IN_RANGE_COMMAND)) {
            zoomInRange(screenX, screenY);
        }
        else if (command.equals(ZOOM_OUT_BOTH_COMMAND)) {
            zoomOutBoth(screenX, screenY);
        }
        else if (command.equals(ZOOM_OUT_DOMAIN_COMMAND)) {
            zoomOutDomain(screenX, screenY);
        }
        else if (command.equals(ZOOM_OUT_RANGE_COMMAND)) {
            zoomOutRange(screenX, screenY);
        }
        else if (command.equals(ZOOM_RESET_BOTH_COMMAND)) {
            restoreAutoBounds();
        }
        else if (command.equals(ZOOM_RESET_DOMAIN_COMMAND)) {
            restoreAutoDomainBounds();
        }
        else if (command.equals(ZOOM_RESET_RANGE_COMMAND)) {
            restoreAutoRangeBounds();
        }
    }

    /**
     * Handles a 'mouse entered' event. This method changes the tooltip delays
     * of ToolTipManager.sharedInstance() to the possibly different values set
     * for this chart panel.
     *
     * @param e  the mouse event.
     */
    @Override
    public void mouseEntered(MouseEvent e) {
        if (!this.ownToolTipDelaysActive) {
            ToolTipManager ttm = ToolTipManager.sharedInstance();

            this.originalToolTipInitialDelay = ttm.getInitialDelay();
            ttm.setInitialDelay(this.ownToolTipInitialDelay);

            this.originalToolTipReshowDelay = ttm.getReshowDelay();
            ttm.setReshowDelay(this.ownToolTipReshowDelay);

            this.originalToolTipDismissDelay = ttm.getDismissDelay();
            ttm.setDismissDelay(this.ownToolTipDismissDelay);

            this.ownToolTipDelaysActive = true;
        }
    }

    /**
     * Handles a 'mouse exited' event. This method resets the tooltip delays of
     * ToolTipManager.sharedInstance() to their
     * original values in effect before mouseEntered()
     *
     * @param e  the mouse event.
     */
    @Override
    public void mouseExited(MouseEvent e) {
        if (this.ownToolTipDelaysActive) {
            // restore original tooltip dealys
            ToolTipManager ttm = ToolTipManager.sharedInstance();
            ttm.setInitialDelay(this.originalToolTipInitialDelay);
            ttm.setReshowDelay(this.originalToolTipReshowDelay);
            ttm.setDismissDelay(this.originalToolTipDismissDelay);
            this.ownToolTipDelaysActive = false;
        }
    }

    /**
     * Handles a 'mouse pressed' event.
     * <P>
     * This event is the popup trigger on Unix/Linux.  For Windows, the popup
     * trigger is the 'mouse released' event.
     *
     * @param e  The mouse event.
     */
    @Override
    public void mousePressed(MouseEvent e) {
        if (this.chart == null) {
            return;
        }
        Plot plot = this.chart.getPlot();
        int mods = e.getModifiers();
        if ((mods & this.panMask) == this.panMask) {
            // can we pan this plot?
            if (plot instanceof Pannable) {
                Pannable pannable = (Pannable) plot;
                if (pannable.isDomainPannable() || pannable.isRangePannable()) {
                    Rectangle2D screenDataArea = getScreenDataArea(e.getX(),
                            e.getY());
                    if (screenDataArea != null && screenDataArea.contains(
                            e.getPoint())) {
                        this.panW = screenDataArea.getWidth();
                        this.panH = screenDataArea.getHeight();
                        this.panLast = e.getPoint();
                        setCursor(Cursor.getPredefinedCursor(
                                Cursor.MOVE_CURSOR));
                    }
                }
                // the actual panning occurs later in the mouseDragged() 
                // method
            }
        }
        else if (this.zoomRectangle == null) {
            Rectangle2D screenDataArea = getScreenDataArea(e.getX(), e.getY());
            if (screenDataArea != null) {
                this.zoomPoint = getPointInRectangle(e.getX(), e.getY(),
                        screenDataArea);
            }
            else {
                this.zoomPoint = null;
            }
            if (e.isPopupTrigger()) {
                if (this.popup != null) {
                    displayPopupMenu(e.getX(), e.getY());
                }
            }
        }
    }

    /**
     * Returns a point based on (x, y) but constrained to be within the bounds
     * of the given rectangle.  This method could be moved to JCommon.
     *
     * @param x  the x-coordinate.
     * @param y  the y-coordinate.
     * @param area  the rectangle (<code>null</code> not permitted).
     *
     * @return A point within the rectangle.
     */
    private Point2D getPointInRectangle(int x, int y, Rectangle2D area) {
        double xx = Math.max(area.getMinX(), Math.min(x, area.getMaxX()));
        double yy = Math.max(area.getMinY(), Math.min(y, area.getMaxY()));
        return new Point2D.Double(xx, yy);
    }

    /**
     * Returns whether horizontal zooming is currently enabled, taking the plot
     * orientation into account.
     *
     * @return A boolean.
     */
    private boolean isHorizontalZoomEnabled() {
        if (this.orientation == PlotOrientation.HORIZONTAL) {
            return this.rangeZoomable;
        }
        return this.domainZoomable;
    }

    /**
     * Returns whether vertical zooming is currently enabled, taking the plot
     * orientation into account.
     *
     * @return A boolean.
     */
    private boolean isVerticalZoomEnabled() {
        if (this.orientation == PlotOrientation.HORIZONTAL) {
            return this.domainZoomable;
        }
        return this.rangeZoomable;
    }

    /**
     * Handles panning for a mouse drag event.
     *
     * @param e  the mouse event.
     */
    private void handlePanning(MouseEvent e) {
        double dx = e.getX() - this.panLast.getX();
        double dy = e.getY() - this.panLast.getY();
        if (dx == 0.0 && dy == 0.0) {
            return;
        }
        double wPercent = -dx / this.panW;
        double hPercent = dy / this.panH;
        boolean old = this.chart.getPlot().isNotify();
        this.chart.getPlot().setNotify(false);
        Pannable p = (Pannable) this.chart.getPlot();
        if (p.getOrientation() == PlotOrientation.VERTICAL) {
            p.panDomainAxes(wPercent, this.info.getPlotInfo(),
                    this.panLast);
            p.panRangeAxes(hPercent, this.info.getPlotInfo(),
                    this.panLast);
        }
        else {
            p.panDomainAxes(hPercent, this.info.getPlotInfo(),
                    this.panLast);
            p.panRangeAxes(wPercent, this.info.getPlotInfo(),
                    this.panLast);
        }
        this.panLast = e.getPoint();
        this.chart.getPlot().setNotify(old);
    }

    /**
     * Updates the zoom rectangle based on the current mouse position and the
     * enabled zoom directions.
     *
     * @param e  the mouse event.
     * @param hZoom  a flag indicating whether horizontal zooming is enabled.
     * @param vZoom  a flag indicating whether vertical zooming is enabled.
     * @param scaledDataArea  the scaled data area.
     */
    private void updateZoomRectangle(MouseEvent e, boolean hZoom, boolean vZoom,
            Rectangle2D scaledDataArea) {
        if (hZoom && vZoom) {
            double xmax = Math.min(e.getX(), scaledDataArea.getMaxX());
            double ymax = Math.min(e.getY(), scaledDataArea.getMaxY());
            this.zoomRectangle = new Rectangle2D.Double(
                    this.zoomPoint.getX(), this.zoomPoint.getY(),
                    xmax - this.zoomPoint.getX(), ymax - this.zoomPoint.getY());
        }
        else if (hZoom) {
            double xmax = Math.min(e.getX(), scaledDataArea.getMaxX());
            this.zoomRectangle = new Rectangle2D.Double(
                    this.zoomPoint.getX(), scaledDataArea.getMinY(),
                    xmax - this.zoomPoint.getX(), scaledDataArea.getHeight());
        }
        else if (vZoom) {
            double ymax = Math.min(e.getY(), scaledDataArea.getMaxY());
            this.zoomRectangle = new Rectangle2D.Double(
                    scaledDataArea.getMinX(), this.zoomPoint.getY(),
                    scaledDataArea.getWidth(), ymax - this.zoomPoint.getY());
        }
    }

    /**
     * Handles the release of the mouse button while a zoom rectangle is being
     * drawn.
     *
     * @param e  the mouse event.
     */
    private void handleZoomRectangleRelease(MouseEvent e) {
        boolean hZoom = isHorizontalZoomEnabled();
        boolean vZoom = isVerticalZoomEnabled();
        boolean zoomTrigger1 = hZoom && Math.abs(e.getX()
                - this.zoomPoint.getX()) >= this.zoomTriggerDistance;
        boolean zoomTrigger2 = vZoom && Math.abs(e.getY()
                - this.zoomPoint.getY()) >= this.zoomTriggerDistance;
        if (zoomTrigger1 || zoomTrigger2) {
            if (isRestoreAutoBounds(e, hZoom, vZoom)) {
                restoreAutoBounds();
            }
            else {
                performZoom(e, hZoom, vZoom);
            }
            this.zoomPoint = null;
            this.zoomRectangle = null;
        }
        else {
            eraseZoomRectangle();
            this.zoomPoint = null;
            this.zoomRectangle = null;
        }
    }

    /**
     * Returns <code>true</code> if the zoom gesture indicates that the auto
     * bounds should be restored.
     *
     * @param e  the mouse event.
     * @param hZoom  a flag indicating whether horizontal zooming is enabled.
     * @param vZoom  a flag indicating whether vertical zooming is enabled.
     *
     * @return A boolean.
     */
    private boolean isRestoreAutoBounds(MouseEvent e, boolean hZoom, boolean vZoom) {
        return (hZoom && (e.getX() < this.zoomPoint.getX()))
                || (vZoom && (e.getY() < this.zoomPoint.getY()));
    }

    /**
     * Performs a zoom operation based on the current zoom rectangle.
     *
     * @param e  the mouse event.
     * @param hZoom  a flag indicating whether horizontal zooming is enabled.
     * @param vZoom  a flag indicating whether vertical zooming is enabled.
     */
    private void performZoom(MouseEvent e, boolean hZoom, boolean vZoom) {
        Rectangle2D screenDataArea = getScreenDataArea(
                (int) this.zoomPoint.getX(),
                (int) this.zoomPoint.getY());
        double maxX = screenDataArea.getMaxX();
        double maxY = screenDataArea.getMaxY();
        double x, y, w, h;
        if (!vZoom) {
            x = this.zoomPoint.getX();
            y = screenDataArea.getMinY();
            w = Math.min(this.zoomRectangle.getWidth(),
                    maxX - this.zoomPoint.getX());
            h = screenDataArea.getHeight();
        }
        else if (!hZoom) {
            x = screenDataArea.getMinX();
            y = this.zoomPoint.getY();
