/**
 * Updates the zoom rectangle based on the current mouse position and the
 * enabled zoom directions.
 *
 * @param e  the mouse event.
 * @param hZoom  a flag indicating whether horizontal zooming is enabled.
 * @param vZoom  a flag indicating whether vertical zooming is enabled.
 * @param scaledDataArea  the scaled data area.
 */
private void updateZoomRectangle(MouseEvent e, boolean hZoom, boolean vZoom,
        Rectangle2D scaledDataArea) {
    if (hZoom && vZoom) {
        double xmax = Math.min(e.getX(), scaledDataArea.getMaxX());
        double ymax = Math.min(e.getY(), scaledDataArea.getMaxY());
        this.zoomRectangle = new Rectangle2D.Double(
                this.zoomPoint.getX(), this.zoomPoint.getY(),
                xmax - this.zoomPoint.getX(),
                ymax - this.zoomPoint.getY());
    }
    else if (hZoom) {
        double xmax = Math.min(e.getX(), scaledDataArea.getMaxX());
        this.zoomRectangle = new Rectangle2D.Double(
                this.zoomPoint.getX(), scaledDataArea.getMinY(),
                xmax - this.zoomPoint.getX(), scaledDataArea.getHeight());
    }
    else if (vZoom) {
        double ymax = Math.min(e.getY(), scaledDataArea.getMaxY());
        this.zoomRectangle = new Rectangle2D.Double(
                scaledDataArea.getMinX(), this.zoomPoint.getY(),
                scaledDataArea.getWidth(),
                ymax - this.zoomPoint.getY());
    }
}
