/**
 * Redraws the chart into the off-screen buffer if the refresh flag is set.
 *
 * @param scale  a flag indicating whether scaling is required.
 * @param chartArea  the chart drawing area.
 */
private void redrawBufferIfNecessary(boolean scale, Rectangle2D chartArea) {
    if (this.refreshBuffer) {
        this.refreshBuffer = false;

        Rectangle2D bufferArea = new Rectangle2D.Double(
                0, 0, this.chartBufferWidth, this.chartBufferHeight);

        Graphics2D bufferG2 = (Graphics2D) this.chartBuffer.getGraphics();
        try {
            clearBuffer(bufferG2);
            if (scale) {
                drawScaledChart(bufferG2, chartArea);
            }
            else {
                this.chart.draw(bufferG2, bufferArea, this.anchor, this.info);
            }
        }
        finally {
            bufferG2.dispose();
        }
    }
}
