    /**
     * Paints the component by drawing the chart to fill the entire component,
     * but allowing for the insets (which will be non-zero if a border has been
     * set for this component).  To increase performance (at the expense of
     * memory), an off-screen buffer image can be used.
     *
     * @param g  the graphics device for drawing on.
     */
    @Override
    public void paintComponent(Graphics g) {
        super.paintComponent(g);
        if (this.chart == null) {
            return;
        }

        Graphics2D g2 = (Graphics2D) g.create();
        try {
            Dimension size = getSize();
            Insets insets = getInsets();
            Rectangle2D available = new Rectangle2D.Double(insets.left, insets.top,
                    size.getWidth() - insets.left - insets.right,
                    size.getHeight() - insets.top - insets.bottom);

            boolean scale = updateScaleFactors(available.getWidth(),
                    available.getHeight());
            double drawWidth = getDrawWidth(available.getWidth());
            double drawHeight = getDrawHeight(available.getHeight());
            Rectangle2D chartArea = new Rectangle2D.Double(0.0, 0.0, drawWidth,
                    drawHeight);

            if (this.useBuffer) {
                drawChartToBuffer(g2, available, chartArea, scale);
                g2.drawImage(this.chartBuffer, insets.left, insets.top, this);
            }
            else {
                drawChartDirectly(g2, insets, chartArea, scale);
            }

            paintOverlays(g2);
            drawZoomRectangle(g2, !this.useBuffer);
        }
        finally {
            g2.dispose();
        }

        this.anchor = null;
        this.verticalTraceLine = null;
        this.horizontalTraceLine = null;
    }

    /**
     * Updates the scale factors ({@link #scaleX} and {@link #scaleY}) based on
     * the available drawing area and the minimum/maximum draw sizes.
     *
     * @param availableWidth  the available width.
     * @param availableHeight  the available height.
     *
     * @return <code>true</code> if scaling is required, and
     *         <code>false</code> otherwise.
     */
    private boolean updateScaleFactors(double availableWidth,
            double availableHeight) {
        boolean scale = false;
        this.scaleX = 1.0;
        this.scaleY = 1.0;

        if (availableWidth < this.minimumDrawWidth) {
            this.scaleX = availableWidth / this.minimumDrawWidth;
            scale = true;
        }
        else if (availableWidth > this.maximumDrawWidth) {
            this.scaleX = availableWidth / this.maximumDrawWidth;
            scale = true;
        }

        if (availableHeight < this.minimumDrawHeight) {
            this.scaleY = availableHeight / this.minimumDrawHeight;
            scale = true;
        }
        else if (availableHeight > this.maximumDrawHeight) {
            this.scaleY = availableHeight / this.maximumDrawHeight;
            scale = true;
        }

        return scale;
    }

    /**
     * Returns the width to use for drawing the chart, taking into account the
     * minimum and maximum draw widths.
     *
     * @param availableWidth  the available width.
     *
     * @return The draw width.
     */
    private double getDrawWidth(double availableWidth) {
        if (availableWidth < this.minimumDrawWidth) {
            return this.minimumDrawWidth;
        }
        if (availableWidth > this.maximumDrawWidth) {
            return this.maximumDrawWidth;
        }
        return availableWidth;
    }

    /**
     * Returns the height to use for drawing the chart, taking into account
     * the minimum and maximum draw heights.
     *
     * @param availableHeight  the available height.
     *
     * @return The draw height.
     */
    private double getDrawHeight(double availableHeight) {
        if (availableHeight < this.minimumDrawHeight) {
            return this.minimumDrawHeight;
        }
        if (availableHeight > this.maximumDrawHeight) {
            return this.maximumDrawHeight;
        }
        return availableHeight;
    }

    /**
     * Draws the chart into the off-screen buffer, creating or resizing the
     * buffer if necessary.
     *
     * @param g2  the graphics device for the panel.
     * @param available  the available drawing area on the panel.
     * @param chartArea  the chart drawing area.
     * @param scale  a flag indicating whether scaling is required.
     */
    private void drawChartToBuffer(Graphics2D g2, Rectangle2D available,
            Rectangle2D chartArea, boolean scale) {

        if (this.chartBuffer == null
                || this.chartBufferWidth != available.getWidth()
                || this.chartBufferHeight != available.getHeight()) {
            this.chartBufferWidth = (int) available.getWidth();
            this.chartBufferHeight = (int) available.getHeight();
            GraphicsConfiguration gc = g2.getDeviceConfiguration();
            this.chartBuffer = gc.createCompatibleImage(
                    this.chartBufferWidth, this.chartBufferHeight,
                    Transparency.TRANSLUCENT);
            this.refreshBuffer = true;
        }

        if (this.refreshBuffer) {
            this.refreshBuffer = false;

            Rectangle2D bufferArea = new Rectangle2D.Double(
                    0, 0, this.chartBufferWidth, this.chartBufferHeight);

            Graphics2D bufferG2 = (Graphics2D) this.chartBuffer.getGraphics();
            try {
                clearBuffer(bufferG2);
                if (scale) {
                    AffineTransform saved = bufferG2.getTransform();
                    AffineTransform st = AffineTransform.getScaleInstance(
                            this.scaleX, this.scaleY);
                    bufferG2.transform(st);
                    this.chart.draw(bufferG2, chartArea, this.anchor,
                            this.info);
                    bufferG2.setTransform(saved);
                }
                else {
                    this.chart.draw(bufferG2, bufferArea, this.anchor,
                            this.info);
                }
            }
            finally {
                bufferG2.dispose();
            }
        }
    }

    /**
     * Clears the off-screen chart buffer to a fully transparent background.
     *
     * @param bufferG2  the graphics device for the buffer.
     */
    private void clearBuffer(Graphics2D bufferG2) {
        Composite savedComposite = bufferG2.getComposite();
        bufferG2.setComposite(AlphaComposite.getInstance(
                AlphaComposite.CLEAR, 0.0f));
        bufferG2.fill(new Rectangle(0, 0, this.chartBufferWidth,
                this.chartBufferHeight));
        bufferG2.setComposite(savedComposite);
    }

    /**
     * Draws the chart directly onto the panel (without using the off-screen
     * buffer).
     *
     * @param g2  the graphics device for the panel.
     * @param insets  the panel insets.
     * @param chartArea  the chart drawing area.
     * @param scale  a flag indicating whether scaling is required.
     */
    private void drawChartDirectly(Graphics2D g2, Insets insets,
            Rectangle2D chartArea, boolean scale) {
        AffineTransform saved = g2.getTransform();
        g2.translate(insets.left, insets.top);
        if (scale) {
            AffineTransform st = AffineTransform.getScaleInstance(
                    this.scaleX, this.scaleY);
            g2.transform(st);
        }
        this.chart.draw(g2, chartArea, this.anchor, this.info);
        g2.setTransform(saved);
    }

    /**
     * Paints any overlays registered with the panel.
     *
     * @param g2  the graphics device.
     */
    private void paintOverlays(Graphics2D g2) {
        Iterator iterator = this.overlays.iterator();
        while (iterator.hasNext()) {
            Overlay overlay = (Overlay) iterator.next();
            overlay.paintOverlay(g2, this);
        }
    }

    /**
     * Receives notification of changes to the chart, and redraws the chart.
     *
     * @param event  details of the chart change event.
     */
    @Override
    public void chartChanged(ChartChangeEvent event) {
        this.refreshBuffer = true;
        Plot plot = this.chart.getPlot();
        if (plot instanceof Zoomable) {
            Zoomable z = (Zoomable) plot;
            this.orientation = z.getOrientation();
        }
        repaint();
    }

