    /**
     * Updates the scale factors ({@link #scaleX} and {@link #scaleY}) based on
     * the available drawing area and the minimum/maximum draw sizes.
     *
     * @param availableWidth  the available width.
     * @param availableHeight  the available height.
     *
     * @return <code>true</code> if scaling is required, and
     *         <code>false</code> otherwise.
     */
    private boolean updateScaleFactors(double availableWidth,
            double availableHeight) {
        boolean scale = false;
        this.scaleX = 1.0;
        this.scaleY = 1.0;

        if (availableWidth < this.minimumDrawWidth) {
            this.scaleX = availableWidth / this.minimumDrawWidth;
            scale = true;
        }
        else if (availableWidth > this.maximumDrawWidth) {
            this.scaleX = availableWidth / this.maximumDrawWidth;
            scale = true;
        }

        if (availableHeight < this.minimumDrawHeight) {
            this.scaleY = availableHeight / this.minimumDrawHeight;
            scale = true;
        }
        else if (availableHeight > this.maximumDrawHeight) {
            this.scaleY = availableHeight / this.maximumDrawHeight;
            scale = true;
        }

        return scale;
    }

