    private double getDrawWidth(double availableWidth) {
        if (availableWidth < this.minimumDrawWidth) {
            return this.minimumDrawWidth;
        }
        if (availableWidth > this.maximumDrawWidth) {
            return this.maximumDrawWidth;
        }
