    /**
     * Returns a string for the tooltip.
     *
     * @param e  the mouse event.
     *
     * @return A tool tip or <code>null</code> if no tooltip is available.
     */
    @Override
    public String getToolTipText(MouseEvent e) {
        String result = null;
        if (this.info != null) {
            EntityCollection entities = this.info.getEntityCollection();
            if (entities != null) {
                Insets insets = getInsets();
                ChartEntity entity = entities.getEntity(
                        (int) ((e.getX() - insets.left) / this.scaleX),
                        (int) ((e.getY() - insets.top) / this.scaleY));
                if (entity != null) {
                    result = entity.getToolTipText();
                }
            }
        }
        return result;
    }

    /**
     * Translates a Java2D point on the chart to a screen location.
     *
     * @param java2DPoint  the Java2D point.
     *
     * @return The screen location.
     */
    public Point translateJava2DToScreen(Point2D java2DPoint) {
        Insets insets = getInsets();
        int x = (int) (java2DPoint.getX() * this.scaleX + insets.left);
        int y = (int) (java2DPoint.getY() * this.scaleY + insets.top);
        return new Point(x, y);
    }

    /**
     * Translates a panel (component) location to a Java2D point.
     *
     * @param screenPoint  the screen location (<code>null</code> not
     *                     permitted).
     *
     * @return The Java2D coordinates.
     */
    public Point2D translateScreenToJava2D(Point screenPoint) {
        Insets insets = getInsets();
        double x = (screenPoint.getX() - insets.left) / this.scaleX;
        double y = (screenPoint.getY() - insets.top) / this.scaleY;
        return new Point2D.Double(x, y);
    }

    /**
     * Applies any scaling that is in effect for the chart drawing to the
     * given rectangle.
     *
     * @param rect  the rectangle (<code>null</code> not permitted).
     *
     * @return A new scaled rectangle.
     */
    public Rectangle2D scale(Rectangle2D rect) {
        Insets insets = getInsets();
        double x = rect.getX() * getScaleX() + insets.left;
        double y = rect.getY() * getScaleY() + insets.top;
        double w = rect.getWidth() * getScaleX();
        double h = rect.getHeight() * getScaleY();
        return new Rectangle2D.Double(x, y, w, h);
    }

    /**
     * Returns the chart entity at a given point.
     * <P>
     * This method will return null if there is (a) no entity at the given
     * point, or (b) no entity collection has been generated.
     *
     * @param viewX  the x-coordinate.
     * @param viewY  the y-coordinate.
     *
     * @return The chart entity (possibly <code>null</code>).
     */
    public ChartEntity getEntityForPoint(int viewX, int viewY) {

        ChartEntity result = null;
        if (this.info != null) {
            Insets insets = getInsets();
            double x = (viewX - insets.left) / this.scaleX;
            double y = (viewY - insets.top) / this.scaleY;
            EntityCollection entities = this.info.getEntityCollection();
            result = entities != null ? entities.getEntity(x, y) : null;
        }
        return result;

    }

    /**
     * Returns the flag that controls whether or not the offscreen buffer
     * needs to be refreshed.
     *
     * @return A boolean.
     */
    public boolean getRefreshBuffer() {
        return this.refreshBuffer;
    }

    /**
     * Sets the refresh buffer flag.  This flag is used to avoid unnecessary
     * redrawing of the chart when the offscreen image buffer is used.
     *
     * @param flag  <code>true</code> indicates that the buffer should be
     *              refreshed.
     */
    public void setRefreshBuffer(boolean flag) {
        this.refreshBuffer = flag;
    }

    /**
     * Holds the result of calculating whether the chart needs to be scaled
     * to fit the available drawing area.
     */
    private static class ScaleResult {
        /** Whether scaling is required. */
        boolean scale;
        /** The width to use when drawing the chart. */
        double drawWidth;
        /** The height to use when drawing the chart. */
        double drawHeight;

        /**
         * Creates a new scale result.
         *
         * @param scale  whether scaling is required.
         * @param drawWidth  the drawing width.
         * @param drawHeight  the drawing height.
         */
        ScaleResult(boolean scale, double drawWidth, double drawHeight) {
            this.scale = scale;
            this.drawWidth = drawWidth;
            this.drawHeight = drawHeight;
        }
    }

    /**
     * Paints the component by drawing the chart to fill the entire component,
     * but allowing for the insets (which will be non-zero if a border has been
     * set for this component).  To increase performance (at the expense of
     * memory), an off-screen buffer image can be used.
     *
     * @param g  the graphics device for drawing on.
     */
    @Override
    public void paintComponent(Graphics g) {
        super.paintComponent(g);
        if (this.chart == null) {
            return;
        }
        Graphics2D g2 = (Graphics2D) g.create();
        try {
            Rectangle2D available = calculateAvailableArea();
            ScaleResult scaleResult = updateScaleFactors(available);
            Rectangle2D chartArea = createChartArea(scaleResult);
            if (this.useBuffer) {
                drawChartToBuffer(g2, available, chartArea, scaleResult.scale);
            } else {
                drawChartDirectly(g2, chartArea, scaleResult.scale);
            }
            paintOverlays(g2);
            drawZoomRectangle(g2, !this.useBuffer);
        } finally {
            g2.dispose();
        }
        clearTransientState();
    }

    /**
     * Calculates the area available for chart rendering after accounting for
     * the panel insets.
     *
     * @return The available chart area.
     */
    private Rectangle2D calculateAvailableArea() {
        Dimension size = getSize();
        Insets insets = getInsets();
        return new Rectangle2D.Double(insets.left, insets.top,
                size.getWidth() - insets.left - insets.right,
                size.getHeight() - insets.top - insets.bottom);
    }

    /**
     * Computes the scale factors required to fit the chart into the available
     * area and updates the panel's scale fields.
     *
     * @param available  the available drawing area.
     *
     * @return A {@link ScaleResult} describing the required scaling.
     */
    private ScaleResult updateScaleFactors(Rectangle2D available) {
        boolean scale = false;
        double drawWidth = available.getWidth();
        double drawHeight = available.getHeight();
        this.scaleX = 1.0;
        this.scaleY = 1.0;

        if (drawWidth < this.minimumDrawWidth) {
            this.scaleX = drawWidth / this.minimumDrawWidth;
            drawWidth = this.minimumDrawWidth;
            scale = true;
        } else if (drawWidth > this.maximumDrawWidth) {
            this.scaleX = drawWidth / this.maximumDrawWidth;
            drawWidth = this.maximumDrawWidth;
            scale = true;
        }

        if (drawHeight < this.minimumDrawHeight) {
            this.scaleY = drawHeight / this.minimumDrawHeight;
            drawHeight = this.minimumDrawHeight;
            scale = true;
        } else if (drawHeight > this.maximumDrawHeight) {
            this.scaleY = drawHeight / this.maximumDrawHeight;
            drawHeight = this.maximumDrawHeight;
            scale = true;
        }

        return new ScaleResult(scale, drawWidth, drawHeight);
    }

    /**
     * Creates the chart drawing area from the scale result.
     *
     * @param scaleResult  the scale result.
     *
     * @return The chart area.
     */
    private Rectangle2D createChartArea(ScaleResult scaleResult) {
        return new Rectangle2D.Double(0.0, 0.0, scaleResult.drawWidth,
                scaleResult.drawHeight);
    }

    /**
     * Draws the chart into the off-screen buffer and then copies the buffer
     * onto the panel.
     *
     * @param panelG2  the panel graphics device.
     * @param available  the available panel area.
     * @param chartArea  the chart drawing area.
     * @param scale  whether scaling is required.
     */
    private void drawChartToBuffer(Graphics2D panelG2, Rectangle2D available,
            Rectangle2D chartArea, boolean scale) {
        ensureBufferSized(panelG2, available);
        if (this.refreshBuffer) {
            this.refreshBuffer = false;
            Graphics2D bufferG2 = (Graphics2D) this.chartBuffer.getGraphics();
            try {
                clearBuffer(bufferG2);
                if (scale) {
                    drawChartScaled(bufferG2, chartArea);
                } else {
                    Rectangle2D bufferArea = new Rectangle2D.Double(0, 0,
                            this.chartBufferWidth, this.chartBufferHeight);
                    this.chart.draw(bufferG2, bufferArea, this.anchor,
                            this.info);
                }
            } finally {
                bufferG2.dispose();
            }
        }
        panelG2.drawImage(this.chartBuffer, (int) available.getX(),
                (int) available.getY(), this);
    }

    /**
     * Ensures the off-screen buffer is the same size as the available panel
     * area, recreating it if necessary.
     *
     * @param panelG2  the panel graphics device.
     * @param available  the available panel area.
     */
    private void ensureBufferSized(Graphics2D panelG2, Rectangle2D available) {
        int width = (int) available.getWidth();
        int height = (int) available.getHeight();
        if (this.chartBuffer == null
                || this.chartBufferWidth != width
                || this.chartBufferHeight != height) {
            this.chartBufferWidth = width;
            this.chartBufferHeight = height;
            GraphicsConfiguration gc = panelG2.getDeviceConfiguration();
            this.chartBuffer = gc.createCompatibleImage(this.chartBufferWidth,
                    this.chartBufferHeight, Transparency.TRANSLUCENT);
            this.refreshBuffer = true;
        }
    }

    /**
     * Clears the off-screen buffer to fully transparent.
     *
     * @param bufferG2  the buffer graphics device.
     */
    private void clearBuffer(Graphics2D bufferG2) {
        Composite savedComposite = bufferG2.getComposite();
        bufferG2.setComposite(AlphaComposite.getInstance(
                AlphaComposite.CLEAR, 0.0f));
        Rectangle r = new Rectangle(0, 0, this.chartBufferWidth,
                this.chartBufferHeight);
        bufferG2.fill(r);
        bufferG2.setComposite(savedComposite);
    }

    /**
     * Draws the chart with the current scale transform applied.
     *
     * @param g2  the graphics device.
     * @param chartArea  the chart area.
     */
    private void drawChartScaled(Graphics2D g2, Rectangle2D chartArea) {
        AffineTransform saved = g2.getTransform();
        AffineTransform st = AffineTransform.getScaleInstance(this.scaleX,
                this.scaleY);
        g2.transform(st);
        this.chart.draw(g2, chartArea, this.anchor, this.info);
        g2.setTransform(saved);
    }

    /**
     * Draws the chart directly onto the panel graphics device.
     *
     * @param g2  the panel graphics device.
     * @param chartArea  the chart area.
     * @param scale  whether scaling is required.
     */
    private void drawChartDirectly(Graphics2D g2, Rectangle2D chartArea,
            boolean scale) {
        AffineTransform saved = g2.getTransform();
        g2.translate(getInsets().left, getInsets().top);
        if (scale) {
            AffineTransform st = AffineTransform.getScaleInstance(this.scaleX,
                    this.scaleY);
            g2.transform(st);
        }
        this.chart.draw(g2, chartArea, this.anchor, this.info);
        g2.setTransform(saved);
    }

    /**
     * Paints any registered overlays.
     *
     * @param g2  the graphics device.
     */
    private void paintOverlays(Graphics2D g2) {
        Iterator iterator = this.overlays.iterator();
        while (iterator.hasNext()) {
            Overlay overlay = (Overlay) iterator.next();
            overlay.paintOverlay(g2, this);
        }
    }

    /**
     * Clears the transient state used during rendering.
     */
    private void clearTransientState() {
        this.anchor = null;
        this.verticalTraceLine = null;
        this.horizontalTraceLine = null;
    }

    /**
     * Receives notification of changes to the chart, and redraws the chart.
     *
     * @param event  details of the chart change event.
     */
    @Override
    public void chartChanged(ChartChangeEvent event) {
        this.refreshBuffer = true;
        Plot plot = this.chart.getPlot();
        if (plot instanceof Zoomable) {
            Zoomable z = (Zoomable) plot;
            this.orientation = z.getOrientation();
        }
        repaint();
    }

    /**
     * Receives notification of a chart progress event.
     *
     * @param event  the event.
     */
    @Override
    public void chartProgress(ChartProgressEvent event) {
        // does nothing - override if necessary
    }

    /**
     * Handles action events generated by the popup menu.
     *
     * @param event  the event.
     */
    @Override
    public void actionPerformed(ActionEvent event) {
        String command = event.getActionCommand();

        double screenX = -1.0;
        double screenY = -1.0;
        if (this.zoomPoint != null) {
            screenX = this.zoomPoint.getX();
            screenY = this.zoomPoint.getY();
        }

        if (handleGeneralCommand(command)) {
            return;
        }
        if (handleSaveCommand(command)) {
            return;
        }
        handleZoomCommand(command, screenX, screenY);
    }

    /**
     * Handles general commands (properties, copy and print).
     *
     * @param command  the action command.
     *
     * @return <code>true</code> if the command was handled.
     */
    private boolean handleGeneralCommand(String command) {
        if (command.equals(PROPERTIES_COMMAND)) {
            doEditChartProperties();
            return true;
        }
        if (command.equals(COPY_COMMAND)) {
            doCopy();
            return true;
        }
        if (command.equals(PRINT_COMMAND)) {
            createChartPrintJob();
            return true;
        }
        return false;
    }

    /**
     * Handles save commands (PNG, SVG and PDF).
     *
     * @param command  the action command.
     *
     * @return <code>true</code> if the command was handled.
     */
    private boolean handleSaveCommand(String command) {
        if (command.equals(SAVE_AS_PNG_COMMAND)) {
            try {
                doSaveAs();
            } catch (IOException e) {
                JOptionPane.showMessageDialog(this, "I/O error occurred.",
                        "Save As PNG", JOptionPane.WARNING_MESSAGE);
            }
            return true;
        }
        if (command.equals(SAVE_AS_SVG_COMMAND)) {
            try {
                saveAsSVG(null);
            } catch (IOException e) {
                JOptionPane.showMessageDialog(this, "I/O error occurred.",
                        "Save As SVG", JOptionPane.WARNING_MESSAGE);
            }
            return true;
        }
        if (command.equals(SAVE_AS_PDF_COMMAND)) {
            saveAsPDF(null);
            return true;
        }
        return false;
    }

    /**
     * Handles zoom commands from the popup menu.
     *
     * @param command  the action command.
     * @param x  the x-coordinate (in screen coordinates).
     * @param y  the y-coordinate (in screen coordinates).
     */
    private void handleZoomCommand(String command, double x, double y) {
        if (command.equals(ZOOM_IN_BOTH_COMMAND)) {
            zoomInBoth(x, y);
            return;
        }
        if (command.equals(ZOOM_IN_DOMAIN_COMMAND)) {
            zoomInDomain(x, y);
            return;
        }
        if (command.equals(ZOOM_IN_RANGE_COMMAND)) {
            zoomInRange(x, y);
            return;
        }
        if (command.equals(ZOOM_OUT_BOTH_COMMAND)) {
            zoomOutBoth(x, y);
            return;
        }
        if (command.equals(ZOOM_OUT_DOMAIN_COMMAND)) {
            zoomOutDomain(x, y);
            return;
        }
        if (command.equals(ZOOM_OUT_RANGE_COMMAND)) {
            zoomOutRange(x, y);
            return;
        }
        if (command.equals(ZOOM_RESET_BOTH_COMMAND)) {
            restoreAutoBounds();
            return;
        }
        if (command.equals(ZOOM_RESET_DOMAIN_COMMAND)) {
            restoreAutoDomainBounds();
            return;
        }
        if (command.equals(ZOOM_RESET_RANGE_COMMAND)) {
            restoreAutoRangeBounds();
        }
    }

    /**
     * Handles a 'mouse entered' event. This method changes the tooltip delays
     * of ToolTipManager.sharedInstance() to the possibly different values set
     * for this chart panel.
     *
     * @param e  the mouse event.
     */
    @Override
    public void mouseEntered(MouseEvent e) {
        if (!this.ownToolTipDelaysActive) {
            ToolTipManager ttm = ToolTipManager.sharedInstance();

            this.originalToolTipInitialDelay = ttm.getInitialDelay();
            ttm.setInitialDelay(this.ownToolTipInitialDelay);

            this.originalToolTipReshowDelay = ttm.getReshowDelay();
            ttm.setReshowDelay(this.ownToolTipReshowDelay);

            this.originalToolTipDismissDelay = ttm.getDismissDelay();
            ttm.setDismissDelay(this.ownToolTipDismissDelay);

            this.ownToolTipDelaysActive = true;
        }
    }

    /**
     * Handles a 'mouse exited' event. This method resets the tooltip delays of
     * ToolTipManager.sharedInstance() to their
     * original values in effect before mouseEntered()
     *
     * @param e  the mouse event.
     */
    @Override
    public void mouseExited(MouseEvent e) {
        if (this.ownToolTipDelaysActive) {
            // restore original tooltip dealys
            ToolTipManager ttm = ToolTipManager.sharedInstance();
            ttm.setInitialDelay(this.originalToolTipInitialDelay);
            ttm.setReshowDelay(this.originalToolTipReshowDelay);
            ttm.setDismissDelay(this.originalToolTipDismissDelay);
            this.ownToolTipDelaysActive = false;
        }
    }

    /**
     * Handles a 'mouse pressed' event.
     * <P>
     * This event is the popup trigger on Unix/Linux.  For Windows, the popup
     * trigger is the 'mouse released' event.
     *
     * @param e  The mouse event.
     */
    @Override
    public void mousePressed(MouseEvent e) {
        if (this.chart == null) {
            return;
        }
        Plot plot = this.chart.getPlot();
        int mods = e.getModifiers();
        if ((mods & this.panMask) == this.panMask) {
            // can we pan this plot?
            if (plot instanceof Pannable) {
                Pannable pannable = (Pannable) plot;
                if (pannable.isDomainPannable() || pannable.isRangePannable()) {
                    Rectangle2D screenDataArea = getScreenDataArea(e.getX(),
                            e.getY());
                    if (screenDataArea != null && screenDataArea.contains(
                            e.getPoint())) {
                        this.panW = screenDataArea.getWidth();
                        this.panH = screenDataArea.getHeight();
                        this.panLast = e.getPoint();
                        setCursor(Cursor.getPredefinedCursor(
                                Cursor.MOVE_CURSOR));
                    }
                }
                // the actual panning occurs later in the mouseDragged() 
                // method
            }
        }
        else if (this.zoomRectangle == null) {
            Rectangle2D screenDataArea = getScreenDataArea(e.getX(), e.getY());
            if (screenDataArea != null) {
                this.zoomPoint = getPointInRectangle(e.getX(), e.getY(),
                        screenDataArea);
            }
            else {
                this.zoomPoint = null;
            }
            if (e.isPopupTrigger()) {
                if (this.popup != null) {
                    displayPopupMenu(e.getX(), e.getY());
                }
            }
        }
    }

    /**
     * Returns a point based on (x, y) but constrained to be within the bounds
     * of the given rectangle.  This method could be moved to JCommon.
     *
     * @param x  the x-coordinate.
     * @param y  the y-coordinate.
     * @param area  the rectangle (<code>null</code> not permitted).
     *
     * @return A point within the rectangle.
     */
    private Point2D getPointInRectangle(int x, int y, Rectangle2D area) {
        double xx = Math.max(area.getMinX(), Math.min(x, area.getMaxX()));
        double yy = Math.max(area.getMinY(), Math.min(y, area.getMaxY()));
        return new Point2D.Double(xx, yy);
    }

    /**
     * Handles a 'mouse dragged' event.
     *
     * @param e  the mouse event.
     */
    @Override
    public void mouseDragged(MouseEvent e) {
        if (this.popup != null && this.popup.isShowing()) {
            return;
        }
        if (handlePanning(e)) {
            return;
        }
        if (this.zoomPoint == null) {
            return;
        }
        Graphics2D g2 = (Graphics2D) getGraphics();
        try {
            if (!this.useBuffer) {
                drawZoomRectangle(g2, true);
            }
            updateZoomRectangle(e);
            if (this.useBuffer) {
                repaint();
            } else {
                drawZoomRectangle(g2, true);
            }
        } finally {
            g2.dispose();
        }
    }

    /**
     * Handles panning during a mouse drag.
     *
     * @param e  the mouse event.
     *
     * @return <code>true</code> if the event was consumed as a pan gesture.
     */
    private boolean handlePanning(MouseEvent e) {
        if (this.panLast == null) {
            return false;
        }
        double dx = e.getX() - this.panLast.getX();
        double dy = e.getY() - this.panLast.getY();
        if (dx == 0.0 && dy == 0.0) {
            return true;
        }
        double wPercent = -dx / this.panW;
        double hPercent = dy / this.panH;
        boolean old = this.chart.getPlot().isNotify();
        this.chart.getPlot().setNotify(false);
        Pannable p = (Pannable) this.chart.getPlot();
        if (p.getOrientation() == PlotOrientation.VERTICAL) {
            p.panDomainAxes(wPercent, this.info.getPlotInfo(), this.panLast);
            p.panRangeAxes(hPercent, this.info.getPlotInfo(), this.panLast);
        } else {
            p.panDomainAxes(hPercent, this.info.getPlotInfo(), this.panLast);
            p.panRangeAxes(wPercent, this.info.getPlotInfo(), this.panLast);
        }
        this.panLast = e.getPoint();
        this.chart.getPlot().setNotify(old);
        return true;
    }

    /**
     * Updates the zoom rectangle based on the current mouse position.
     *
     * @param e  the mouse event.
     */
    private void updateZoomRectangle(MouseEvent e) {
        boolean hZoom = isHorizontalZoom();
        boolean vZoom = isVerticalZoom();
        Rectangle2D scaledDataArea = getScreenDataArea(
                (int) this.zoomPoint.getX(), (int) this.zoomPoint.getY());
        if (hZoom && vZoom) {
            double xmax = Math.min(e.getX(), scaledDataArea.getMaxX());
            double ymax = Math.min(e.getY(), scaledDataArea.getMaxY());
            this.zoomRectangle = new Rectangle2D.Double(
                    this.zoomPoint.getX(), this.zoomPoint.getY(),
                    xmax - this.zoomPoint.getX(),
                    ymax - this.zoomPoint.getY());
        } else if (hZoom) {
            double xmax = Math.min(e.getX(), scaledDataArea.getMaxX());
            this.zoomRectangle = new Rectangle2D.Double(
                    this.zoomPoint.getX(), scaledDataArea.getMinY(),
                    xmax - this.zoomPoint.getX(),
                    scaledDataArea.getHeight());
        } else if (vZoom) {
            double ymax = Math.min(e.getY(), scaledDataArea.getMaxY());
            this.zoomRectangle = new Rectangle2D.Double(
                    scaledDataArea.getMinX(), this.zoomPoint.getY(),
                    scaledDataArea.getWidth(),
                    ymax - this.zoomPoint.getY());
        }
    }

    /**
     * Returns whether horizontal zooming is enabled, taking the current
     * plot orientation into account.
     *
     * @return A boolean.
     */
    private boolean isHorizontalZoom() {
        if (this.orientation == PlotOrientation.HORIZONTAL) {
            return this.rangeZoomable;
        }
        return this.domainZoomable;
    }

    /**
     * Returns whether vertical zooming is enabled, taking the current
     * plot orientation into account.
     *
     * @return A boolean.
     */
    private boolean isVerticalZoom() {
        if (this.orientation == PlotOrientation.HORIZONTAL) {
            return this.domainZoomable;
        }
        return this.rangeZoomable;
    }

    /**
     * Handles a 'mouse released' event.  On Windows, we need to check if this
     * is a popup trigger, but only if we haven't already been tracking a zoom
     * rectangle.
     *
     * @param e  information about the event.
     */
    @Override
    public void mouseReleased(MouseEvent e) {
        if (handlePanningRelease()) {
            return;
        }
        if (handleZoomRelease(e)) {
            return;
        }
        if (e.isPopupTrigger() && this.popup != null) {
            displayPopupMenu(e.getX(), e.getY());
        }
    }

    /**
     * Resets panning state when the mouse is released.
     *
     * @return <code>true</code> if panning was active.
     */
    private boolean handlePanningRelease() {
        if (this.panLast != null) {
            this.panLast = null;
            setCursor(Cursor.getDefaultCursor());
            return true;
        }
        return false;
    }

    /**
     * Finalises the zoom operation when the mouse is released.
     *
     * @param e  the mouse event.
     *
     * @return <code>true</code> if a zoom rectangle was being tracked.
     */
    private boolean handleZoomRelease(MouseEvent e) {
        if (this.zoomRectangle == null) {
            return false;
        }
        boolean hZoom = isHorizontalZoom();
        boolean vZoom = isVerticalZoom();
        if (isZoomTriggerReached(e, hZoom, vZoom)) {
            if (isRestoreAutoBounds(e, hZoom, vZoom)) {
                restoreAutoBounds();
            } else {
                zoomToRectangle(hZoom, vZoom);
            }
        } else {
            eraseZoomRectangle();
        }
        this.zoomPoint = null;
        this.zoomRectangle = null;
        return true;
    }

    /**
     * Returns whether the mouse has been dragged far enough to trigger a zoom.
     *
     * @param e  the mouse event.
     * @param hZoom  horizontal zoom enabled.
     * @param vZoom  vertical zoom enabled.
     *
     * @return A boolean.
     */
    private boolean isZoomTriggerReached(MouseEvent e, boolean hZoom,
            boolean vZoom) {
        boolean trigger1 = hZoom && Math.abs(e.getX() - this.zoomPoint.getX())
                >= this.zoomTriggerDistance;
        boolean trigger2 = vZoom && Math.abs(e.getY() - this.zoomPoint.getY())
                >= this.zoomTriggerDistance;
        return trigger1 || trigger2;
    }

    /**
     * Returns whether the drag direction indicates that auto bounds should be
     * restored.
     *
     * @param e  the mouse event.
     * @param hZoom  horizontal zoom enabled.
     * @param vZoom  vertical zoom enabled.
     *
     * @return A boolean.
     */
    private boolean isRestoreAutoBounds(MouseEvent e, boolean hZoom,
            boolean vZoom) {
        return (hZoom && (e.getX() < this.zoomPoint.getX()))
                || (vZoom && (e.getY() < this.zoomPoint.getY()));
    }

    /**
     * Performs the zoom operation for the current zoom rectangle.
     *
     * @param hZoom  horizontal zoom enabled.
     * @param vZoom  vertical zoom enabled.
     */
    private void zoomToRectangle(boolean hZoom, boolean vZoom) {
        Rectangle2D screenDataArea = getScreenDataArea(
                (int) this.zoomPoint.getX(), (int) this.zoomPoint.getY());
        double maxX = screenDataArea.getMaxX();
        double maxY = screenDataArea.getMaxY();
        double x, y, w, h;
        if (!vZoom) {
            x = this.zoomPoint.getX();
            y = screenDataArea.getMinY();
            w = Math.min(this.zoomRectangle.getWidth(),
                    maxX - this.zoomPoint.getX());
            h = screenDataArea.getHeight();
        } else if (!hZoom) {
            x = screenDataArea.getMinX();
            y = this.zoomPoint.getY();
            w = screenDataArea.getWidth();
            h = Math.min(this.zoomRectangle.getHeight(),
                    maxY - this.zoomPoint.getY());
        } else {
            x = this.zoomPoint.getX();
            y = this.zoomPoint.getY();
            w = Math.min(this.zoomRectangle.getWidth(),
                    maxX - this.zoomPoint.getX());
            h = Math.min(this.zoomRectangle.getHeight(),
                    maxY - this.zoomPoint.getY());
        }
        Rectangle2D zoomArea = new Rectangle2D.Double(x, y, w, h);
        zoom(zoomArea);
    }

    /**
     * Erases the zoom rectangle from the screen.
     */
    private void eraseZoomRectangle() {
        Graphics2D g2 = (Graphics2D) getGraphics();
        try {
            if (this.useBuffer) {
                repaint();
            } else {
                drawZoomRectangle(g2, true);
            }
        } finally {
            g2.dispose();
        }
    }

    /**
     * Receives notification of mouse clicks on the panel. These are
     * translated and passed on to any registered {@link ChartMouseListener}s.
     *
     * @param event  Information about the mouse event.
     */
    @Override
    public void mouseClicked(MouseEvent event) {

        Insets insets = getInsets();
        int x = (int) ((event.getX() - insets.left) / this.scaleX);
        int y = (int) ((event.getY() - insets.top) / this.scaleY);

        this.anchor = new Point2D.Double(x, y);
        if (this.chart == null) {
            return;
        }
        this.chart.setNotify(true);  // force a redraw
        // new entity code...
        Object[] listeners = this.chartMouseListeners.getListeners(
                ChartMouseListener.class);
        if (listeners.length == 0) {
            return;
        }

        ChartEntity entity = null;
        if (this.info != null) {
            EntityCollection entities = this.info.getEntityCollection();
            if (entities != null) {
                entity = entities.getEntity(x, y);
            }
        }
        ChartMouseEvent chartEvent = new ChartMouseEvent(getChart(), event,
                entity);
        for (int i = listeners.length - 1; i >= 0; i -= 1) {
            ((ChartMouseListener) listeners[i]).chartMouseClicked(chartEvent);
        }

    }

    /**
     * Implementation of the MouseMotionListener's method.
     *
     * @param e  the event.
     */
    @Override
    public void mouseMoved(MouseEvent e) {
        Graphics2D g2 = (Graphics2D) getGraphics();
        if (this.horizontalAxisTrace) {
            drawHorizontalAxisTrace(g2, e.getX());
        }
        if (this.verticalAxisTrace) {
            drawVerticalAxisTrace(g2, e.getY());
        }
        g2.dispose();

        Object[] listeners = this.chartMouseListeners.getListeners(
                ChartMouseListener.class);
        if (listeners.length == 0) {
            return;
        }
        Insets insets = getInsets();
        int x = (int) ((e.getX() - insets.left) / this.scaleX);
        int y = (int) ((e.getY() - insets.top) / this.scaleY);

        ChartEntity entity = null;
        if (this.info != null) {
            EntityCollection entities = this.info.getEntityCollection();
            if (entities != null) {
                entity = entities.getEntity(x, y);
            }
        }

        // we can only generate events if the panel's chart is not null
        // (see bug report 1556951)
        if (this.chart != null) {
            ChartMouseEvent event = new ChartMouseEvent(getChart(), e, entity);
            for (int i = listeners.length - 1; i >= 0; i -= 1) {
                ((ChartMouseListener) listeners[i]).chartMouseMoved(event);
            }
        }

    }

