    /**
     * Opens a file chooser and gives the user an opportunity to save the chart
     * in PNG format.
     *
     * @throws IOException if there is an I/O error.
     */
    public void doSaveAs() throws IOException {
        JFileChooser fileChooser = new JFileChooser();
        fileChooser.setCurrentDirectory(this.defaultDirectoryForSaveAs);
        FileNameExtensionFilter filter = new FileNameExtensionFilter(
                    localizationResources.getString("PNG_Image_Files"), "png");
        fileChooser.addChoosableFileFilter(filter);
        fileChooser.setFileFilter(filter);

        int option = fileChooser.showSaveDialog(this);
        if (option == JFileChooser.APPROVE_OPTION) {
            String filename = fileChooser.getSelectedFile().getPath();
            if (isEnforceFileExtensions()) {
                if (!filename.endsWith(".png")) {
                    filename = filename + ".png";
                }
            }
            ChartUtilities.saveChartAsPNG(new File(filename), this.chart,
                    getWidth(), getHeight());
        }
    }

    /**
     * Prompts the user for a save file with the given extension.
     *
     * @param extension  the required file extension (without the dot).
     * @param descriptionKey  the resource bundle key for the file filter
     *                        description.
     * @param dialogTitle  the title for the overwrite confirmation dialog.
     *
     * @return The selected file, or <code>null</code> if the user cancelled.
     */
    private File chooseSaveFile(String extension, String descriptionKey,
            String dialogTitle) {
        JFileChooser fileChooser = new JFileChooser();
        fileChooser.setCurrentDirectory(this.defaultDirectoryForSaveAs);
        FileNameExtensionFilter filter = new FileNameExtensionFilter(
                localizationResources.getString(descriptionKey), extension);
        fileChooser.addChoosableFileFilter(filter);
        fileChooser.setFileFilter(filter);

        int option = fileChooser.showSaveDialog(this);
        if (option != JFileChooser.APPROVE_OPTION) {
            return null;
        }
        String filename = fileChooser.getSelectedFile().getPath();
        if (isEnforceFileExtensions()) {
            if (!filename.endsWith("." + extension)) {
                filename = filename + "." + extension;
            }
        }
        File file = new File(filename);
        if (file.exists()) {
            String fileExists = localizationResources.getString(
                    "FILE_EXISTS_CONFIRM_OVERWRITE");
            int response = JOptionPane.showConfirmDialog(this, fileExists,
                    dialogTitle, JOptionPane.OK_CANCEL_OPTION);
            if (response == JOptionPane.CANCEL_OPTION) {
                file = null;
            }
        }
        return file;
    }

    /**
     * Saves the chart in SVG format (a filechooser will be displayed so that
     * the user can specify the filename).  Note that this method only works
     * if the JFreeSVG library is on the classpath...if this library is not 
     * present, the method will fail.
     */
    private void saveAsSVG(File f) throws IOException {
        File file = f;
        if (file == null) {
            file = chooseSaveFile("svg", "SVG_Files", "Save As SVG");
        }
        if (file != null) {
            String svg = generateSVG(getWidth(), getHeight());
            BufferedWriter writer = null;
