private Rectangle2D calculateAvailableArea() {
    Dimension size = getSize();
    Insets insets = getInsets();
    return new Rectangle2D.Double(insets.left, insets.top,
        size.getWidth() - insets.left - insets.right,
        size.getHeight() - insets.top - insets.bottom);
}

private boolean updateScaleFactors(double availableWidth, double availableHeight) {
    this.scaleX = 1.0;
    this.scaleY = 1.0;
    boolean scale = false;
    if (availableWidth < this.minimumDrawWidth) {
        this.scaleX = availableWidth / this.minimumDrawWidth;
        scale = true;
    } else if (availableWidth > this.maximumDrawWidth) {
        this.scaleX = availableWidth / this.maximumDrawWidth;
        scale = true;
    }
    if (availableHeight < this.minimumDrawHeight) {
        this.scaleY = availableHeight / this.minimumDrawHeight;
        scale = true;
    } else if (availableHeight > this.maximumDrawHeight) {
        this.scaleY = availableHeight / this.maximumDrawHeight;
        scale = true;
    }
    return scale;
}

private Rectangle2D createChartArea(double availableWidth, double availableHeight, boolean scale) {
    double drawWidth = availableWidth;
    double drawHeight = availableHeight;
    if (scale) {
        if (drawWidth < this.minimumDrawWidth) drawWidth = this.minimumDrawWidth;
        else if (drawWidth > this.maximumDrawWidth) drawWidth = this.maximumDrawWidth;
        if (drawHeight < this.minimumDrawHeight) drawHeight = this.minimumDrawHeight;
        else if (drawHeight > this.maximumDrawHeight) drawHeight = this.maximumDrawHeight;
    }
    return new Rectangle2D.Double(0.0, 0.0, drawWidth, drawHeight);
}

