public void paintComponent(Graphics g) {
    super.paintComponent(g);
    if (this.chart == null) {
        return;
    }
    Graphics2D g2 = (Graphics2D) g.create();
    try {
        Rectangle2D available = calculateAvailableArea();
        ScaleResult scaleResult = updateScaleFactors(available);
        Rectangle2D chartArea = createChartArea(scaleResult);
        if (this.useBuffer) {
            drawChartToBuffer(g2, available, chartArea, scaleResult.scale);
        } else {
            drawChartDirectly(g2, chartArea, scaleResult.scale);
        }
        paintOverlays(g2);
        drawZoomRectangle(g2, !this.useBuffer);
    } finally {
        g2.dispose();
    }
    clearTransientState();
}

