private void ensureBufferSized(Graphics2D panelG2, Rectangle2D available) {
    int width = (int) available.getWidth();
    int height = (int) available.getHeight();
    if (this.chartBuffer == null
            || this.chartBufferWidth != width
            || this.chartBufferHeight != height) {
        this.chartBufferWidth = width;
        this.chartBufferHeight = height;
        GraphicsConfiguration gc = panelG2.getDeviceConfiguration();
        this.chartBuffer = gc.createCompatibleImage(this.chartBufferWidth,
                this.chartBufferHeight, Transparency.TRANSLUCENT);
        this.refreshBuffer = true;
    }
}

