private boolean handleZoomRelease(MouseEvent e) {
    if (this.zoomRectangle == null) {
        return false;
    }
    boolean hZoom = isHorizontalZoom();
    boolean vZoom = isVerticalZoom();
    if (isZoomTriggerReached(e, hZoom, vZoom)) {
        if (isRestoreAutoBounds(e, hZoom, vZoom)) {
            restoreAutoBounds();
        } else {
            zoomToRectangle(hZoom, vZoom);
        }
    } else {
        eraseZoomRectangle();
    }
    this.zoomPoint = null;
    this.zoomRectangle = null;
    return true;
}

private boolean isZoomTriggerReached(MouseEvent e, boolean hZoom, boolean vZoom) {
    boolean trigger1 = hZoom && Math.abs(e.getX() - this.zoomPoint.getX())
            >= this.zoomTriggerDistance;
    boolean trigger2 = vZoom && Math.abs(e.getY() - this.zoomPoint.getY())
            >= this.zoomTriggerDistance;
    return trigger1 || trigger2;
}

private boolean isRestoreAutoBounds(MouseEvent e, boolean hZoom, boolean vZoom) {
    return (hZoom && (e.getX() < this.zoomPoint.getX()))
            || (vZoom && (e.getY() < this.zoomPoint.getY()));
}

private void zoomToRectangle(boolean hZoom, boolean vZoom) {
    Rectangle2D screenDataArea = getScreenDataArea(
            (int) this.zoomPoint.getX(), (int) this.zoomPoint.getY());
    double maxX = screenDataArea.getMaxX();
    double maxY = screenDataArea.getMaxY();
    double x, y, w, h;
    if (!vZoom) {
        x = this.zoomPoint.getX();
        y = screenDataArea.getMinY();
        w = Math.min(this.zoomRectangle.getWidth(),
                maxX - this.zoomPoint.getX());
        h = screenDataArea.getHeight();
    } else if (!hZoom) {
        x = screenDataArea.getMinX();
        y = this.zoomPoint.getY();
        w = screenDataArea.getWidth();
        h = Math.min(this.zoomRectangle.getHeight(),
                maxY - this.zoomPoint.getY());
    } else {
        x = this.zoomPoint.getX();
        y = this.zoomPoint.getY();
        w = Math.min(this.zoomRectangle.getWidth(),
                maxX - this.zoomPoint.getX());
        h = Math.min(this.zoomRectangle.getHeight(),
                maxY - this.zoomPoint.getY());
    }
    Rectangle2D zoomArea = new Rectangle2D.Double(x, y, w, h);
    zoom(zoomArea);
}

private void eraseZoomRectangle() {
    Graphics2D g2 = (Graphics2D) getGraphics();
    try {
        if (this.useBuffer) {
            repaint();
        } else {
            drawZoomRectangle(g2, true);
        }
    } finally {
        g2.dispose();
    }
}

