private File chooseSaveFile(String extension, String description, String dialogTitle) {
    JFileChooser fileChooser = new JFileChooser();
    fileChooser.setCurrentDirectory(this.defaultDirectoryForSaveAs);
    FileNameExtensionFilter filter = new FileNameExtensionFilter(
            localizationResources.getString(description), extension);
    fileChooser.addChoosableFileFilter(filter);
    fileChooser.setFileFilter(filter);

    int option = fileChooser.showSaveDialog(this);
    if (option != JFileChooser.APPROVE_OPTION) {
        return null;
    }
    String filename = fileChooser.getSelectedFile().getPath();
    if (isEnforceFileExtensions()) {
        if (!filename.endsWith("." + extension)) {
            filename = filename + "." + extension;
        }
    }
    File file = new File(filename);
    if (file.exists()) {
        String fileExists = localizationResources.getString(
                "FILE_EXISTS_CONFIRM_OVERWRITE");
        int response = JOptionPane.showConfirmDialog(this, fileExists,
                dialogTitle, JOptionPane.OK_CANCEL_OPTION);
        if (response == JOptionPane.CANCEL_OPTION) {
            file = null;
        }
    }
    return file;
}

