protected JPopupMenu createPopupMenu(boolean properties,
        boolean copy, boolean save, boolean print, boolean zoom) {

    JPopupMenu result = new JPopupMenu(localizationResources.getString("Chart") + ":");
    boolean hasItems = false;

    if (properties) {
        appendPropertiesItem(result);
        hasItems = true;
    }
    if (copy) {
        if (hasItems) {
            result.addSeparator();
        }
        appendCopyItem(result);
        hasItems = true;
    }
    if (save) {
        if (hasItems) {
            result.addSeparator();
        }
        appendSaveMenu(result);
        hasItems = true;
    }
    if (print) {
        if (hasItems) {
            result.addSeparator();
        }
        appendPrintItem(result);
        hasItems = true;
    }
    if (zoom) {
        if (hasItems) {
            result.addSeparator();
        }
        appendZoomMenu(result);
    }

    return result;
}

