    /**
     * A configuration object that groups the panel sizing, buffering and
     * popup-menu option parameters used by the constructors.
     */
    private static class Configuration {
        /** The preferred width. */
        int width;
        /** The preferred height. */
        int height;
        /** The minimum drawing width. */
        int minimumDrawWidth;
        /** The minimum drawing height. */
        int minimumDrawHeight;
        /** The maximum drawing width. */
        int maximumDrawWidth;
        /** The maximum drawing height. */
        int maximumDrawHeight;
        /** A flag that indicates whether to use the off-screen buffer. */
        boolean useBuffer;
        /** A flag indicating whether the properties item is available. */
        boolean properties;
        /** A flag indicating whether the copy item is available. */
        boolean copy;
        /** A flag indicating whether the save item is available. */
        boolean save;
        /** A flag indicating whether the print item is available. */
        boolean print;
        /** A flag indicating whether zoom items are available. */
        boolean zoom;
        /** A flag indicating whether tooltips are enabled. */
        boolean tooltips;

        /**
         * Returns a builder pre-populated with the default configuration.
         *
         * @return A builder.
         */
        static Builder newBuilder() {
            return new Builder();
        }

        /**
         * Builder for {@link Configuration}.
         */
        static class Builder {
            private int width = DEFAULT_WIDTH;
            private int height = DEFAULT_HEIGHT;
            private int minimumDrawWidth = DEFAULT_MINIMUM_DRAW_WIDTH;
            private int minimumDrawHeight = DEFAULT_MINIMUM_DRAW_HEIGHT;
            private int maximumDrawWidth = DEFAULT_MAXIMUM_DRAW_WIDTH;
            private int maximumDrawHeight = DEFAULT_MAXIMUM_DRAW_HEIGHT;
            private boolean useBuffer = DEFAULT_BUFFER_USED;
            private boolean properties = true;
            private boolean copy = true;
            private boolean save = true;
            private boolean print = true;
            private boolean zoom = true;
            private boolean tooltips = true;

            Builder width(int width) {
                this.width = width;
                return this;
            }

            Builder height(int height) {
                this.height = height;
                return this;
            }

            Builder minimumDrawWidth(int minimumDrawWidth) {
                this.minimumDrawWidth = minimumDrawWidth;
                return this;
            }

            Builder minimumDrawHeight(int minimumDrawHeight) {
                this.minimumDrawHeight = minimumDrawHeight;
                return this;
            }

            Builder maximumDrawWidth(int maximumDrawWidth) {
                this.maximumDrawWidth = maximumDrawWidth;
                return this;
            }

            Builder maximumDrawHeight(int maximumDrawHeight) {
                this.maximumDrawHeight = maximumDrawHeight;
                return this;
            }

            Builder useBuffer(boolean useBuffer) {
                this.useBuffer = useBuffer;
                return this;
            }

            Builder properties(boolean properties) {
                this.properties = properties;
                return this;
            }

            Builder copy(boolean copy) {
                this.copy = copy;
                return this;
            }

            Builder save(boolean save) {
                this.save = save;
                return this;
            }

            Builder print(boolean print) {
                this.print = print;
                return this;
            }

            Builder zoom(boolean zoom) {
                this.zoom = zoom;
                return this;
            }

            Builder tooltips(boolean tooltips) {
                this.tooltips = tooltips;
                return this;
            }

            Configuration build() {
                Configuration config = new Configuration();
                config.width = this.width;
                config.height = this.height;
                config.minimumDrawWidth = this.minimumDrawWidth;
                config.minimumDrawHeight = this.minimumDrawHeight;
                config.maximumDrawWidth = this.maximumDrawWidth;
                config.maximumDrawHeight = this.maximumDrawHeight;
                config.useBuffer = this.useBuffer;
                config.properties = this.properties;
                config.copy = this.copy;
                config.save = this.save;
                config.print = this.print;
                config.zoom = this.zoom;
                config.tooltips = this.tooltips;
                return config;
            }
        }
    }

