    /**
     * Default constructor.
     */
    public PolarPlot() {
        this(null, null, null);
    }

   /**
     * Creates a new plot.
     *
     * @param dataset  the dataset (<code>null</code> permitted).
     * @param radiusAxis  the radius axis (<code>null</code> permitted).
     * @param renderer  the renderer (<code>null</code> permitted).
     */
    public PolarPlot(XYDataset dataset, ValueAxis radiusAxis,
                PolarItemRenderer renderer) {

        super();

        this.datasets = new ObjectList();
        this.datasets.set(0, dataset);
        if (dataset != null) {
            dataset.addChangeListener(this);
        }
        this.angleTickUnit = new NumberTickUnit(DEFAULT_ANGLE_TICK_UNIT_SIZE);

        this.axes = new ObjectList();
        this.datasetToAxesMap = new TreeMap();
        this.axes.set(0, radiusAxis);
        if (radiusAxis != null) {
            radiusAxis.setPlot(this);
            radiusAxis.addChangeListener(this);
        }

        // define the default locations for up to 8 axes...
        this.axisLocations = new ObjectList();
        this.axisLocations.set(0, PolarAxisLocation.EAST_ABOVE);
        this.axisLocations.set(1, PolarAxisLocation.NORTH_LEFT);
        this.axisLocations.set(2, PolarAxisLocation.WEST_BELOW);
        this.axisLocations.set(3, PolarAxisLocation.SOUTH_RIGHT);
        this.axisLocations.set(4, PolarAxisLocation.EAST_BELOW);
        this.axisLocations.set(5, PolarAxisLocation.NORTH_RIGHT);
        this.axisLocations.set(6, PolarAxisLocation.WEST_ABOVE);
        this.axisLocations.set(7, PolarAxisLocation.SOUTH_LEFT);

        this.renderers = new ObjectList();
        this.renderers.set(0, renderer);
        if (renderer != null) {
            renderer.setPlot(this);
            renderer.addChangeListener(this);
        }

        this.angleOffset = DEFAULT_ANGLE_OFFSET;
        this.counterClockwise = false;
        this.angleGridlinesVisible = true;
        this.angleGridlineStroke = DEFAULT_GRIDLINE_STROKE;
        this.angleGridlinePaint = DEFAULT_GRIDLINE_PAINT;

        this.radiusGridlinesVisible = true;
        this.radiusMinorGridlinesVisible = true;
        this.radiusGridlineStroke = DEFAULT_GRIDLINE_STROKE;
        this.radiusGridlinePaint = DEFAULT_GRIDLINE_PAINT;
        this.margin = DEFAULT_MARGIN;
    }

    /**
     * Creates a deep copy of the given plot.
     *
     * @param original  the original plot (<code>null</code> not permitted).
     *
     * @throws CloneNotSupportedException  if some component of the plot cannot
     *         be cloned.
     */
    public PolarPlot(PolarPlot original) throws CloneNotSupportedException {
        super();
        ParamChecks.nullNotPermitted(original, "original");

        // Copy inherited Plot properties.
        setBackgroundPaint(original.getBackgroundPaint());
        setBackgroundImage(original.getBackgroundImage());
        setBackgroundImageAlignment(original.getBackgroundImageAlignment());
        setBackgroundImageAlpha(original.getBackgroundImageAlpha());
        setBackgroundAlpha(original.getBackgroundAlpha());
        setOutlinePaint(original.getOutlinePaint());
        setOutlineStroke(original.getOutlineStroke());
        setOutlineVisible(original.isOutlineVisible());
        setInsets(original.getInsets());
        setForegroundAlpha(original.getForegroundAlpha());
        setNoDataMessage(original.getNoDataMessage());
        setNoDataMessageFont(original.getNoDataMessageFont());
        setNoDataMessagePaint(original.getNoDataMessagePaint());
        setDatasetGroup(original.getDatasetGroup());
        setParent(original.getParent());

        // Copy local properties.
        this.angleTicks = null;

        this.axes = new ObjectList();
        for (int i = 0; i < original.axes.size(); i++) {
            ValueAxis axis = (ValueAxis) original.axes.get(i);
            if (axis != null) {
                ValueAxis clonedAxis = (ValueAxis) axis.clone();
                this.axes.set(i, clonedAxis);
                clonedAxis.setPlot(this);
                clonedAxis.addChangeListener(this);
            }
        }

        this.axisLocations = new ObjectList();
        for (int i = 0; i < original.axisLocations.size(); i++) {
            this.axisLocations.set(i, original.axisLocations.get(i));
        }

        this.datasets = new ObjectList();
        for (int i = 0; i < original.datasets.size(); i++) {
            XYDataset d = (XYDataset) original.datasets.get(i);
            this.datasets.set(i, d);
            if (d != null) {
                d.addChangeListener(this);
            }
        }

        this.renderers = new ObjectList();
        for (int i = 0; i < original.renderers.size(); i++) {
            PolarItemRenderer renderer = (PolarItemRenderer) original.renderers.get(i);
            if (renderer instanceof PublicCloneable) {
                PublicCloneable pc = (PublicCloneable) renderer;
                PolarItemRenderer rc = (PolarItemRenderer) pc.clone();
                this.renderers.set(i, rc);
                rc.setPlot(this);
                rc.addChangeListener(this);
            }
            else {
                this.renderers.set(i, renderer);
                if (renderer != null) {
                    renderer.setPlot(this);
                    renderer.addChangeListener(this);
                }
            }
        }

        this.angleTickUnit = original.angleTickUnit;
        this.angleOffset = original.angleOffset;
        this.counterClockwise = original.counterClockwise;
        this.angleLabelsVisible = original.angleLabelsVisible;
        this.angleLabelFont = original.angleLabelFont;
        this.angleLabelPaint = original.angleLabelPaint;
        this.angleGridlinesVisible = original.angleGridlinesVisible;
        this.angleGridlineStroke = original.angleGridlineStroke;
        this.angleGridlinePaint = original.angleGridlinePaint;
        this.radiusGridlinesVisible = original.radiusGridlinesVisible;
        this.radiusGridlineStroke = original.radiusGridlineStroke;
        this.radiusGridlinePaint = original.radiusGridlinePaint;
        this.radiusMinorGridlinesVisible = original.radiusMinorGridlinesVisible;
        this.cornerTextItems = new ArrayList(original.cornerTextItems);
        this.margin = original.margin;
        this.fixedLegendItems = original.fixedLegendItems;

        this.datasetToAxesMap = new TreeMap();
        for (Object entry : original.datasetToAxesMap.entrySet()) {
            Map.Entry e = (Map.Entry) entry;
            List axesList = (List) e.getValue();
            this.datasetToAxesMap.put(e.getKey(), new ArrayList(axesList));
        }

        if (!original.isNotify()) {
            setNotify(false);
        }
    }

    /**
