    /**
     * Generates a list of tick values for the angular tick marks.
     *
     * @return A list of {@link NumberTick} instances.
     *
     * @since 1.0.10
     */
    protected List refreshAngleTicks() {
        List ticks = new ArrayList();
        for (double currentTickVal = 0.0; currentTickVal < 360.0;
                currentTickVal += this.angleTickUnit.getSize()) {

            TextAnchor ta = calculateTextAnchor(currentTickVal);
            NumberTick tick = new NumberTick(new Double(currentTickVal),
                this.angleTickUnit.valueToString(currentTickVal),
                ta, TextAnchor.CENTER, 0.0);
            ticks.add(tick);
        }
        return ticks;
    }

    /**
     * Calculate the text position for the given degrees.
     *
     * @param angleDegrees  the angle in degrees.
     * 
     * @return The optimal text anchor.
     * @since 1.0.14
     */
    protected TextAnchor calculateTextAnchor(double angleDegrees) {
        return selectTextAnchorForAngle(normalizeAngle(angleDegrees));
    }

    /**
     * Normalizes the supplied angle using the current offset and direction
     * settings.
     *
     * @param angleDegrees  the raw angle in degrees.
     *
     * @return The normalized angle.
     */
    private double normalizeAngle(double angleDegrees) {
        double offset = this.angleOffset;
        while (offset < 0.0) {
            offset += 360.0;
        }
        double normalizedAngle = (((this.counterClockwise ? -1 : 1)
                * angleDegrees) + offset) % 360;
        while (this.counterClockwise && (normalizedAngle < 0.0)) {
            normalizedAngle += 360.0;
        }
        return normalizedAngle;
    }

    /**
     * Selects the text anchor for a normalized angle.
     *
     * @param normalizedAngle  the normalized angle in degrees.
     *
     * @return The matching text anchor.
     */
    private TextAnchor selectTextAnchorForAngle(double normalizedAngle) {
        if (normalizedAngle == 0.0) {
            return TextAnchor.CENTER_LEFT;
        }
        else if (normalizedAngle > 0.0 && normalizedAngle < 90.0) {
            return TextAnchor.TOP_LEFT;
        }
        else if (normalizedAngle == 90.0) {
            return TextAnchor.TOP_CENTER;
        }
        else if (normalizedAngle > 90.0 && normalizedAngle < 180.0) {
            return TextAnchor.TOP_RIGHT;
        }
        else if (normalizedAngle == 180) {
            return TextAnchor.CENTER_RIGHT;
        }
        else if (normalizedAngle > 180.0 && normalizedAngle < 270.0) {
            return TextAnchor.BOTTOM_RIGHT;
        }
        else if (normalizedAngle == 270) {
            return TextAnchor.BOTTOM_CENTER;
        }
        else if (normalizedAngle > 270.0 && normalizedAngle < 360.0) {
            return TextAnchor.BOTTOM_LEFT;
        }
        return TextAnchor.CENTER;
    }

    /**
     * Maps a dataset to a particular axis.  All data will be plotted
     * against axis zero by default, no mapping is required for this case.
     *
     * @param index  the dataset index (zero-based).
     * @param axisIndex  the axis index.
     *
     * @since 1.0.14
     */
    public void mapDatasetToAxis(int index, int axisIndex) {
        List axisIndices = new java.util.ArrayList(1);
        axisIndices.add(new Integer(axisIndex));
        mapDatasetToAxes(index, axisIndices);
    }

    /**
     * Maps the specified dataset to the axes in the list.  Note that the
     * conversion of data values into Java2D space is always performed using
     * the first axis in the list.
     *
     * @param index  the dataset index (zero-based).
     * @param axisIndices  the axis indices (<code>null</code> permitted).
     *
     * @since 1.0.14
     */
    public void mapDatasetToAxes(int index, List axisIndices) {
        if (index < 0) {
            throw new IllegalArgumentException("Requires 'index' >= 0.");
        }
        checkAxisIndices(axisIndices);
        Integer key = new Integer(index);
        this.datasetToAxesMap.put(key, new ArrayList(axisIndices));
        // fake a dataset change event to update axes...
        datasetChanged(new DatasetChangeEvent(this, getDataset(index)));
    }

    /**
     * This method is used to perform argument checking on the list of
     * axis indices passed to mapDatasetToAxes().
     *
     * @param indices  the list of indices (<code>null</code> permitted).
     */
    private void checkAxisIndices(List indices) {
        // axisIndices can be:
        // 1.  null;
        // 2.  non-empty, containing only Integer objects that are unique.
        if (indices == null) {
            return;  // OK
        }
        int count = indices.size();
        if (count == 0) {
            throw new IllegalArgumentException("Empty list not permitted.");
        }
        HashSet set = new HashSet();
        for (int i = 0; i < count; i++) {
            Object item = indices.get(i);
            if (!(item instanceof Integer)) {
                throw new IllegalArgumentException(
                        "Indices must be Integer instances.");
            }
            if (set.contains(item)) {
                throw new IllegalArgumentException("Indices must be unique.");
            }
            set.add(item);
        }
    }

    /**
     * Returns the axis for a dataset.
     *
     * @param index  the dataset index.
     *
     * @return The axis.
     *
     * @since 1.0.14
     */
    public ValueAxis getAxisForDataset(int index) {
        ValueAxis valueAxis;
        List axisIndices = (List) this.datasetToAxesMap.get(
                new Integer(index));
        if (axisIndices != null) {
            // the first axis in the list is used for data <--> Java2D
            Integer axisIndex = (Integer) axisIndices.get(0);
            valueAxis = getAxis(axisIndex.intValue());
        }
        else {
            valueAxis = getAxis(0);
        }
        return valueAxis;
    }

    /**
     * Returns the index of the given axis.
     *
     * @param axis  the axis.
     *
     * @return The axis index or -1 if axis is not used in this plot.
     *
     * @since 1.0.14
     */
    public int getAxisIndex(ValueAxis axis) {
        int result = this.axes.indexOf(axis);
        if (result < 0) {
            // try the parent plot
            Plot parent = getParent();
            if (parent instanceof PolarPlot) {
                PolarPlot p = (PolarPlot) parent;
                result = p.getAxisIndex(axis);
            }
        }
        return result;
    }

    /**
     * Returns the index of the specified renderer, or <code>-1</code> if the
     * renderer is not assigned to this plot.
     *
     * @param renderer  the renderer (<code>null</code> permitted).
     *
     * @return The renderer index.
     *
     * @since 1.0.14
     */
    public int getIndexOf(PolarItemRenderer renderer) {
        return this.renderers.indexOf(renderer);
    }

    /**
     * Draws the plot on a Java 2D graphics device (such as the screen or a
     * printer).
     * <P>
     * This plot relies on a {@link PolarItemRenderer} to draw each
     * item in the plot.  This allows the visual representation of the data to
     * be changed easily.
     * <P>
     * The optional info argument collects information about the rendering of
     * the plot (dimensions, tooltip information etc).  Just pass in
     * <code>null</code> if you do not need this information.
     *
     * @param g2  the graphics device.
     * @param area  the area within which the plot (including axes and
     *              labels) should be drawn.
     * @param anchor  the anchor point (<code>null</code> permitted).
     * @param parentState  ignored.
     * @param info  collects chart drawing information (<code>null</code>
     *              permitted).
     */
    @Override
    public void draw(Graphics2D g2, Rectangle2D area, Point2D anchor,
            PlotState parentState, PlotRenderingInfo info) {

        // if the plot area is too small, just return...
        boolean b1 = (area.getWidth() <= MINIMUM_WIDTH_TO_DRAW);
        boolean b2 = (area.getHeight() <= MINIMUM_HEIGHT_TO_DRAW);
        if (b1 || b2) {
            return;
        }

        // record the plot area...
        if (info != null) {
            info.setPlotArea(area);
        }

        // adjust the drawing area for the plot insets (if any)...
        RectangleInsets insets = getInsets();
        insets.trim(area);

        Rectangle2D dataArea = area;
        if (info != null) {
            info.setDataArea(dataArea);
        }

        // draw the plot background and axes...
        drawBackground(g2, dataArea);
        int axisCount = this.axes.size();
        AxisState state = null;
        for (int i = 0; i < axisCount; i++) {
            ValueAxis axis = getAxis(i);
            if (axis != null) {
                PolarAxisLocation location
                        = (PolarAxisLocation) this.axisLocations.get(i);
                AxisState s = this.drawAxis(axis, location, g2, dataArea);
                if (i == 0) {
                    state = s;
                }
            }
        }

        // now for each dataset, get the renderer and the appropriate axis
        // and render the dataset...
        Shape originalClip = g2.getClip();
        Composite originalComposite = g2.getComposite();

        g2.clip(dataArea);
        g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER,
                getForegroundAlpha()));
        this.angleTicks = refreshAngleTicks();
        drawGridlines(g2, dataArea, this.angleTicks, state.getTicks());
        render(g2, dataArea, info);
        g2.setClip(originalClip);
        g2.setComposite(originalComposite);
        drawOutline(g2, dataArea);
        drawCornerTextItems(g2, dataArea);
    }

    /**
     * Draws the corner text items.
     *
     * @param g2  the drawing surface.
     * @param area  the area.
     */
    protected void drawCornerTextItems(Graphics2D g2, Rectangle2D area) {
        if (this.cornerTextItems.isEmpty()) {
            return;
        }

        g2.setColor(Color.black);
        double width = 0.0;
        double height = 0.0;
        for (Iterator it = this.cornerTextItems.iterator(); it.hasNext();) {
            String msg = (String) it.next();
            FontMetrics fm = g2.getFontMetrics();
            Rectangle2D bounds = TextUtilities.getTextBounds(msg, g2, fm);
            width = Math.max(width, bounds.getWidth());
            height += bounds.getHeight();
        }

        double xadj = ANNOTATION_MARGIN * 2.0;
        double yadj = ANNOTATION_MARGIN;
        width += xadj;
        height += yadj;

        double x = area.getMaxX() - width;
        double y = area.getMaxY() - height;
        g2.drawRect((int) x, (int) y, (int) width, (int) height);
        x += ANNOTATION_MARGIN;
        for (Iterator it = this.cornerTextItems.iterator(); it.hasNext();) {
            String msg = (String) it.next();
            Rectangle2D bounds = TextUtilities.getTextBounds(msg, g2,
                    g2.getFontMetrics());
            y += bounds.getHeight();
            g2.drawString(msg, (int) x, (int) y);
        }
    }

    /**
     * Draws the axis with the specified index.
     *
     * @param axis  the axis.
     * @param location  the axis location.
     * @param g2  the graphics target.
     * @param plotArea  the plot area.
     *
     * @return The axis state.
     *
     * @since 1.0.14
     */
    protected AxisState drawAxis(ValueAxis axis, PolarAxisLocation location,
            Graphics2D g2, Rectangle2D plotArea) {

        double centerX = plotArea.getCenterX();
        double centerY = plotArea.getCenterY();
        double r = Math.min(plotArea.getWidth() / 2.0,
                plotArea.getHeight() / 2.0) - this.margin;
        double x = centerX - r;
        double y = centerY - r;

        AxisDrawInfo info = createAxisDrawInfo(location, x, y, centerX, centerY, r);
        if (info == null) {
            return null;
        }

        double anchor = (info.edge == RectangleEdge.RIGHT
                || info.edge == RectangleEdge.LEFT) ? centerX : centerY;
        return axis.draw(g2, anchor, plotArea, info.dataArea, info.edge, null);
    }

    /**
     * Simple holder for the data area and edge used to draw a single axis.
     */
    private static class AxisDrawInfo {
        /** The data area for the axis. */
        final Rectangle2D dataArea;
        /** The edge on which the axis is drawn. */
        final RectangleEdge edge;

        /**
         * Creates a new instance.
         *
         * @param dataArea  the data area.
         * @param edge  the edge.
         */
        AxisDrawInfo(Rectangle2D dataArea, RectangleEdge edge) {
            this.dataArea = dataArea;
            this.edge = edge;
        }
    }

    /**
     * Determines the data area and edge for an axis based on its location.
     *
     * @param location  the axis location.
     * @param x  the left edge of the square axis area.
     * @param y  the top edge of the square axis area.
     * @param centerX  the x-coordinate of the plot center.
     * @param centerY  the y-coordinate of the plot center.
     * @param r  the radius of the square axis area.
     *
     * @return The draw info, or <code>null</code> if the location is unknown.
     */
    private AxisDrawInfo createAxisDrawInfo(PolarAxisLocation location,
            double x, double y, double centerX, double centerY, double r) {
        if (location == PolarAxisLocation.NORTH_RIGHT) {
            return new AxisDrawInfo(new Rectangle2D.Double(x, y, r, r),
                    RectangleEdge.RIGHT);
        }
        else if (location == PolarAxisLocation.NORTH_LEFT) {
            return new AxisDrawInfo(new Rectangle2D.Double(centerX, y, r, r),
                    RectangleEdge.LEFT);
        }
        else if (location == PolarAxisLocation.SOUTH_LEFT) {
            return new AxisDrawInfo(new Rectangle2D.Double(centerX, centerY, r, r),
                    RectangleEdge.LEFT);
        }
        else if (location == PolarAxisLocation.SOUTH_RIGHT) {
            return new AxisDrawInfo(new Rectangle2D.Double(x, centerY, r, r),
                    RectangleEdge.RIGHT);
        }
        else if (location == PolarAxisLocation.EAST_ABOVE) {
            return new AxisDrawInfo(new Rectangle2D.Double(centerX, centerY, r, r),
                    RectangleEdge.TOP);
        }
        else if (location == PolarAxisLocation.EAST_BELOW) {
            return new AxisDrawInfo(new Rectangle2D.Double(centerX, y, r, r),
                    RectangleEdge.BOTTOM);
        }
        else if (location == PolarAxisLocation.WEST_ABOVE) {
            return new AxisDrawInfo(new Rectangle2D.Double(x, centerY, r, r),
                    RectangleEdge.TOP);
        }
        else if (location == PolarAxisLocation.WEST_BELOW) {
            return new AxisDrawInfo(new Rectangle2D.Double(x, y, r, r),
                    RectangleEdge.BOTTOM);
        }
        return null;
    }

    /**
     * Draws a representation of the data within the dataArea region, using the
     * current m_Renderer.
     *
     * @param g2  the graphics device.
     * @param dataArea  the region in which the data is to be drawn.
     * @param info  an optional object for collection dimension
     *              information (<code>null</code> permitted).
     */
    protected void render(Graphics2D g2, Rectangle2D dataArea,
            PlotRenderingInfo info) {

        // now get the data and plot it (the visual representation will depend
        // on the m_Renderer that has been set)...
        boolean hasData = false;
        int datasetCount = this.datasets.size();
        for (int i = datasetCount - 1; i >= 0; i--) {
            XYDataset dataset = getDataset(i);
            if (dataset == null) {
                continue;
            }
            PolarItemRenderer renderer = getRenderer(i);
            if (renderer == null) {
                continue;
            }
            if (!DatasetUtilities.isEmptyOrNull(dataset)) {
                hasData = true;
                int seriesCount = dataset.getSeriesCount();
                for (int series = 0; series < seriesCount; series++) {
                    renderer.drawSeries(g2, dataArea, info, this, dataset,
                            series);
                }
            }
        }
        if (!hasData) {
            drawNoDataMessage(g2, dataArea);
        }
    }

    /**
     * Draws the gridlines for the plot, if they are visible.
     *
     * @param g2  the graphics device.
     * @param dataArea  the data area.
     * @param angularTicks  the ticks for the angular axis.
     * @param radialTicks  the ticks for the radial axis.
     */
    protected void drawGridlines(Graphics2D g2, Rectangle2D dataArea,
                                 List angularTicks, List radialTicks) {

        PolarItemRenderer renderer = getRenderer();
        // no renderer, no gridlines...
        if (renderer == null) {
            return;
        }

        // draw the domain grid lines, if any...
        if (isAngleGridlinesVisible()) {
            Stroke gridStroke = getAngleGridlineStroke();
            Paint gridPaint = getAngleGridlinePaint();
            if ((gridStroke != null) && (gridPaint != null)) {
                renderer.drawAngularGridLines(g2, this, angularTicks,
                        dataArea);
            }
        }

        // draw the radius grid lines, if any...
        if (isRadiusGridlinesVisible()) {
            Stroke gridStroke = getRadiusGridlineStroke();
            Paint gridPaint = getRadiusGridlinePaint();
            if ((gridStroke != null) && (gridPaint != null)) {
                List ticks = buildRadialTicks(radialTicks);
                renderer.drawRadialGridLines(g2, this, getAxis(),
                        ticks, dataArea);
            }
        }
    }

    /**
     * Create a list of ticks based on the given list and plot properties.
     * Only ticks of a specific type may be in the result list.
     *
     * @param allTicks A list of all available ticks for the primary axis.
     *        <code>null</code> not permitted.
     * @return Ticks to use for radial gridlines.
     * @since 1.0.15
     */
    protected List buildRadialTicks(List allTicks)
    {
        List ticks = new ArrayList();
        Iterator it = allTicks.iterator();
        while (it.hasNext()) {
            ValueTick tick = (ValueTick) it.next();
            if (isRadiusMinorGridlinesVisible() ||
                    TickType.MAJOR.equals(tick.getTickType())) {
                ticks.add(tick);
            }
        }
        return ticks;
    }

    /**
     * Zooms the axis ranges by the specified percentage about the anchor point.
     *
     * @param percent  the amount of the zoom.
     */
    @Override
    public void zoom(double percent) {
        for (int axisIdx = 0; axisIdx < getAxisCount(); axisIdx++) {
            final ValueAxis axis = getAxis(axisIdx);
            if (axis != null) {
                if (percent > 0.0) {
                    double radius = axis.getUpperBound();
                    double scaledRadius = radius * percent;
                    axis.setUpperBound(scaledRadius);
                    axis.setAutoRange(false);
                }
                else {
                    axis.setAutoRange(true);
                }
            }
        }
    }

    /**
     * A utility method that returns a list of datasets that are mapped to a
     * particular axis.
     *
     * @param axisIndex  the axis index (<code>null</code> not permitted).
     *
     * @return A list of datasets.
     *
     * @since 1.0.14
     */
    private List getDatasetsMappedToAxis(Integer axisIndex) {
        ParamChecks.nullNotPermitted(axisIndex, "axisIndex");
        List result = new ArrayList();
        for (int i = 0; i < this.datasets.size(); i++) {
            List mappedAxes = (List) this.datasetToAxesMap.get(new Integer(i));
            if (mappedAxes == null) {
                if (axisIndex.equals(ZERO)) {
                    result.add(this.datasets.get(i));
                }
            }
            else {
                if (mappedAxes.contains(axisIndex)) {
                    result.add(this.datasets.get(i));
                }
            }
        }
        return result;
    }

    /**
     * Returns the range for the specified axis.
     *
     * @param axis  the axis.
     *
     * @return The range.
     */
    @Override
    public Range getDataRange(ValueAxis axis) {
        Range result = null;
        int axisIdx = getAxisIndex(axis);
        List mappedDatasets = new ArrayList();

        if (axisIdx >= 0) {
            mappedDatasets = getDatasetsMappedToAxis(new Integer(axisIdx));
        }

        // iterate through the datasets that map to the axis and get the union
        // of the ranges.
        Iterator iterator = mappedDatasets.iterator();
        int datasetIdx = -1;
        while (iterator.hasNext()) {
            datasetIdx++;
            XYDataset d = (XYDataset) iterator.next();
            if (d != null) {
                // FIXME better ask the renderer instead of DatasetUtilities
                result = Range.combine(result,
                        DatasetUtilities.findRangeBounds(d));
            }
        }

        return result;
    }

    /**
     * Receives notification of a change to the plot's m_Dataset.
     * <P>
     * The axis ranges are updated if necessary.
     *
     * @param event  information about the event (not used here).
     */
    @Override
    public void datasetChanged(DatasetChangeEvent event) {
        for (int i = 0; i < this.axes.size(); i++) {
            final ValueAxis axis = (ValueAxis) this.axes.get(i);
            if (axis != null) {
                axis.configure();
            }
        }
        if (getParent() != null) {
            getParent().datasetChanged(event);
        }
        else {
            super.datasetChanged(event);
        }
    }

    /**
     * Notifies all registered listeners of a property change.
     * <P>
     * One source of property change events is the plot's m_Renderer.
     *
     * @param event  information about the property change.
     */
    @Override
    public void rendererChanged(RendererChangeEvent event) {
        fireChangeEvent();
    }

    /**
     * Returns the legend items for the plot.  Each legend item is generated by
     * the plot's m_Renderer, since the m_Renderer is responsible for the visual
     * representation of the data.
     *
     * @return The legend items.
     */
    @Override
    public LegendItemCollection getLegendItems() {
        if (this.fixedLegendItems != null) {
            return this.fixedLegendItems;
        }
        LegendItemCollection result = new LegendItemCollection();
        int count = this.datasets.size();
        for (int datasetIndex = 0; datasetIndex < count; datasetIndex++) {
            XYDataset dataset = getDataset(datasetIndex);
            PolarItemRenderer renderer = getRenderer(datasetIndex);
            if (dataset != null && renderer != null) {
                int seriesCount = dataset.getSeriesCount();
                for (int i = 0; i < seriesCount; i++) {
                    LegendItem item = renderer.getLegendItem(i);
                    result.add(item);
                }
            }
        }
        return result;
    }

    /**
     * Tests this plot for equality with another object.
     *
     * @param obj  the object (<code>null</code> permitted).
     *
     * @return <code>true</code> or <code>false</code>.
     */
    @Override
    public boolean equals(Object obj) {
        if (obj == this) {
            return true;
        }
        if (!(obj instanceof PolarPlot)) {
            return false;
        }
        PolarPlot that = (PolarPlot) obj;
        return axesAndLocationsEqual(that)
            && renderersAndTickUnitEqual(that)
            && angleSettingsEqual(that)
            && gridlinesEqual(that)
            && radiusSettingsEqual(that)
            && cornerAndLegendItemsEqual(that)
            && super.equals(obj);
    }

    /**
     * Compares the axes and their locations.
     *
     * @param that  the other plot.
     *
     * @return <code>true</code> if the axes and locations are equal.
     */
    private boolean axesAndLocationsEqual(PolarPlot that) {
        return this.axes.equals(that.axes)
            && this.axisLocations.equals(that.axisLocations);
    }

    /**
     * Compares the renderers and the angle tick unit.
     *
     * @param that  the other plot.
     *
     * @return <code>true</code> if the renderers and tick unit are equal.
     */
    private boolean renderersAndTickUnitEqual(PolarPlot that) {
        return this.renderers.equals(that.renderers)
            && this.angleTickUnit.equals(that.angleTickUnit);
    }

    /**
     * Compares the angle-related settings.
     *
     * @param that  the other plot.
     *
     * @return <code>true</code> if the angle settings are equal.
     */
    private boolean angleSettingsEqual(PolarPlot that) {
        return this.angleGridlinesVisible == that.angleGridlinesVisible
            && this.angleOffset == that.angleOffset
            && this.counterClockwise == that.counterClockwise
            && this.angleLabelsVisible == that.angleLabelsVisible
            && this.angleLabelFont.equals(that.angleLabelFont)
            && PaintUtilities.equal(this.angleLabelPaint, that.angleLabelPaint);
    }

    /**
     * Compares the angular gridline appearance.
     *
     * @param that  the other plot.
     *
     * @return <code>true</code> if the angular gridlines are equal.
     */
    private boolean gridlinesEqual(PolarPlot that) {
        return ObjectUtilities.equal(this.angleGridlineStroke,
                that.angleGridlineStroke)
            && PaintUtilities.equal(this.angleGridlinePaint,
                    that.angleGridlinePaint);
    }

    /**
     * Compares the radius gridline settings.
     *
     * @param that  the other plot.
     *
     * @return <code>true</code> if the radius settings are equal.
     */
    private boolean radiusSettingsEqual(PolarPlot that) {
        return this.radiusGridlinesVisible == that.radiusGridlinesVisible
            && ObjectUtilities.equal(this.radiusGridlineStroke,
                    that.radiusGridlineStroke)
            && PaintUtilities.equal(this.radiusGridlinePaint,
                    that.radiusGridlinePaint)
            && this.radiusMinorGridlinesVisible
                    == that.radiusMinorGridlinesVisible;
    }

    /**
     * Compares the corner text items, margin and fixed legend items.
     *
     * @param that  the other plot.
     *
     * @return <code>true</code> if the corner and legend items are equal.
     */
    private boolean cornerAndLegendItemsEqual(PolarPlot that) {
        return this.cornerTextItems.equals(that.cornerTextItems)
            && this.margin == that.margin
            && ObjectUtilities.equal(this.fixedLegendItems,
                    that.fixedLegendItems);
    }

    /**
     * Returns a clone of the plot.
     *
     * @return A clone.
     *
     * @throws CloneNotSupportedException  this can occur if some component of
     *         the plot cannot be cloned.
     */
    @Override
    public Object clone() throws CloneNotSupportedException {
        PolarPlot copy = (PolarPlot) super.clone();
        copy.axes = cloneObjectList(this.axes);
        copyAxesTo(copy);
        copy.datasets = cloneObjectList(this.datasets);
        registerDatasetListeners(copy);
        copy.renderers = cloneObjectList(this.renderers);
        copyRenderersTo(copy);
        copy.cornerTextItems = new ArrayList(this.cornerTextItems);
        return copy;
    }

    /**
     * Clones an {@link ObjectList}.
     *
     * @param list  the list to clone.
     *
     * @return A cloned list.
     *
     * @throws CloneNotSupportedException if cloning is not supported.
     */
    private static ObjectList cloneObjectList(ObjectList list)
            throws CloneNotSupportedException {
        return (ObjectList) ObjectUtilities.clone(list);
    }

    /**
     * Clones the axes and attaches them to the supplied copy.
     *
     * @param copy  the plot copy.
     *
     * @throws CloneNotSupportedException if an axis cannot be cloned.
     */
    private void copyAxesTo(PolarPlot copy) throws CloneNotSupportedException {
        for (int i = 0; i < this.axes.size(); i++) {
            ValueAxis axis = (ValueAxis) this.axes.get(i);
            if (axis != null) {
                ValueAxis clonedAxis = (ValueAxis) axis.clone();
                copy.axes.set(i, clonedAxis);
                clonedAxis.setPlot(copy);
                clonedAxis.addChangeListener(copy);
            }
        }
    }

    /**
     * Registers the copied plot as a change listener for all shared datasets.
     *
     * @param copy  the plot copy.
     */
    private void registerDatasetListeners(PolarPlot copy) {
        for (int i = 0; i < this.datasets.size(); i++) {
            XYDataset dataset = getDataset(i);
            if (dataset != null) {
                dataset.addChangeListener(copy);
            }
        }
    }

    /**
     * Clones the renderers and attaches them to the supplied copy.
     *
     * @param copy  the plot copy.
     *
     * @throws CloneNotSupportedException if a renderer cannot be cloned.
     */
    private void copyRenderersTo(PolarPlot copy)
            throws CloneNotSupportedException {
