    /**
     * Normalizes the angle according to the current offset and direction.
     *
     * @param angleDegrees  the angle in degrees.
     *
     * @return The normalized angle in the range 0 to 360 degrees.
     */
    private double normalizeAngle(double angleDegrees) {
        double offset = this.angleOffset;
        while (offset < 0.0) {
            offset += 360.0;
        }
        double normalizedAngle = (((this.counterClockwise ? -1 : 1)
                * angleDegrees) + offset) % 360;
        while (this.counterClockwise && (normalizedAngle < 0.0)) {
            normalizedAngle += 360.0;
        }
        return normalizedAngle;
    }

    /**
     * Returns the text anchor for the specified normalized angle.
     *
     * @param normalizedAngle  the normalized angle in degrees.
     *
     * @return The text anchor.
     */
    private TextAnchor lookupTextAnchor(double normalizedAngle) {
        if (normalizedAngle == 0.0) {
            return TextAnchor.CENTER_LEFT;
        }
        if (normalizedAngle > 0.0 && normalizedAngle < 90.0) {
            return TextAnchor.TOP_LEFT;
        }
        if (normalizedAngle == 90.0) {
            return TextAnchor.TOP_CENTER;
        }
        if (normalizedAngle > 90.0 && normalizedAngle < 180.0) {
            return TextAnchor.TOP_RIGHT;
        }
        if (normalizedAngle == 180.0) {
            return TextAnchor.CENTER_RIGHT;
        }
        if (normalizedAngle > 180.0 && normalizedAngle < 270.0) {
            return TextAnchor.BOTTOM_RIGHT;
        }
        if (normalizedAngle == 270.0) {
            return TextAnchor.BOTTOM_CENTER;
        }
        if (normalizedAngle > 270.0 && normalizedAngle < 360.0) {
            return TextAnchor.BOTTOM_LEFT;
        }
        return TextAnchor.CENTER;
    }
