/**
 * Creates an independent copy of this plot.
 *
 * @return A clone.
 *
 * @throws CloneNotSupportedException if some component of the plot cannot
 *         be cloned.
 */
@Override
public Object clone() throws CloneNotSupportedException {
    return copyInstance(this);
}

/**
 * Creates a copy of the given plot.
 *
 * @param source  the source plot (<code>null</code> not permitted).
 *
 * @return A copy.
 *
 * @throws CloneNotSupportedException if some component of the plot cannot
 *         be cloned.
 */
public static PolarPlot copyInstance(PolarPlot source)
        throws CloneNotSupportedException {
    ParamChecks.nullNotPermitted(source, "source");
    PolarPlot copy = source.createShallowCopy();
    copy.copyAxesFrom(source);
    copy.copyDatasetsFrom(source);
    copy.copyRenderersFrom(source);
    copy.cornerTextItems = new ArrayList(source.cornerTextItems);
    return copy;
}

/**
 * Creates a shallow copy of this plot, including superclass state.
 *
 * @return A shallow copy.
 *
 * @throws CloneNotSupportedException if the superclass cannot be cloned.
 */
private PolarPlot createShallowCopy() throws CloneNotSupportedException {
    return (PolarPlot) super.clone();
}

/**
 * Copies the axes from the source plot into this plot, cloning each axis
 * and registering this plot as a listener.
 *
 * @param source  the source plot.
 *
 * @throws CloneNotSupportedException if an axis cannot be cloned.
 */
private void copyAxesFrom(PolarPlot source)
        throws CloneNotSupportedException {
    this.axes = (ObjectList) ObjectUtilities.clone(source.axes);
    for (int i = 0; i < source.axes.size(); i++) {
        ValueAxis axis = (ValueAxis) source.axes.get(i);
        if (axis != null) {
            ValueAxis clonedAxis = (ValueAxis) axis.clone();
            this.axes.set(i, clonedAxis);
            clonedAxis.setPlot(this);
            clonedAxis.addChangeListener(this);
        }
    }
}

/**
 * Copies the dataset list from the source plot into this plot and registers
 * this plot as a listener for each dataset.
 *
 * @param source  the source plot.
 *
 * @throws CloneNotSupportedException if the dataset list cannot be cloned.
 */
private void copyDatasetsFrom(PolarPlot source)
        throws CloneNotSupportedException {
    this.datasets = (ObjectList) ObjectUtilities.clone(source.datasets);
    for (int i = 0; i < this.datasets.size(); i++) {
        XYDataset d = source.getDataset(i);
        if (d != null) {
            d.addChangeListener(this);
        }
    }
}

/**
 * Copies the renderers from the source plot into this plot, cloning each
 * renderer that implements {@link PublicCloneable} and registering this
 * plot as a listener.
 *
 * @param source  the source plot.
 *
 * @throws CloneNotSupportedException if a renderer cannot be cloned.
 */
private void copyRenderersFrom(PolarPlot source)
        throws CloneNotSupportedException {
    this.renderers = (ObjectList) ObjectUtilities.clone(source.renderers);
    for (int i = 0; i < source.renderers.size(); i++) {
        PolarItemRenderer renderer = (PolarItemRenderer) source.renderers.get(i);
        if (renderer instanceof PublicCloneable) {
            PublicCloneable pc = (PublicCloneable) renderer;
            PolarItemRenderer clonedRenderer = (PolarItemRenderer) pc.clone();
            this.renderers.set(i, clonedRenderer);
            clonedRenderer.setPlot(this);
            clonedRenderer.addChangeListener(this);
        }
    }
}
```

