/** Anchors used for the four 90-degree sectors (excluding boundaries). */
private static final TextAnchor[] SECTOR_ANCHORS = {
    TextAnchor.TOP_LEFT,      // 0 < angle < 90
    TextAnchor.TOP_RIGHT,     // 90 < angle < 180
    TextAnchor.BOTTOM_RIGHT,  // 180 < angle < 270
    TextAnchor.BOTTOM_LEFT    // 270 < angle < 360
};

/**
 * Determines the text anchor for a normalized angle.
 *
 * @param normalizedAngle  the normalized angle in degrees.
 *
 * @return The text anchor.
 */
private TextAnchor determineTextAnchor(double normalizedAngle) {
    if (normalizedAngle < 0.0 || normalizedAngle >= 360.0) {
        return TextAnchor.CENTER;
    }
    if (normalizedAngle == 0.0) {
        return TextAnchor.CENTER_LEFT;
    }
    if (normalizedAngle == 90.0) {
        return TextAnchor.TOP_CENTER;
    }
    if (normalizedAngle == 180.0) {
        return TextAnchor.CENTER_RIGHT;
    }
    if (normalizedAngle == 270.0) {
        return TextAnchor.BOTTOM_CENTER;
    }
    int sector = (int) (normalizedAngle / 90.0);
    return SECTOR_ANCHORS[sector];
}
```

