    /**
     * Applies this theme to the supplied chart.
     *
     * @param chart  the chart (<code>null</code> not permitted).
     */
    @Override
    public void apply(JFreeChart chart) {
        ParamChecks.nullNotPermitted(chart, "chart");
        applyToChartTitle(chart.getTitle());
        applyToSubtitles(chart);
        chart.setBackgroundPaint(this.chartBackgroundPaint);
        applyToChartPlot(chart.getPlot());
    }

    /**
     * Applies the theme to the main chart title.
     *
     * @param title  the title (may be <code>null</code>).
     */
    private void applyToChartTitle(TextTitle title) {
        if (title != null) {
            title.setFont(this.extraLargeFont);
            title.setPaint(this.titlePaint);
        }
    }

    /**
     * Applies the theme to all subtitles of the supplied chart.
     *
     * @param chart  the chart (<code>null</code> not permitted).
     */
    private void applyToSubtitles(JFreeChart chart) {
        int subtitleCount = chart.getSubtitleCount();
        for (int i = 0; i < subtitleCount; i++) {
            applyToTitle(chart.getSubtitle(i));
        }
    }

    /**
     * Applies the theme to the chart's plot if there is one.
     *
     * @param plot  the plot (may be <code>null</code>).
     */
    private void applyToChartPlot(Plot plot) {
        if (plot != null) {
            applyToPlot(plot);
        }
    }

    /**
     * Applies the attributes of this theme to the specified title.
     *
     * @param title  the title.
     */
    protected void applyToTitle(Title title) {
        if (title instanceof TextTitle) {
            applyToTextTitle((TextTitle) title);
        }
        else if (title instanceof LegendTitle) {
            applyToLegendTitle((LegendTitle) title);
        }
        else if (title instanceof PaintScaleLegend) {
            applyToPaintScaleLegend((PaintScaleLegend) title);
        }
        else if (title instanceof CompositeTitle) {
            applyToCompositeTitle((CompositeTitle) title);
        }
    }

    /**
     * Applies the attributes of this theme to a {@link TextTitle}.
     *
     * @param title  the title (<code>null</code> not permitted).
     */
    protected void applyToTextTitle(TextTitle title) {
        title.setFont(this.largeFont);
        title.setPaint(this.subtitlePaint);
    }

    /**
     * Applies the attributes of this theme to a {@link LegendTitle}.
     *
     * @param title  the title (<code>null</code> not permitted).
     */
    protected void applyToLegendTitle(LegendTitle title) {
        if (title.getBackgroundPaint() != null) {
            title.setBackgroundPaint(this.legendBackgroundPaint);
        }
        title.setItemFont(this.regularFont);
        title.setItemPaint(this.legendItemPaint);
        if (title.getWrapper() != null) {
            applyToBlockContainer(title.getWrapper());
        }
    }

    /**
     * Applies the attributes of this theme to a {@link PaintScaleLegend}.
     *
     * @param title  the title (<code>null</code> not permitted).
     */
    protected void applyToPaintScaleLegend(PaintScaleLegend title) {
        title.setBackgroundPaint(this.legendBackgroundPaint);
        ValueAxis axis = title.getAxis();
        if (axis != null) {
            applyToValueAxis(axis);
        }
    }

    /**
     * Applies the attributes of this theme to a {@link CompositeTitle}.
     *
     * @param title  the title (<code>null</code> not permitted).
     */
    protected void applyToCompositeTitle(CompositeTitle title) {
        BlockContainer bc = title.getContainer();
        List blocks = bc.getBlocks();
        Iterator iterator = blocks.iterator();
        while (iterator.hasNext()) {
            Block b = (Block) iterator.next();
            if (b instanceof Title) {
                applyToTitle((Title) b);
            }
        }
    }

    /**
     * Applies the attributes of this theme to the specified container.
     *
     * @param bc  a block container (<code>null</code> not permitted).
     */
    protected void applyToBlockContainer(BlockContainer bc) {
        Iterator iterator = bc.getBlocks().iterator();
        while (iterator.hasNext()) {
            Block b = (Block) iterator.next();
            applyToBlock(b);
        }
    }

    /**
     * Applies the attributes of this theme to the specified block.
     *
     * @param b  the block.
     */
    protected void applyToBlock(Block b) {
        if (b instanceof Title) {
            applyToTitle((Title) b);
        }
        else if (b instanceof LabelBlock) {
            LabelBlock lb = (LabelBlock) b;
            lb.setFont(this.regularFont);
            lb.setPaint(this.legendItemPaint);
        }
    }

    /**
     * Applies the attributes of this theme to a plot.
     *
     * @param plot  the plot (<code>null</code> not permitted).
     */
    protected void applyToPlot(Plot plot) {
        ParamChecks.nullNotPermitted(plot, "plot");
        applyCommonPlotAttributes(plot);
        applyToTypedPlot(plot);
    }

    /**
     * Applies the plot attributes that are common to all plot types.
     *
     * @param plot  the plot (<code>null</code> not permitted).
     */
    private void applyCommonPlotAttributes(Plot plot) {
        if (plot.getDrawingSupplier() != null) {
            plot.setDrawingSupplier(getDrawingSupplier());
        }
        if (plot.getBackgroundPaint() != null) {
            plot.setBackgroundPaint(this.plotBackgroundPaint);
        }
        plot.setOutlinePaint(this.plotOutlinePaint);
    }

    /**
     * Dispatches the theme application to the appropriate plot type.
     *
     * @param plot  the plot (<code>null</code> not permitted).
     */
    private void applyToTypedPlot(Plot plot) {
        if (plot instanceof PiePlot) {
            applyToPiePlot((PiePlot) plot);
        }
        else if (plot instanceof MultiplePiePlot) {
            applyToMultiplePiePlot((MultiplePiePlot) plot);
        }
        else if (plot instanceof CategoryPlot) {
            applyToCategoryPlot((CategoryPlot) plot);
        }
        else if (plot instanceof XYPlot) {
            applyToXYPlot((XYPlot) plot);
        }
        else if (plot instanceof FastScatterPlot) {
            applyToFastScatterPlot((FastScatterPlot) plot);
        }
        else if (plot instanceof MeterPlot) {
            applyToMeterPlot((MeterPlot) plot);
        }
        else if (plot instanceof ThermometerPlot) {
            applyToThermometerPlot((ThermometerPlot) plot);
        }
        else if (plot instanceof SpiderWebPlot) {
            applyToSpiderWebPlot((SpiderWebPlot) plot);
        }
        else if (plot instanceof PolarPlot) {
            applyToPolarPlot((PolarPlot) plot);
        }
    }

    /**
     * Applies the attributes of this theme to a {@link PiePlot} instance.
     * This method also clears any set values for the section paint, outline
     * etc, so that the theme's {@link DrawingSupplier} will be used.
     *
     * @param plot  the plot (<code>null</code> not permitted).
     */
    protected void applyToPiePlot(PiePlot plot) {
        plot.setLabelLinkPaint(this.labelLinkPaint);
        plot.setLabelLinkStyle(this.labelLinkStyle);
        plot.setLabelFont(this.regularFont);
        plot.setShadowGenerator(this.shadowGenerator);

        // clear the section attributes so that the theme's DrawingSupplier
        // will be used
        if (plot.getAutoPopulateSectionPaint()) {
            plot.clearSectionPaints(false);
        }
        if (plot.getAutoPopulateSectionOutlinePaint()) {
            plot.clearSectionOutlinePaints(false);
        }
        if (plot.getAutoPopulateSectionOutlineStroke()) {
            plot.clearSectionOutlineStrokes(false);
        }
    }

    /**
     * Applies the attributes of this theme to a {@link MultiplePiePlot}.
     *
     * @param plot  the plot (<code>null</code> not permitted).
     */
    protected void applyToMultiplePiePlot(MultiplePiePlot plot) {
        apply(plot.getPieChart());
    }

