            @Override
            public void apply(StandardChartTheme theme, Title title) {
                PaintScaleLegend psl = (PaintScaleLegend) title;
                psl.setBackgroundPaint(theme.legendBackgroundPaint);
                ValueAxis axis = psl.getAxis();
                if (axis != null) {
                    theme.applyToValueAxis(axis);
