     * @param axis  the axis (<code>null</code> not permitted).
     */
    protected void applyToSymbolAxis(SymbolAxis axis) {
        axis.setGridBandPaint(this.gridBandPaint);
        axis.setGridBandAlternatePaint(this.gridBandAlternatePaint);
    }

    /**
     * Applies the attributes for this theme to a {@link PeriodAxis}.
     *
     * @param axis  the axis (<code>null</code> not permitted).
     */
    protected void applyToPeriodAxis(PeriodAxis axis) {
        PeriodAxisLabelInfo[] info = axis.getLabelInfo();
        for (int i = 0; i < info.length; i++) {
            PeriodAxisLabelInfo e = info[i];
            PeriodAxisLabelInfo n = new PeriodAxisLabelInfo(e.getPeriodClass(),
                    e.getDateFormat(), e.getPadding(), this.regularFont,
                    this.tickLabelPaint, e.getDrawDividers(),
                    e.getDividerStroke(), e.getDividerPaint());
            info[i] = n;
        }
        axis.setLabelInfo(info);
    }

    /**
     * Applies the attributes for this theme to an {@link AbstractRenderer}.
     *
     * @param renderer  the renderer (<code>null</code> not permitted).
     */
    protected void applyToAbstractRenderer(AbstractRenderer renderer) {
        if (renderer.getAutoPopulateSeriesPaint()) {
            renderer.clearSeriesPaints(false);
        }
        if (renderer.getAutoPopulateSeriesStroke()) {
            renderer.clearSeriesStrokes(false);
        }
    }

    /**
     * Applies the settings of this theme to the specified renderer.
     *
     * @param renderer  the renderer (<code>null</code> not permitted).
     */
    protected void applyToCategoryItemRenderer(CategoryItemRenderer renderer) {
        ParamChecks.nullNotPermitted(renderer, "renderer");

        renderer.setBaseItemLabelFont(this.regularFont);
        renderer.setBaseItemLabelPaint(this.itemLabelPaint);

        for (int i = 0; i < CATEGORY_RENDERER_APPLIERS.length; i++) {
            CategoryItemRendererApplier applier = CATEGORY_RENDERER_APPLIERS[i];
            if (applier.appliesTo(renderer)) {
                applier.apply(this, renderer);
            }
        }
    }

    /**
     * Applies the settings of this theme to the specified renderer.
     *
     * @param renderer  the renderer (<code>null</code> not permitted).
     */
    protected void applyToXYItemRenderer(XYItemRenderer renderer) {
        ParamChecks.nullNotPermitted(renderer, "renderer");
        renderer.setBaseItemLabelFont(this.regularFont);
        renderer.setBaseItemLabelPaint(this.itemLabelPaint);
        for (int i = 0; i < XY_RENDERER_APPLIERS.length; i++) {
            XYItemRendererApplier applier = XY_RENDERER_APPLIERS[i];
            if (applier.appliesTo(renderer)) {
                applier.apply(this, renderer);
            }
        }
    }

    /**
     * Applies the settings of this theme to the specified annotation.
     *
     * @param annotation  the annotation.
     */
    protected void applyToXYAnnotation(XYAnnotation annotation) {
        ParamChecks.nullNotPermitted(annotation, "annotation");
        if (annotation instanceof XYTextAnnotation) {
            XYTextAnnotation xyta = (XYTextAnnotation) annotation;
            xyta.setFont(this.smallFont);
            xyta.setPaint(this.itemLabelPaint);
        }
    }

    /**
     * Tests this theme for equality with an arbitrary object.
     *
     * @param obj  the object (<code>null</code> permitted).
     *
     * @return A boolean.
     */
    @Override
    public boolean equals(Object obj) {
        if (obj == this) {
            return true;
        }
        if (!(obj instanceof StandardChartTheme)) {
            return false;
        }
        StandardChartTheme that = (StandardChartTheme) obj;
        return equalNameAndFonts(that)
            && equalTitleAndChartPaints(that)
            && this.drawingSupplier.equals(that.drawingSupplier)
            && equalPlotAttributes(that)
            && equalGridAndCrosshairPaints(that)
            && equalAxisAndItemLabelPaints(that)
            && equalShadowAndBarPaints(that)
            && equalWallAndGridBandPaints(that);
    }

    /**
     * Returns <code>true</code> if the name and font fields are equal to those
     * of the supplied theme.
     *
     * @param that  the other theme.
     *
     * @return A boolean.
     */
    private boolean equalNameAndFonts(StandardChartTheme that) {
        return this.name.equals(that.name)
            && this.extraLargeFont.equals(that.extraLargeFont)
            && this.largeFont.equals(that.largeFont)
            && this.regularFont.equals(that.regularFont)
            && this.smallFont.equals(that.smallFont);
    }

    /**
     * Returns <code>true</code> if the title and chart paint fields are equal
     * to those of the supplied theme.
     *
     * @param that  the other theme.
     *
     * @return A boolean.
     */
    private boolean equalTitleAndChartPaints(StandardChartTheme that) {
        return PaintUtilities.equal(this.titlePaint, that.titlePaint)
            && PaintUtilities.equal(this.subtitlePaint, that.subtitlePaint)
            && PaintUtilities.equal(this.chartBackgroundPaint,
                    that.chartBackgroundPaint)
            && PaintUtilities.equal(this.legendBackgroundPaint,
                    that.legendBackgroundPaint)
            && PaintUtilities.equal(this.legendItemPaint, that.legendItemPaint);
    }

    /**
     * Returns <code>true</code> if the plot attribute fields are equal to
     * those of the supplied theme.
     *
     * @param that  the other theme.
     *
     * @return A boolean.
     */
    private boolean equalPlotAttributes(StandardChartTheme that) {
        return PaintUtilities.equal(this.plotBackgroundPaint,
                    that.plotBackgroundPaint)
            && PaintUtilities.equal(this.plotOutlinePaint,
                    that.plotOutlinePaint)
            && this.labelLinkStyle.equals(that.labelLinkStyle)
            && PaintUtilities.equal(this.labelLinkPaint, that.labelLinkPaint);
    }

    /**
     * Returns <code>true</code> if the grid and crosshair paint fields are
     * equal to those of the supplied theme.
     *
     * @param that  the other theme.
     *
     * @return A boolean.
     */
    private boolean equalGridAndCrosshairPaints(StandardChartTheme that) {
        return PaintUtilities.equal(this.domainGridlinePaint,
                    that.domainGridlinePaint)
            && PaintUtilities.equal(this.rangeGridlinePaint,
                    that.rangeGridlinePaint)
            && PaintUtilities.equal(this.crosshairPaint, that.crosshairPaint)
            && this.axisOffset.equals(that.axisOffset);
    }

    /**
     * Returns <code>true</code> if the axis and item label paint fields are
     * equal to those of the supplied theme.
     *
     * @param that  the other theme.
     *
     * @return A boolean.
     */
    private boolean equalAxisAndItemLabelPaints(StandardChartTheme that) {
        return PaintUtilities.equal(this.axisLabelPaint, that.axisLabelPaint)
            && PaintUtilities.equal(this.tickLabelPaint, that.tickLabelPaint)
            && PaintUtilities.equal(this.itemLabelPaint, that.itemLabelPaint)
            && this.shadowVisible == that.shadowVisible;
    }

    /**
     * Returns <code>true</code> if the shadow and bar painter fields are equal
     * to those of the supplied theme.
     *
     * @param that  the other theme.
     *
     * @return A boolean.
     */
    private boolean equalShadowAndBarPaints(StandardChartTheme that) {
        return PaintUtilities.equal(this.shadowPaint, that.shadowPaint)
            && this.barPainter.equals(that.barPainter)
            && this.xyBarPainter.equals(that.xyBarPainter)
            && PaintUtilities.equal(this.thermometerPaint,
                    that.thermometerPaint);
    }

    /**
     * Returns <code>true</code> if the wall and grid band paint fields are
     * equal to those of the supplied theme.
     *
     * @param that  the other theme.
     *
     * @return A boolean.
     */
    private boolean equalWallAndGridBandPaints(StandardChartTheme that) {
        return PaintUtilities.equal(this.wallPaint, that.wallPaint)
            && PaintUtilities.equal(this.errorIndicatorPaint,
                    that.errorIndicatorPaint)
            && PaintUtilities.equal(this.gridBandPaint, that.gridBandPaint)
            && PaintUtilities.equal(this.gridBandAlternatePaint,
                    that.gridBandAlternatePaint);
    }

    /**
     * Returns a clone of this theme.
     *
     * @return A clone.
     *
     * @throws CloneNotSupportedException if the theme cannot be cloned.
     */
    @Override
    public Object clone() throws CloneNotSupportedException {
        return new StandardChartTheme(this);
    }

    /**
     * Provides serialization support.
     *
     * @param stream  the output stream (<code>null</code> not permitted).
     *
     * @throws IOException  if there is an I/O error.
     */
    private void writeObject(ObjectOutputStream stream) throws IOException {
        stream.defaultWriteObject();
        SerialUtilities.writePaint(this.titlePaint, stream);
        SerialUtilities.writePaint(this.subtitlePaint, stream);
        SerialUtilities.writePaint(this.chartBackgroundPaint, stream);
        SerialUtilities.writePaint(this.legendBackgroundPaint, stream);
        SerialUtilities.writePaint(this.legendItemPaint, stream);
        SerialUtilities.writePaint(this.plotBackgroundPaint, stream);
        SerialUtilities.writePaint(this.plotOutlinePaint, stream);
        SerialUtilities.writePaint(this.labelLinkPaint, stream);
        SerialUtilities.writePaint(this.baselinePaint, stream);
        SerialUtilities.writePaint(this.domainGridlinePaint, stream);
        SerialUtilities.writePaint(this.rangeGridlinePaint, stream);
        SerialUtilities.writePaint(this.crosshairPaint, stream);
        SerialUtilities.writePaint(this.axisLabelPaint, stream);
        SerialUtilities.writePaint(this.tickLabelPaint, stream);
        SerialUtilities.writePaint(this.itemLabelPaint, stream);
        SerialUtilities.writePaint(this.shadowPaint, stream);
        SerialUtilities.writePaint(this.thermometerPaint, stream);
        SerialUtilities.writePaint(this.wallPaint, stream);
        SerialUtilities.writePaint(this.errorIndicatorPaint, stream);
        SerialUtilities.writePaint(this.gridBandPaint, stream);
        SerialUtilities.writePaint(this.gridBandAlternatePaint, stream);
    }

    /**
     * Provides serialization support.
     *
     * @param stream  the input stream (<code>null</code> not permitted).
     *
     * @throws IOException  if there is an I/O error.
     * @throws ClassNotFoundException  if there is a classpath problem.
     */
    private void readObject(ObjectInputStream stream)
        throws IOException, ClassNotFoundException {
        stream.defaultReadObject();
        this.titlePaint = SerialUtilities.readPaint(stream);
        this.subtitlePaint = SerialUtilities.readPaint(stream);
        this.chartBackgroundPaint = SerialUtilities.readPaint(stream);
        this.legendBackgroundPaint = SerialUtilities.readPaint(stream);
        this.legendItemPaint = SerialUtilities.readPaint(stream);
        this.plotBackgroundPaint = SerialUtilities.readPaint(stream);
        this.plotOutlinePaint = SerialUtilities.readPaint(stream);
        this.labelLinkPaint = SerialUtilities.readPaint(stream);
        this.baselinePaint = SerialUtilities.readPaint(stream);
        this.domainGridlinePaint = SerialUtilities.readPaint(stream);
        this.rangeGridlinePaint = SerialUtilities.readPaint(stream);
        this.crosshairPaint = SerialUtilities.readPaint(stream);
        this.axisLabelPaint = SerialUtilities.readPaint(stream);
        this.tickLabelPaint = SerialUtilities.readPaint(stream);
        this.itemLabelPaint = SerialUtilities.readPaint(stream);
        this.shadowPaint = SerialUtilities.readPaint(stream);
        this.thermometerPaint = SerialUtilities.readPaint(stream);
        this.wallPaint = SerialUtilities.readPaint(stream);
        this.errorIndicatorPaint = SerialUtilities.readPaint(stream);
        this.gridBandPaint = SerialUtilities.readPaint(stream);
        this.gridBandAlternatePaint = SerialUtilities.readPaint(stream);
    }

}

