/**
 * A default implementation of the {@link ChartTheme} interface.  This
 * implementation just collects a whole bunch of chart attributes and mimics
 * the manual process of applying each attribute to the right sub-object
 * within the JFreeChart instance.  It's not elegant code, but it works.
 *
 * @since 1.0.11
 */
public class StandardChartTheme implements ChartTheme, Cloneable,
        PublicCloneable, Serializable {

    /** The name of this theme. */
    private String name;

    /**
     * The largest font size.  Use for the main chart title.
     */
    private Font extraLargeFont;

    /**
     * A large font.  Used for subtitles.
     */
    private Font largeFont;

    /**
     * The regular font size.  Used for axis tick labels, legend items etc.
     */
    private Font regularFont;

    /**
     * The small font size.
     */
    private Font smallFont;

    /** The paint used to display the main chart title. */
    private transient Paint titlePaint;

    /** The paint used to display subtitles. */
    private transient Paint subtitlePaint;

    /** The background paint for the chart. */
    private transient Paint chartBackgroundPaint;

    /** The legend background paint. */
    private transient Paint legendBackgroundPaint;

    /** The legend item paint. */
    private transient Paint legendItemPaint;

    /** The drawing supplier. */
    private DrawingSupplier drawingSupplier;

    /** The background paint for the plot. */
    private transient Paint plotBackgroundPaint;

    /** The plot outline paint. */
    private transient Paint plotOutlinePaint;

    /** The label link style for pie charts. */
    private PieLabelLinkStyle labelLinkStyle;

    /** The label link paint for pie charts. */
    private transient Paint labelLinkPaint;

    /** The domain grid line paint. */
    private transient Paint domainGridlinePaint;

    /** The range grid line paint. */
    private transient Paint rangeGridlinePaint;

    /**
     * The baseline paint (used for domain and range zero baselines)
     *
     * @since 1.0.13
     */
    private transient Paint baselinePaint;

    /** The crosshair paint. */
    private transient Paint crosshairPaint;

    /** The axis offsets. */
    private RectangleInsets axisOffset;

    /** The axis label paint. */
    private transient Paint axisLabelPaint;

    /** The tick label paint. */
    private transient Paint tickLabelPaint;

    /** The item label paint. */
    private transient Paint itemLabelPaint;

    /**
     * A flag that controls whether or not shadows are visible (for example,
     * in a bar renderer).
     */
    private boolean shadowVisible;

    /** The shadow paint. */
    private transient Paint shadowPaint;

    /** The bar painter. */
    private BarPainter barPainter;

    /** The XY bar painter. */
    private XYBarPainter xyBarPainter;

    /** The thermometer paint. */
    private transient Paint thermometerPaint;

    /**
     * The paint used to fill the interior of the 'walls' in the background
     * of a plot with a 3D effect.  Applied to BarRenderer3D.
     */
    private transient Paint wallPaint;

    /** The error indicator paint for the {@link StatisticalBarRenderer}. */
    private transient Paint errorIndicatorPaint;

    /** The grid band paint for a {@link SymbolAxis}. */
    private transient Paint gridBandPaint = SymbolAxis.DEFAULT_GRID_BAND_PAINT;

    /** The grid band alternate paint for a {@link SymbolAxis}. */
    private transient Paint gridBandAlternatePaint
            = SymbolAxis.DEFAULT_GRID_BAND_ALTERNATE_PAINT;

    /**
     * The shadow generator (can be null).
     * 
     * @since 1.0.14
     */
    private ShadowGenerator shadowGenerator;

    /**
     * Applies theme attributes to a specific {@link Plot} subclass.
     */
    private interface PlotApplier {
        /**
         * Applies this theme to the supplied plot.
         *
         * @param theme  the theme.
         * @param plot  the plot.
         */
        void apply(StandardChartTheme theme, Plot plot);
    }

    /**
     * Pairs a plot type with the applier that handles it.
     */
    private static final class PlotTypeHandler {
        /** The plot type. */
        private final Class<? extends Plot> type;

        /** The applier for the plot type. */
        private final PlotApplier applier;

        /**
         * Creates a new handler.
         *
         * @param type  the plot type.
         * @param applier  the applier.
         */
        PlotTypeHandler(Class<? extends Plot> type, PlotApplier applier) {
            this.type = type;
            this.applier = applier;
        }

        /**
         * Returns {@code true} if the handler applies to the supplied plot.
         *
         * @param plot  the plot.
         *
         * @return A boolean.
         */
        boolean matches(Plot plot) {
            return this.type.isInstance(plot);
        }

        /**
         * Applies the theme to the supplied plot.
         *
         * @param theme  the theme.
         * @param plot  the plot.
         */
        void apply(StandardChartTheme theme, Plot plot) {
            this.applier.apply(theme, plot);
        }
    }

    /** A list of plot type handlers, in the order they are checked. */
    private static final List<PlotTypeHandler> PLOT_TYPE_HANDLERS;
    static {
        List<PlotTypeHandler> handlers = new ArrayList<PlotTypeHandler>();
        handlers.add(new PlotTypeHandler(PiePlot.class, new PlotApplier() {
            @Override
            public void apply(StandardChartTheme theme, Plot plot) {
                theme.applyToPiePlot((PiePlot) plot);
            }
        }));
        handlers.add(new PlotTypeHandler(MultiplePiePlot.class, new PlotApplier() {
            @Override
            public void apply(StandardChartTheme theme, Plot plot) {
                theme.applyToMultiplePiePlot((MultiplePiePlot) plot);
            }
        }));
        handlers.add(new PlotTypeHandler(CategoryPlot.class, new PlotApplier() {
            @Override
            public void apply(StandardChartTheme theme, Plot plot) {
                theme.applyToCategoryPlot((CategoryPlot) plot);
            }
        }));
        handlers.add(new PlotTypeHandler(XYPlot.class, new PlotApplier() {
            @Override
            public void apply(StandardChartTheme theme, Plot plot) {
                theme.applyToXYPlot((XYPlot) plot);
            }
        }));
        handlers.add(new PlotTypeHandler(FastScatterPlot.class, new PlotApplier() {
            @Override
            public void apply(StandardChartTheme theme, Plot plot) {
                theme.applyToFastScatterPlot((FastScatterPlot) plot);
            }
        }));
        handlers.add(new PlotTypeHandler(MeterPlot.class, new PlotApplier() {
            @Override
            public void apply(StandardChartTheme theme, Plot plot) {
                theme.applyToMeterPlot((MeterPlot) plot);
            }
        }));
        handlers.add(new PlotTypeHandler(ThermometerPlot.class, new PlotApplier() {
            @Override
            public void apply(StandardChartTheme theme, Plot plot) {
                theme.applyToThermometerPlot((ThermometerPlot) plot);
            }
        }));
        handlers.add(new PlotTypeHandler(SpiderWebPlot.class, new PlotApplier() {
            @Override
            public void apply(StandardChartTheme theme, Plot plot) {
                theme.applyToSpiderWebPlot((SpiderWebPlot) plot);
            }
        }));
        handlers.add(new PlotTypeHandler(PolarPlot.class, new PlotApplier() {
            @Override
            public void apply(StandardChartTheme theme, Plot plot) {
                theme.applyToPolarPlot((PolarPlot) plot);
            }
        }));
        PLOT_TYPE_HANDLERS = Collections.unmodifiableList(handlers);
    }

    /**
     * Applies theme attributes to a specific {@link Title} subclass.
     */
    private interface TitleApplier {
        /**
         * Applies this theme to the supplied title.
         *
         * @param theme  the theme.
         * @param title  the title.
         */
        void apply(StandardChartTheme theme, Title title);
    }

    /**
     * Pairs a title type with the applier that handles it.
     */
    private static final class TitleTypeHandler {
        /** The title type. */
        private final Class<? extends Title> type;

        /** The applier for the title type. */
        private final TitleApplier applier;

        /**
         * Creates a new handler.
         *
         * @param type  the title type.
         * @param applier  the applier.
         */
        TitleTypeHandler(Class<? extends Title> type, TitleApplier applier) {
            this.type = type;
            this.applier = applier;
        }

        /**
         * Returns {@code true} if the handler applies to the supplied title.
         *
         * @param title  the title.
         *
         * @return A boolean.
         */
        boolean matches(Title title) {
            return this.type.isInstance(title);
        }

        /**
         * Applies the theme to the supplied title.
         *
         * @param theme  the theme.
         * @param title  the title.
         */
        void apply(StandardChartTheme theme, Title title) {
            this.applier.apply(theme, title);
        }
    }

    /** A list of title type handlers, in the order they are checked. */
    private static final List<TitleTypeHandler> TITLE_TYPE_HANDLERS;
    static {
        List<TitleTypeHandler> handlers = new ArrayList<TitleTypeHandler>();
        handlers.add(new TitleTypeHandler(TextTitle.class, new TitleApplier() {
            @Override
            public void apply(StandardChartTheme theme, Title title) {
                TextTitle tt = (TextTitle) title;
                tt.setFont(theme.largeFont);
                tt.setPaint(theme.subtitlePaint);
            }
        }));
        handlers.add(new TitleTypeHandler(LegendTitle.class, new TitleApplier() {
            @Override
            public void apply(StandardChartTheme theme, Title title) {
                LegendTitle lt = (LegendTitle) title;
                if (lt.getBackgroundPaint() != null) {
                    lt.setBackgroundPaint(theme.legendBackgroundPaint);
                }
                lt.setItemFont(theme.regularFont);
                lt.setItemPaint(theme.legendItemPaint);
                if (lt.getWrapper() != null) {
                    theme.applyToBlockContainer(lt.getWrapper());
                }
            }
        }));
        handlers.add(new TitleTypeHandler(PaintScaleLegend.class, new TitleApplier() {
            @Override
            public void apply(StandardChartTheme theme, Title title) {
                PaintScaleLegend psl = (PaintScaleLegend) title;
                psl.setBackgroundPaint(theme.legendBackgroundPaint);
                ValueAxis axis = psl.getAxis();
                if (axis != null) {
                    theme.applyToValueAxis(axis);
                }
            }
        }));
        handlers.add(new TitleTypeHandler(CompositeTitle.class, new TitleApplier() {
            @Override
            public void apply(StandardChartTheme theme, Title title) {
                CompositeTitle ct = (CompositeTitle) title;
                BlockContainer bc = ct.getContainer();
                List blocks = bc.getBlocks();
                Iterator iterator = blocks.iterator();
                while (iterator.hasNext()) {
                    Block b = (Block) iterator.next();
                    if (b instanceof Title) {
                        theme.applyToTitle((Title) b);
                    }
                }
            }
        }));
        TITLE_TYPE_HANDLERS = Collections.unmodifiableList(handlers);
    }

    /**
     * Applies theme attributes to a specific {@link CategoryItemRenderer}
     * subclass.
     */
    private interface CategoryRendererApplier {
        /**
         * Applies this theme to the supplied renderer.
         *
         * @param theme  the theme.
         * @param renderer  the renderer.
         */
        void apply(StandardChartTheme theme, CategoryItemRenderer renderer);
    }

    /**
     * Pairs a renderer type with the applier that handles it.
     */
    private static final class CategoryRendererTypeHandler {
        /** The renderer type. */
        private final Class<?> type;

        /** The applier for the renderer type. */
        private final CategoryRendererApplier applier;

        /**
         * Creates a new handler.
         *
         * @param type  the renderer type.
         * @param applier  the applier.
         */
        CategoryRendererTypeHandler(Class<?> type,
                CategoryRendererApplier applier) {
            this.type = type;
            this.applier = applier;
        }

        /**
         * Returns {@code true} if the handler applies to the supplied renderer.
         *
         * @param renderer  the renderer.
         *
         * @return A boolean.
         */
        boolean matches(CategoryItemRenderer renderer) {
            return this.type.isInstance(renderer);
        }

        /**
         * Applies the theme to the supplied renderer.
         *
         * @param theme  the theme.
         * @param renderer  the renderer.
         */
        void apply(StandardChartTheme theme, CategoryItemRenderer renderer) {
            this.applier.apply(theme, renderer);
        }
    }

    /**
     * A list of category renderer type handlers, in the order they are checked.
     * All matching handlers are applied, so order matters when types overlap.
     */
    private static final List<CategoryRendererTypeHandler>
            CATEGORY_RENDERER_HANDLERS;
    static {
        List<CategoryRendererTypeHandler> handlers
                = new ArrayList<CategoryRendererTypeHandler>();
        handlers.add(new CategoryRendererTypeHandler(BarRenderer.class,
                new CategoryRendererApplier() {
            @Override
            public void apply(StandardChartTheme theme,
                    CategoryItemRenderer renderer) {
                BarRenderer br = (BarRenderer) renderer;
                br.setBarPainter(theme.barPainter);
                br.setShadowVisible(theme.shadowVisible);
                br.setShadowPaint(theme.shadowPaint);
            }
        }));
        handlers.add(new CategoryRendererTypeHandler(BarRenderer3D.class,
                new CategoryRendererApplier() {
            @Override
            public void apply(StandardChartTheme theme,
                    CategoryItemRenderer renderer) {
                BarRenderer3D br3d = (BarRenderer3D) renderer;
                br3d.setWallPaint(theme.wallPaint);
            }
        }));
        handlers.add(new CategoryRendererTypeHandler(LineRenderer3D.class,
                new CategoryRendererApplier() {
            @Override
            public void apply(StandardChartTheme theme,
                    CategoryItemRenderer renderer) {
                LineRenderer3D lr3d = (LineRenderer3D) renderer;
                lr3d.setWallPaint(theme.wallPaint);
            }
        }));
        handlers.add(new CategoryRendererTypeHandler(StatisticalBarRenderer.class,
                new CategoryRendererApplier() {
            @Override
            public void apply(StandardChartTheme theme,
                    CategoryItemRenderer renderer) {
                StatisticalBarRenderer sbr = (StatisticalBarRenderer) renderer;
                sbr.setErrorIndicatorPaint(theme.errorIndicatorPaint);
            }
        }));
        handlers.add(new CategoryRendererTypeHandler(MinMaxCategoryRenderer.class,
                new CategoryRendererApplier() {
            @Override
            public void apply(StandardChartTheme theme,
                    CategoryItemRenderer renderer) {
                MinMaxCategoryRenderer mmcr = (MinMaxCategoryRenderer) renderer;
                mmcr.setGroupPaint(theme.errorIndicatorPaint);
            }
        }));
        CATEGORY_RENDERER_HANDLERS = Collections.unmodifiableList(handlers);
    }

