    /**
     * Applies this theme to the supplied chart.
     *
     * @param chart  the chart (<code>null</code> not permitted).
     */
    @Override
    public void apply(JFreeChart chart) {
        ParamChecks.nullNotPermitted(chart, "chart");
        TextTitle title = chart.getTitle();
        if (title != null) {
            title.setFont(this.extraLargeFont);
            title.setPaint(this.titlePaint);
        }

        int subtitleCount = chart.getSubtitleCount();
        for (int i = 0; i < subtitleCount; i++) {
            applyToTitle(chart.getSubtitle(i));
        }

        chart.setBackgroundPaint(this.chartBackgroundPaint);

        // now process the plot if there is one
        Plot plot = chart.getPlot();
        if (plot != null) {
            applyToPlot(plot);
        }
    }

    /**
     * Strategy for applying theme attributes to a specific title type.
     */
    private static abstract class TitleApplier {
        private final Class type;
        TitleApplier(Class type) {
            this.type = type;
        }
        boolean matches(Title title) {
            return this.type.isInstance(title);
        }
        abstract void apply(StandardChartTheme theme, Title title);
    }

    private static final TitleApplier[] TITLE_APPLIERS = new TitleApplier[] {
        new TitleApplier(TextTitle.class) {
            @Override
            void apply(StandardChartTheme theme, Title title) {
                TextTitle tt = (TextTitle) title;
                tt.setFont(theme.largeFont);
                tt.setPaint(theme.subtitlePaint);
            }
        },
        new TitleApplier(LegendTitle.class) {
            @Override
            void apply(StandardChartTheme theme, Title title) {
                LegendTitle lt = (LegendTitle) title;
                if (lt.getBackgroundPaint() != null) {
                    lt.setBackgroundPaint(theme.legendBackgroundPaint);
                }
                lt.setItemFont(theme.regularFont);
                lt.setItemPaint(theme.legendItemPaint);
                if (lt.getWrapper() != null) {
                    theme.applyToBlockContainer(lt.getWrapper());
                }
            }
        },
        new TitleApplier(PaintScaleLegend.class) {
            @Override
            void apply(StandardChartTheme theme, Title title) {
                PaintScaleLegend psl = (PaintScaleLegend) title;
                psl.setBackgroundPaint(theme.legendBackgroundPaint);
                ValueAxis axis = psl.getAxis();
                if (axis != null) {
                    theme.applyToValueAxis(axis);
                }
            }
        },
        new TitleApplier(CompositeTitle.class) {
            @Override
            void apply(StandardChartTheme theme, Title title) {
                CompositeTitle ct = (CompositeTitle) title;
                BlockContainer bc = ct.getContainer();
                List blocks = bc.getBlocks();
                Iterator iterator = blocks.iterator();
                while (iterator.hasNext()) {
                    Block b = (Block) iterator.next();
                    if (b instanceof Title) {
                        theme.applyToTitle((Title) b);
                    }
                }
            }
        }
    };

    /**
     * Applies the attributes of this theme to the specified title.
     *
     * @param title  the title.
     */
    protected void applyToTitle(Title title) {
        for (int i = 0; i < TITLE_APPLIERS.length; i++) {
            TitleApplier applier = TITLE_APPLIERS[i];
            if (applier.matches(title)) {
                applier.apply(this, title);
                return;
            }
        }
    }

    /**
     * Applies the attributes of this theme to the specified container.
     *
     * @param bc  a block container (<code>null</code> not permitted).
     */
    protected void applyToBlockContainer(BlockContainer bc) {
        Iterator iterator = bc.getBlocks().iterator();
        while (iterator.hasNext()) {
            Block b = (Block) iterator.next();
            applyToBlock(b);
        }
    }

