    /**
     * Draws a vertical line on the chart to represent a 'range marker'.
     *
     * @param g2  the graphics device.
     * @param plot  the plot.
     * @param domainAxis  the domain axis.
     * @param marker  the marker line.
     * @param dataArea  the axis data area.
     */
    @Override
    public void drawDomainMarker(Graphics2D g2, XYPlot plot, 
            ValueAxis domainAxis, Marker marker, Rectangle2D dataArea) {

        if (marker instanceof ValueMarker) {
            drawValueDomainMarker(g2, plot, domainAxis, (ValueMarker) marker,
                    dataArea);
        }
        else if (marker instanceof IntervalMarker) {
            drawIntervalDomainMarker(g2, plot, domainAxis,
                    (IntervalMarker) marker, dataArea);
        }
    }

    /**
     * Draws a single-value marker on the domain axis.
     *
     * @param g2  the graphics device.
     * @param plot  the plot.
     * @param domainAxis  the domain axis.
     * @param marker  the marker.
     * @param dataArea  the data area.
     */
    private void drawValueDomainMarker(Graphics2D g2, XYPlot plot,
            ValueAxis domainAxis, ValueMarker marker, Rectangle2D dataArea) {

        double value = marker.getValue();
        Range range = domainAxis.getRange();
        if (!range.contains(value)) {
            return;
        }

        double v = domainAxis.valueToJava2D(value, dataArea,
                plot.getDomainAxisEdge());
        PlotOrientation orientation = plot.getOrientation();
        Line2D line = createDomainMarkerLine(dataArea, orientation, v);

        final Composite originalComposite = g2.getComposite();
        g2.setComposite(AlphaComposite.getInstance(
                AlphaComposite.SRC_OVER, marker.getAlpha()));
        g2.setPaint(marker.getPaint());
        g2.setStroke(marker.getStroke());
        g2.draw(line);

        drawDomainValueMarkerLabel(g2, orientation, dataArea, marker, line);
        g2.setComposite(originalComposite);
    }

    /**
     * Creates the line for a single-value domain marker.
     *
     * @param dataArea  the data area.
     * @param orientation  the plot orientation.
     * @param v  the marker value in Java2D space.
     *
     * @return The marker line.
     */
    private Line2D createDomainMarkerLine(Rectangle2D dataArea,
            PlotOrientation orientation, double v) {
        if (orientation == PlotOrientation.HORIZONTAL) {
            return new Line2D.Double(dataArea.getMinX(), v,
                    dataArea.getMaxX(), v);
        }
        else if (orientation == PlotOrientation.VERTICAL) {
            return new Line2D.Double(v, dataArea.getMinY(), v,
                    dataArea.getMaxY());
        }
        else {
            throw new IllegalStateException();
        }
    }

    /**
     * Draws the label for a single-value domain marker.
     *
     * @param g2  the graphics device.
     * @param orientation  the plot orientation.
     * @param dataArea  the data area.
     * @param marker  the marker.
     * @param line  the marker line.
     */
    private void drawDomainValueMarkerLabel(Graphics2D g2,
            PlotOrientation orientation, Rectangle2D dataArea,
            ValueMarker marker, Line2D line) {

        String label = marker.getLabel();
        RectangleAnchor anchor = marker.getLabelAnchor();
        if (label != null) {
            Font labelFont = marker.getLabelFont();
            g2.setFont(labelFont);
            g2.setPaint(marker.getLabelPaint());
            Point2D coordinates = calculateDomainMarkerTextAnchorPoint(
                    g2, orientation, dataArea, line.getBounds2D(),
                    marker.getLabelOffset(),
                    LengthAdjustmentType.EXPAND, anchor);
            TextUtilities.drawAlignedString(label, g2,
                    (float) coordinates.getX(), (float) coordinates.getY(),
                    marker.getLabelTextAnchor());
        }
    }

    /**
     * Draws an interval marker on the domain axis.
     *
     * @param g2  the graphics device.
     * @param plot  the plot.
     * @param domainAxis  the domain axis.
     * @param marker  the interval marker.
     * @param dataArea  the data area.
     */
    private void drawIntervalDomainMarker(Graphics2D g2, XYPlot plot,
            ValueAxis domainAxis, IntervalMarker marker,
            Rectangle2D dataArea) {

        double start = marker.getStartValue();
        double end = marker.getEndValue();
        Range range = domainAxis.getRange();
        if (!(range.intersects(start, end))) {
            return;
        }

        double start2d = domainAxis.valueToJava2D(start, dataArea,
                plot.getDomainAxisEdge());
        double end2d = domainAxis.valueToJava2D(end, dataArea,
                plot.getDomainAxisEdge());
        PlotOrientation orientation = plot.getOrientation();
        Rectangle2D rect = createIntervalDomainRectangle(dataArea,
                orientation, start2d, end2d);

        final Composite originalComposite = g2.getComposite();
        g2.setComposite(AlphaComposite.getInstance(
                AlphaComposite.SRC_OVER, marker.getAlpha()));
        fillIntervalMarker(g2, marker, rect);
        drawIntervalDomainOutlines(g2, dataArea, range, orientation, marker,
                start2d, end2d);
        drawIntervalDomainMarkerLabel(g2, orientation, dataArea, marker, rect);
        g2.setComposite(originalComposite);
    }

    /**
     * Creates the rectangle for an interval domain marker, clipped to the
     * data area.
     *
     * @param dataArea  the data area.
     * @param orientation  the plot orientation.
     * @param start2d  the start value in Java2D space.
     * @param end2d  the end value in Java2D space.
     *
     * @return The marker rectangle (may be <code>null</code> for an unknown
     *         orientation, preserving original behaviour).
     */
    private Rectangle2D createIntervalDomainRectangle(Rectangle2D dataArea,
            PlotOrientation orientation, double start2d, double end2d) {

        double low = Math.min(start2d, end2d);
        double high = Math.max(start2d, end2d);
        if (orientation == PlotOrientation.HORIZONTAL) {
            // clip top and bottom bounds to data area
            low = Math.max(low, dataArea.getMinY());
            high = Math.min(high, dataArea.getMaxY());
            return new Rectangle2D.Double(dataArea.getMinX(), low,
                    dataArea.getWidth(), high - low);
        }
        else if (orientation == PlotOrientation.VERTICAL) {
            // clip left and right bounds to data area
            low = Math.max(low, dataArea.getMinX());
            high = Math.min(high, dataArea.getMaxX());
            return new Rectangle2D.Double(low, dataArea.getMinY(),
                    high - low, dataArea.getHeight());
        }
        return null;
    }

    /**
     * Fills the rectangle for an interval marker.
     *
     * @param g2  the graphics device.
     * @param marker  the interval marker.
     * @param rect  the rectangle to fill.
     */
    private void fillIntervalMarker(Graphics2D g2, IntervalMarker marker,
            Rectangle2D rect) {
        Paint p = marker.getPaint();
        if (p instanceof GradientPaint) {
            GradientPaint gp = (GradientPaint) p;
            GradientPaintTransformer t = marker.getGradientPaintTransformer();
            if (t != null) {
                gp = t.transform(gp, rect);
            }
            g2.setPaint(gp);
        }
        else {
            g2.setPaint(p);
        }
        g2.fill(rect);
    }

