     * @param dataArea  the axis data area.
     */
    @Override
    public void drawRangeMarker(Graphics2D g2, XYPlot plot, ValueAxis rangeAxis,
            Marker marker, Rectangle2D dataArea) {

        if (marker instanceof ValueMarker) {
            drawValueRangeMarker(g2, plot, rangeAxis, (ValueMarker) marker,
                    dataArea);
        }
        else if (marker instanceof IntervalMarker) {
            drawIntervalRangeMarker(g2, plot, rangeAxis,
                    (IntervalMarker) marker, dataArea);
