    /**
     * Draws a single-value marker on the range axis.
     *
     * @param g2  the graphics device.
     * @param plot  the plot.
     * @param rangeAxis  the range axis.
     * @param marker  the marker.
     * @param dataArea  the data area.
     */
    private void drawValueRangeMarker(Graphics2D g2, XYPlot plot,
            ValueAxis rangeAxis, ValueMarker marker, Rectangle2D dataArea) {

        double value = marker.getValue();
        Range range = rangeAxis.getRange();
        if (!range.contains(value)) {
            return;
        }

        double v = rangeAxis.valueToJava2D(value, dataArea,
                plot.getRangeAxisEdge());
        PlotOrientation orientation = plot.getOrientation();
        Line2D line = createRangeMarkerLine(dataArea, orientation, v);

        final Composite originalComposite = g2.getComposite();
        g2.setComposite(AlphaComposite.getInstance(
                AlphaComposite.SRC_OVER, marker.getAlpha()));
        g2.setPaint(marker.getPaint());
        g2.setStroke(marker.getStroke());
        g2.draw(line);

        drawRangeValueMarkerLabel(g2, orientation, dataArea, marker, line);
        g2.setComposite(originalComposite);
    }

    /**
     * Creates the line for a single-value range marker.
     *
     * @param dataArea  the data area.
     * @param orientation  the plot orientation.
     * @param v  the marker value in Java2D space.
     *
     * @return The marker line.
     */
    private Line2D createRangeMarkerLine(Rectangle2D dataArea,
            PlotOrientation orientation, double v) {
        if (orientation == PlotOrientation.HORIZONTAL) {
            return new Line2D.Double(v, dataArea.getMinY(), v,
                    dataArea.getMaxY());
        }
        else if (orientation == PlotOrientation.VERTICAL) {
            return new Line2D.Double(dataArea.getMinX(), v,
                    dataArea.getMaxX(), v);
        }
        else {
            throw new IllegalStateException("Unknown orientation.");
        }
    }

