    /**
     * Draws an interval marker on the range axis.
     *
     * @param g2  the graphics device.
     * @param plot  the plot.
     * @param rangeAxis  the range axis.
     * @param marker  the interval marker.
     * @param dataArea  the data area.
     */
    private void drawIntervalRangeMarker(Graphics2D g2, XYPlot plot,
            ValueAxis rangeAxis, IntervalMarker marker, Rectangle2D dataArea) {

        double start = marker.getStartValue();
        double end = marker.getEndValue();
        Range range = rangeAxis.getRange();
        if (!(range.intersects(start, end))) {
            return;
        }

        double start2d = rangeAxis.valueToJava2D(start, dataArea,
                plot.getRangeAxisEdge());
        double end2d = rangeAxis.valueToJava2D(end, dataArea,
                plot.getRangeAxisEdge());
        PlotOrientation orientation = plot.getOrientation();
        Rectangle2D rect = createIntervalRangeRectangle(dataArea,
                orientation, start2d, end2d);

        final Composite originalComposite = g2.getComposite();
        g2.setComposite(AlphaComposite.getInstance(
                AlphaComposite.SRC_OVER, marker.getAlpha()));
        fillIntervalMarker(g2, marker, rect);
        drawIntervalRangeOutlines(g2, dataArea, range, orientation, marker,
                start2d, end2d);
        drawIntervalRangeMarkerLabel(g2, orientation, dataArea, marker, rect);
        g2.setComposite(originalComposite);
    }

