     *
     * @param context  the render context.
     * @param spec  the axis line spec.
     */
    private void drawDomainLine(RenderContext context, AxisLineSpec spec) {
        Range range = spec.axis.getRange();
        if (!range.contains(spec.value)) {
            return;
