        PlotOrientation orientation = context.plot.getOrientation();
        Line2D line = null;
        double v = spec.axis.valueToJava2D(spec.value, context.dataArea, 
                context.plot.getDomainAxisEdge());
        if (orientation.isHorizontal()) {
