    /**
     * Fills a domain grid band using the supplied context and range.
     *
     * @param ctx  the axis line context.
     * @param range  the grid band range.
     */
    private void fillDomainGridBand(AxisLineContext ctx, GridBandRange range) {
        double x1 = ctx.getAxis().valueToJava2D(range.getStart(),
                ctx.getDataArea(), ctx.getPlot().getDomainAxisEdge());
        double x2 = ctx.getAxis().valueToJava2D(range.getEnd(),
                ctx.getDataArea(), ctx.getPlot().getDomainAxisEdge());
        Rectangle2D band;
        if (ctx.getPlot().getOrientation() == PlotOrientation.VERTICAL) {
            band = new Rectangle2D.Double(Math.min(x1, x2),
                    ctx.getDataArea().getMinY(),
                    Math.abs(x2 - x1), ctx.getDataArea().getHeight());
        }
        else {
            band = new Rectangle2D.Double(ctx.getDataArea().getMinX(),
                    Math.min(x1, x2),
                    ctx.getDataArea().getWidth(), Math.abs(x2 - x1));
        }
        Paint paint = ctx.getPlot().getDomainTickBandPaint();

        if (paint != null) {
            ctx.getG2().setPaint(paint);
            ctx.getG2().fill(band);
        }
    }

