    /**
     * Draws a domain grid line using the supplied context.
     *
     * @param ctx  the axis line context.
     * @param value  the data value.
     */
    private void drawDomainGridLine(AxisLineContext ctx, double value) {
        Range range = ctx.getAxis().getRange();
        if (!range.contains(value)) {
            return;
        }

        PlotOrientation orientation = ctx.getPlot().getOrientation();
        double v = ctx.getAxis().valueToJava2D(value, ctx.getDataArea(),
                ctx.getPlot().getDomainAxisEdge());
        Line2D line = null;
        if (orientation == PlotOrientation.HORIZONTAL) {
            line = new Line2D.Double(ctx.getDataArea().getMinX(), v,
                    ctx.getDataArea().getMaxX(), v);
        }
        else if (orientation == PlotOrientation.VERTICAL) {
            line = new Line2D.Double(v, ctx.getDataArea().getMinY(), v,
                    ctx.getDataArea().getMaxY());
        }

        Paint paint = ctx.getPlot().getDomainGridlinePaint();
        Stroke stroke = ctx.getPlot().getDomainGridlineStroke();
        ctx.getG2().setPaint(paint != null ? paint : Plot.DEFAULT_OUTLINE_PAINT);
        ctx.getG2().setStroke(stroke != null ? stroke : Plot.DEFAULT_OUTLINE_STROKE);
        Object saved = ctx.getG2().getRenderingHint(
                RenderingHints.KEY_STROKE_CONTROL);
        ctx.getG2().setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, 
                RenderingHints.VALUE_STROKE_NORMALIZE);
        ctx.getG2().draw(line);
        ctx.getG2().setRenderingHint(RenderingHints.KEY_STROKE_CONTROL, saved);
    }

