    /**
     * Draws a value marker on the domain axis.
     *
     * @param ctx  the marker draw context.
     * @param marker  the value marker.
     */
    private void drawValueDomainMarker(MarkerDrawContext ctx,
            ValueMarker marker) {
        double value = marker.getValue();
        Range range = ctx.getAxis().getRange();
        if (!range.contains(value)) {
            return;
        }

        double v = ctx.getAxis().valueToJava2D(value, ctx.getDataArea(),
                ctx.getPlot().getDomainAxisEdge());

        PlotOrientation orientation = ctx.getPlot().getOrientation();
        Line2D line = null;
        if (orientation == PlotOrientation.HORIZONTAL) {
            line = new Line2D.Double(ctx.getDataArea().getMinX(), v,
                    ctx.getDataArea().getMaxX(), v);
        }
        else if (orientation == PlotOrientation.VERTICAL) {
            line = new Line2D.Double(v, ctx.getDataArea().getMinY(), v,
                    ctx.getDataArea().getMaxY());
        } else {
            throw new IllegalStateException();
        }

        final Composite originalComposite = ctx.getG2().getComposite();
        ctx.getG2().setComposite(AlphaComposite.getInstance(
                AlphaComposite.SRC_OVER, marker.getAlpha()));
        ctx.getG2().setPaint(marker.getPaint());
        ctx.getG2().setStroke(marker.getStroke());
        ctx.getG2().draw(line);

        String label = marker.getLabel();
        RectangleAnchor anchor = marker.getLabelAnchor();
        if (label != null) {
            Font labelFont = marker.getLabelFont();
            ctx.getG2().setFont(labelFont);
            ctx.getG2().setPaint(marker.getLabelPaint());
            Point2D coordinates = calculateDomainMarkerTextAnchorPoint(
                    ctx.getG2(), orientation, ctx.getDataArea(),
                    line.getBounds2D(),
                    marker.getLabelOffset(),
                    LengthAdjustmentType.EXPAND, anchor);
            TextUtilities.drawAlignedString(label, ctx.getG2(),
                    (float) coordinates.getX(), (float) coordinates.getY(),
                    marker.getLabelTextAnchor());
        }
        ctx.getG2().setComposite(originalComposite);
    }

    /**
     * Draws an interval marker on the domain axis.
     *
     * @param ctx  the marker draw context.
     * @param marker  the interval marker.
     */
    private void drawIntervalDomainMarker(MarkerDrawContext ctx,
            IntervalMarker marker) {
        double start = marker.getStartValue();
        double end = marker.getEndValue();
        Range range = ctx.getAxis().getRange();
        if (!(range.intersects(start, end))) {
            return;
        }

        double start2d = ctx.getAxis().valueToJava2D(start, ctx.getDataArea(),
                ctx.getPlot().getDomainAxisEdge());
        double end2d = ctx.getAxis().valueToJava2D(end, ctx.getDataArea(),
                ctx.getPlot().getDomainAxisEdge());
        double low = Math.min(start2d, end2d);
        double high = Math.max(start2d, end2d);

        PlotOrientation orientation = ctx.getPlot().getOrientation();
        Rectangle2D rect = null;
        if (orientation == PlotOrientation.HORIZONTAL) {
            // clip top and bottom bounds to data area
            low = Math.max(low, ctx.getDataArea().getMinY());
            high = Math.min(high, ctx.getDataArea().getMaxY());
            rect = new Rectangle2D.Double(ctx.getDataArea().getMinX(),
                    low, ctx.getDataArea().getWidth(),
                    high - low);
        }
        else if (orientation == PlotOrientation.VERTICAL) {
            // clip left and right bounds to data area
            low = Math.max(low, ctx.getDataArea().getMinX());
            high = Math.min(high, ctx.getDataArea().getMaxX());
            rect = new Rectangle2D.Double(low,
                    ctx.getDataArea().getMinY(), high - low,
                    ctx.getDataArea().getHeight());
        }

        final Composite originalComposite = ctx.getG2().getComposite();
        ctx.getG2().setComposite(AlphaComposite.getInstance(
                AlphaComposite.SRC_OVER, marker.getAlpha()));
        Paint p = marker.getPaint();
        if (p instanceof GradientPaint) {
            GradientPaint gp = (GradientPaint) p;
            GradientPaintTransformer t = marker.getGradientPaintTransformer();
            if (t != null) {
                gp = t.transform(gp, rect);
            }
            ctx.getG2().setPaint(gp);
        }
        else {
            ctx.getG2().setPaint(p);
        }
        ctx.getG2().fill(rect);

        // now draw the outlines, if visible...
        if (marker.getOutlinePaint() != null
                && marker.getOutlineStroke() != null) {
            if (orientation == PlotOrientation.VERTICAL) {
                Line2D line = new Line2D.Double();
                double y0 = ctx.getDataArea().getMinY();
                double y1 = ctx.getDataArea().getMaxY();
                ctx.getG2().setPaint(marker.getOutlinePaint());
                ctx.getG2().setStroke(marker.getOutlineStroke());
                if (range.contains(start)) {
                    line.setLine(start2d, y0, start2d, y1);
                    ctx.getG2().draw(line);
                }
                if (range.contains(end)) {
                    line.setLine(end2d, y0, end2d, y1);
                    ctx.getG2().draw(line);
                }
            }
            else { // PlotOrientation.HORIZONTAL
                Line2D line = new Line2D.Double();
                double x0 = ctx.getDataArea().getMinX();
                double x1 = ctx.getDataArea().getMaxX();
                ctx.getG2().setPaint(marker.getOutlinePaint());
                ctx.getG2().setStroke(marker.getOutlineStroke());
                if (range.contains(start)) {
                    line.setLine(x0, start2d, x1, start2d);
                    ctx.getG2().draw(line);
                }
                if (range.contains(end)) {
                    line.setLine(x0, end2d, x1, end2d);
                    ctx.getG2().draw(line);
                }
            }
        }

        String label = marker.getLabel();
        RectangleAnchor anchor = marker.getLabelAnchor();
        if (label != null) {
            Font labelFont = marker.getLabelFont();
            ctx.getG2().setFont(labelFont);
            ctx.getG2().setPaint(marker.getLabelPaint());
            Point2D coordinates = calculateDomainMarkerTextAnchorPoint(
                    ctx.getG2(), orientation, ctx.getDataArea(), rect,
                    marker.getLabelOffset(), marker.getLabelOffsetType(),
                    anchor);
            TextUtilities.drawAlignedString(label, ctx.getG2(),
                    (float) coordinates.getX(), (float) coordinates.getY(),
                    marker.getLabelTextAnchor());
        }
        ctx.getG2().setComposite(originalComposite);
    }

    /**
     * Calculates the (x, y) coordinates for drawing a marker label.
     *
     * @param g2  the graphics device.
     * @param orientation  the plot orientation.
     * @param dataArea  the data area.
     * @param markerArea  the rectangle surrounding the marker area.
     * @param markerOffset  the marker label offset.
     * @param labelOffsetType  the label offset type.
     * @param anchor  the label anchor.
     *
     * @return The coordinates for drawing the marker label.
     */
    protected Point2D calculateDomainMarkerTextAnchorPoint(Graphics2D g2,
            PlotOrientation orientation, Rectangle2D dataArea,
            Rectangle2D markerArea, RectangleInsets markerOffset,
            LengthAdjustmentType labelOffsetType, RectangleAnchor anchor) {
        return calculateDomainMarkerTextAnchorPoint(
                new MarkerLabelContext(orientation, dataArea, markerArea,
                        markerOffset),
                new MarkerLabelStyle(labelOffsetType, anchor));
    }

    /**
     * Calculates the anchor point for a domain marker label.
     *
     * @param ctx  the marker label context.
     * @param style  the marker label style.
     *
     * @return The coordinates for drawing the marker label.
     */
    private Point2D calculateDomainMarkerTextAnchorPoint(
            MarkerLabelContext ctx, MarkerLabelStyle style) {
        Rectangle2D anchorRect = null;
        if (ctx.getOrientation() == PlotOrientation.HORIZONTAL) {
            anchorRect = ctx.getMarkerOffset().createAdjustedRectangle(
                    ctx.getMarkerArea(),
                    LengthAdjustmentType.CONTRACT,
                    style.getLabelOffsetType());
        }
        else if (ctx.getOrientation() == PlotOrientation.VERTICAL) {
            anchorRect = ctx.getMarkerOffset().createAdjustedRectangle(
                    ctx.getMarkerArea(),
                    style.getLabelOffsetType(),
                    LengthAdjustmentType.CONTRACT);
        }
        return RectangleAnchor.coordinates(anchorRect, style.getAnchor());
    }

