     * Considers the current (x, y) coordinate and updates the crosshair point
     * if it meets the criteria (usually means the (x, y) coordinate is the
     * closest to the anchor point so far).
     *
     * @param crosshairState  the crosshair state (<code>null</code> permitted,
     *                        but the method does nothing in that case).
     * @param x  the x-value (in data space).
     * @param y  the y-value (in data space).
     * @param domainAxisIndex  the index of the domain axis for the point.
     * @param rangeAxisIndex  the index of the range axis for the point.
     * @param transX  the x-value translated to Java2D space.
     * @param transY  the y-value translated to Java2D space.
     * @param orientation  the plot orientation (<code>null</code> not
     *                     permitted).
     *
     * @since 1.0.4
     */
    protected void updateCrosshairValues(CrosshairState crosshairState,
            double x, double y, int domainAxisIndex, int rangeAxisIndex,
            double transX, double transY, PlotOrientation orientation) {
        ParamChecks.nullNotPermitted(orientation, "orientation");
        if (crosshairState != null) {
            updateCrosshairValues(crosshairState, new CrosshairParams(x, y,
                    domainAxisIndex, rangeAxisIndex, transX, transY,
                    orientation));
        }
    }

    /**
     * Updates the crosshair state using the supplied parameter object.
     *
     * @param crosshairState  the crosshair state.
     * @param params  the crosshair parameters.
     */
    private void updateCrosshairValues(CrosshairState crosshairState,
            CrosshairParams params) {
        if (this.plot.isDomainCrosshairLockedOnData()) {
            if (this.plot.isRangeCrosshairLockedOnData()) {
                // both axes
                crosshairState.updateCrosshairPoint(params.getX(),
                        params.getY(), params.getDomainAxisIndex(),
                        params.getRangeAxisIndex(), params.getTransX(),
                        params.getTransY(), params.getOrientation());
            }
            else {
                // just the domain axis...
                crosshairState.updateCrosshairX(params.getX(),
                        params.getDomainAxisIndex());
            }
        }
        else {
            if (this.plot.isRangeCrosshairLockedOnData()) {
                // just the range axis...
                crosshairState.updateCrosshairY(params.getY(),
                        params.getRangeAxisIndex());
            }
        }
    }

