     *                  label position).
     */
    protected void drawItemLabel(Graphics2D g2, PlotOrientation orientation,
            XYDataset dataset, int series, int item, double x, double y,
            boolean negative) {
        drawItemLabel(new ItemLabelContext(g2, orientation, dataset, series,
                item, x, y, negative));
    }

    /**
     * Draws an item label using the supplied context.
     *
     * @param ctx  the item label context.
     */
    private void drawItemLabel(ItemLabelContext ctx) {
        XYItemLabelGenerator generator = getItemLabelGenerator(
                ctx.getSeries(), ctx.getItem());
        if (generator != null) {
            Font labelFont = getItemLabelFont(ctx.getSeries(), ctx.getItem());
            Paint paint = getItemLabelPaint(ctx.getSeries(), ctx.getItem());
            ctx.getG2().setFont(labelFont);
            ctx.getG2().setPaint(paint);
            String label = generator.generateLabel(ctx.getDataset(),
                    ctx.getSeries(), ctx.getItem());

            // get the label position..
            ItemLabelPosition position;
            if (!ctx.isNegative()) {
                position = getPositiveItemLabelPosition(ctx.getSeries(),
                        ctx.getItem());
            }
            else {
                position = getNegativeItemLabelPosition(ctx.getSeries(),
                        ctx.getItem());
            }

            // work out the label anchor point...
            Point2D anchorPoint = calculateLabelAnchorPoint(
                    position.getItemLabelAnchor(), ctx.getX(), ctx.getY(),
                    ctx.getOrientation());
            TextUtilities.drawRotatedString(label, ctx.getG2(),
                    (float) anchorPoint.getX(), (float) anchorPoint.getY(),
                    position.getTextAnchor(), position.getAngle(),
                    position.getRotationAnchor());
        }
    }

