        addEntity(new EntityContext(entities, area, dataset, series, item,
                entityX, entityY));
    }

    /**
     * Adds an entity to the collection using the supplied context.
     *
     * @param ctx  the entity context.
     */
    private void addEntity(EntityContext ctx) {
        if (!getItemCreateEntity(ctx.getSeries(), ctx.getItem())) {
            return;
        }
        Shape hotspot = ctx.getArea();
        if (hotspot == null) {
            double r = getDefaultEntityRadius();
            double w = r * 2;
            if (getPlot().getOrientation() == PlotOrientation.VERTICAL) {
                hotspot = new Ellipse2D.Double(ctx.getEntityX() - r,
                        ctx.getEntityY() - r, w, w);
            }
            else {
                hotspot = new Ellipse2D.Double(ctx.getEntityY() - r,
                        ctx.getEntityX() - r, w, w);
            }
        }
        String tip = null;
        XYToolTipGenerator generator = getToolTipGenerator(ctx.getSeries(),
                ctx.getItem());
        if (generator != null) {
            tip = generator.generateToolTip(ctx.getDataset(), ctx.getSeries(),
                    ctx.getItem());
        }
        String url = null;
        if (getURLGenerator() != null) {
            url = getURLGenerator().generateURL(ctx.getDataset(),
                    ctx.getSeries(), ctx.getItem());
        }
        XYItemEntity entity = new XYItemEntity(hotspot, ctx.getDataset(),
                ctx.getSeries(), ctx.getItem(), tip, url);
        ctx.getEntities().add(entity);
    }

