     * @param start  the start value.
     * @param end  the end value.
     */
    private void fillDomainGridBand(AxisDrawContext ctx, double start,
            double end) {
        double x1 = ctx.axis.valueToJava2D(start, ctx.dataArea,
                ctx.plot.getDomainAxisEdge());
        double x2 = ctx.axis.valueToJava2D(end, ctx.dataArea,
                ctx.plot.getDomainAxisEdge());
        Rectangle2D band = createDomainGridBand(ctx, x1, x2);
        Paint paint = ctx.plot.getDomainTickBandPaint();

        if (paint != null) {
            ctx.g2.setPaint(paint);
            ctx.g2.fill(band);
