    /**
     * Creates the band rectangle for a domain grid band.
     *
     * @param ctx  the axis draw context.
     * @param x1  the first Java2D x-coordinate.
     * @param x2  the second Java2D x-coordinate.
     *
     * @return The band rectangle.
     */
    private Rectangle2D createDomainGridBand(AxisDrawContext ctx, double x1,
            double x2) {
        if (ctx.plot.getOrientation() == PlotOrientation.VERTICAL) {
            return new Rectangle2D.Double(Math.min(x1, x2),
                    ctx.dataArea.getMinY(), Math.abs(x2 - x1),
                    ctx.dataArea.getHeight());
        }
        else {
            return new Rectangle2D.Double(ctx.dataArea.getMinX(),
                    Math.min(x1, x2), ctx.dataArea.getWidth(),
                    Math.abs(x2 - x1));
        }
    }

