                value);
    }

    /**
     * Draws a domain grid line using the supplied context.
     *
     * @param ctx  the axis draw context.
     * @param value  the data value.
     */
    private void drawDomainGridLine(AxisDrawContext ctx, double value) {
        Range range = ctx.axis.getRange();
        if (!range.contains(value)) {
            return;
        }

        PlotOrientation orientation = ctx.plot.getOrientation();
        double v = ctx.axis.valueToJava2D(value, ctx.dataArea,
                ctx.plot.getDomainAxisEdge());
        Line2D line = createDomainLine(ctx, v, orientation);
        if (line == null) {
            return;
        }

        Paint paint = ctx.plot.getDomainGridlinePaint();
        Stroke stroke = ctx.plot.getDomainGridlineStroke();
        ctx.g2.setPaint(paint != null ? paint : Plot.DEFAULT_OUTLINE_PAINT);
        ctx.g2.setStroke(stroke != null ? stroke : Plot.DEFAULT_OUTLINE_STROKE);
        drawNormalizedLine(ctx.g2, line);
    }

