     * @param dataArea  the axis data area.
     */
    @Override
    public void drawDomainMarker(Graphics2D g2, XYPlot plot, 
            ValueAxis domainAxis, Marker marker, Rectangle2D dataArea) {
        drawDomainMarker(new AxisDrawContext(g2, plot, domainAxis, dataArea),
                marker);
    }

    /**
     * Draws a domain marker using the supplied context.
     *
     * @param ctx  the axis draw context.
     * @param marker  the marker.
     */
    private void drawDomainMarker(AxisDrawContext ctx, Marker marker) {
        if (marker instanceof ValueMarker) {
            drawValueDomainMarker(ctx, (ValueMarker) marker);
        }
        else if (marker instanceof IntervalMarker) {
            drawIntervalDomainMarker(ctx, (IntervalMarker) marker);
        }
    }

    /**
     * Draws a value marker on the domain axis.
     *
     * @param ctx  the axis draw context.
     * @param marker  the value marker.
     */
    private void drawValueDomainMarker(AxisDrawContext ctx,
            ValueMarker marker) {
        double value = marker.getValue();
        Range range = ctx.axis.getRange();
        if (!range.contains(value)) {
            return;
        }

        double v = ctx.axis.valueToJava2D(value, ctx.dataArea,
                ctx.plot.getDomainAxisEdge());

        PlotOrientation orientation = ctx.plot.getOrientation();
        Line2D line = createDomainLine(ctx, v, orientation);
        if (line == null) {
            throw new IllegalStateException();
        }

        final Composite originalComposite = ctx.g2.getComposite();
        ctx.g2.setComposite(AlphaComposite.getInstance(
                AlphaComposite.SRC_OVER, marker.getAlpha()));
        ctx.g2.setPaint(marker.getPaint());
        ctx.g2.setStroke(marker.getStroke());
        ctx.g2.draw(line);

        drawDomainMarkerLabel(ctx, line.getBounds2D(), marker,
                LengthAdjustmentType.EXPAND);
        ctx.g2.setComposite(originalComposite);
    }

    /**
     * Draws an interval marker on the domain axis.
     *
     * @param ctx  the axis draw context.
     * @param marker  the interval marker.
     */
    private void drawIntervalDomainMarker(AxisDrawContext ctx,
            IntervalMarker marker) {
        double start = marker.getStartValue();
        double end = marker.getEndValue();
        Range range = ctx.axis.getRange();
        if (!range.intersects(start, end)) {
            return;
        }

        double start2d = ctx.axis.valueToJava2D(start, ctx.dataArea,
                ctx.plot.getDomainAxisEdge());
        double end2d = ctx.axis.valueToJava2D(end, ctx.dataArea,
                ctx.plot.getDomainAxisEdge());
        double low = Math.min(start2d, end2d);
        double high = Math.max(start2d, end2d);

        PlotOrientation orientation = ctx.plot.getOrientation();
        Rectangle2D rect = createDomainIntervalRect(ctx, low, high,
                orientation);
        if (rect == null) {
            return;
        }

        final Composite originalComposite = ctx.g2.getComposite();
        ctx.g2.setComposite(AlphaComposite.getInstance(
                AlphaComposite.SRC_OVER, marker.getAlpha()));
        fillIntervalMarker(ctx.g2, marker, rect);
        drawIntervalOutlines(ctx, new IntervalOutlineContext(marker, start2d,
                end2d, orientation));
        drawDomainMarkerLabel(ctx, rect, marker, marker.getLabelOffsetType());
        ctx.g2.setComposite(originalComposite);
    }

    /**
     * Creates the rectangle for an interval marker on the domain axis.
     *
     * @param ctx  the axis draw context.
     * @param low  the low Java2D coordinate.
     * @param high  the high Java2D coordinate.
     * @param orientation  the plot orientation.
     *
     * @return The rectangle, or <code>null</code> if the orientation is unknown.
     */
    private Rectangle2D createDomainIntervalRect(AxisDrawContext ctx,
            double low, double high, PlotOrientation orientation) {
        if (orientation == PlotOrientation.HORIZONTAL) {
            low = Math.max(low, ctx.dataArea.getMinY());
            high = Math.min(high, ctx.dataArea.getMaxY());
            return new Rectangle2D.Double(ctx.dataArea.getMinX(), low,
                    ctx.dataArea.getWidth(), high - low);
        }
        else if (orientation == PlotOrientation.VERTICAL) {
            low = Math.max(low, ctx.dataArea.getMinX());
            high = Math.min(high, ctx.dataArea.getMaxX());
            return new Rectangle2D.Double(low, ctx.dataArea.getMinY(),
                    high - low, ctx.dataArea.getHeight());
        }
        return null;
    }

    /**
     * Fills the rectangle for an interval marker.
     *
     * @param g2  the graphics device.
     * @param marker  the interval marker.
     * @param rect  the rectangle.
     */
    private void fillIntervalMarker(Graphics2D g2, IntervalMarker marker,
            Rectangle2D rect) {
        Paint p = marker.getPaint();
        if (p instanceof GradientPaint) {
            GradientPaint gp = (GradientPaint) p;
            GradientPaintTransformer t = marker.getGradientPaintTransformer();
            if (t != null) {
                gp = t.transform(gp, rect);
            }
            g2.setPaint(gp);
        }
        else {
            g2.setPaint(p);
        }
        g2.fill(rect);
    }

    /**
     * Draws the outlines for an interval marker on the domain axis.
     *
     * @param ctx  the axis draw context.
     * @param oc  the outline context.
     */
    private void drawIntervalOutlines(AxisDrawContext ctx,
            IntervalOutlineContext oc) {
        IntervalMarker im = oc.marker;
        if (im.getOutlinePaint() == null || im.getOutlineStroke() == null) {
            return;
        }

        Range range = ctx.axis.getRange();
        Line2D line = new Line2D.Double();
        ctx.g2.setPaint(im.getOutlinePaint());
        ctx.g2.setStroke(im.getOutlineStroke());

        if (oc.orientation == PlotOrientation.VERTICAL) {
            double y0 = ctx.dataArea.getMinY();
            double y1 = ctx.dataArea.getMaxY();
            if (range.contains(im.getStartValue())) {
                line.setLine(oc.start2d, y0, oc.start2d, y1);
                ctx.g2.draw(line);
            }
            if (range.contains(im.getEndValue())) {
                line.setLine(oc.end2d, y0, oc.end2d, y1);
                ctx.g2.draw(line);
            }
        }
        else { // PlotOrientation.HORIZONTAL
            double x0 = ctx.dataArea.getMinX();
            double x1 = ctx.dataArea.getMaxX();
            if (range.contains(im.getStartValue())) {
                line.setLine(x0, oc.start2d, x1, oc.start2d);
                ctx.g2.draw(line);
            }
            if (range.contains(im.getEndValue())) {
                line.setLine(x0, oc.end2d, x1, oc.end2d);
                ctx.g2.draw(line);
            }
        }
    }

    /**
     * Draws a marker label for the domain axis.
     *
     * @param ctx  the axis draw context.
     * @param markerArea  the marker area.
     * @param marker  the marker.
     * @param offsetType  the label offset type.
     */
    private void drawDomainMarkerLabel(AxisDrawContext ctx,
            Rectangle2D markerArea, Marker marker,
            LengthAdjustmentType offsetType) {
        String label = marker.getLabel();
        RectangleAnchor anchor = marker.getLabelAnchor();
        if (label != null) {
            Font labelFont = marker.getLabelFont();
            ctx.g2.setFont(labelFont);
            ctx.g2.setPaint(marker.getLabelPaint());
            Point2D coordinates = calculateDomainMarkerTextAnchorPoint(
                    new MarkerAnchorBase(ctx.g2, ctx.plot.getOrientation(),
                            ctx.dataArea, markerArea),
                    new MarkerAnchorOffset(marker.getLabelOffset(), offsetType,
                            anchor));
            TextUtilities.drawAlignedString(label, ctx.g2,
                    (float) coordinates.getX(), (float) coordinates.getY(),
                    marker.getLabelTextAnchor());
        }
    }

    /**
     * Calculates the (x, y) coordinates for drawing a marker label.
     *
     * @param g2  the graphics device.
     * @param orientation  the plot orientation.
     * @param dataArea  the data area.
     * @param markerArea  the rectangle surrounding the marker area.
     * @param markerOffset  the marker label offset.
     * @param labelOffsetType  the label offset type.
     * @param anchor  the label anchor.
     *
     * @return The coordinates for drawing the marker label.
     */
    protected Point2D calculateDomainMarkerTextAnchorPoint(Graphics2D g2,
            PlotOrientation orientation, Rectangle2D dataArea,
            Rectangle2D markerArea, RectangleInsets markerOffset,
            LengthAdjustmentType labelOffsetType, RectangleAnchor anchor) {
        return calculateDomainMarkerTextAnchorPoint(
                new MarkerAnchorBase(g2, orientation, dataArea, markerArea),
                new MarkerAnchorOffset(markerOffset, labelOffsetType, anchor));
    }

    /**
     * Calculates the (x, y) coordinates for drawing a domain marker label.
     *
     * @param base  the base anchor data.
     * @param offset  the offset anchor data.
     *
     * @return The coordinates for drawing the marker label.
     */
    private Point2D calculateDomainMarkerTextAnchorPoint(MarkerAnchorBase base,
            MarkerAnchorOffset offset) {
        Rectangle2D anchorRect = null;
        if (base.orientation == PlotOrientation.HORIZONTAL) {
            anchorRect = offset.markerOffset.createAdjustedRectangle(
                    base.markerArea, LengthAdjustmentType.CONTRACT,
                    offset.labelOffsetType);
        }
        else if (base.orientation == PlotOrientation.VERTICAL) {
            anchorRect = offset.markerOffset.createAdjustedRectangle(
                    base.markerArea, offset.labelOffsetType,
                    LengthAdjustmentType.CONTRACT);
        }
        return RectangleAnchor.coordinates(anchorRect, offset.anchor);
    }

