    /**
     * Draws a value marker on the range axis.
     *
     * @param ctx  the axis draw context.
     * @param marker  the value marker.
     */
    private void drawValueRangeMarker(AxisDrawContext ctx, ValueMarker marker) {
        double value = marker.getValue();
        Range range = ctx.axis.getRange();
        if (!range.contains(value)) {
            return;
        }

        double v = ctx.axis.valueToJava2D(value, ctx.dataArea,
                ctx.plot.getRangeAxisEdge());
        PlotOrientation orientation = ctx.plot.getOrientation();
        Line2D line = createRangeLine(ctx, v, orientation);
        if (line == null) {
            throw new IllegalStateException("Unknown orientation.");
        }

        final Composite originalComposite = ctx.g2.getComposite();
        ctx.g2.setComposite(AlphaComposite.getInstance(
                AlphaComposite.SRC_OVER, marker.getAlpha()));
        ctx.g2.setPaint(marker.getPaint());
        ctx.g2.setStroke(marker.getStroke());
        ctx.g2.draw(line);

        drawRangeMarkerLabel(ctx, line.getBounds2D(), marker,
                LengthAdjustmentType.EXPAND);
        ctx.g2.setComposite(originalComposite);
    }

    /**
     * Draws an interval marker on the range axis.
     *
     * @param ctx  the axis draw context.
     * @param marker  the interval marker.
     */
    private void drawIntervalRangeMarker(AxisDrawContext ctx,
            IntervalMarker marker) {
        double start = marker.getStartValue();
        double end = marker.getEndValue();
        Range range = ctx.axis.getRange();
        if (!range.intersects(start, end)) {
            return;
        }

        double start2d = ctx.axis.valueToJava2D(start, ctx.dataArea,
                ctx.plot.getRangeAxisEdge());
        double end2d = ctx.axis.valueToJava2D(end, ctx.dataArea,
                ctx.plot.getRangeAxisEdge());
        double low = Math.min(start2d, end2d);
        double high = Math.max(start2d, end2d);

        PlotOrientation orientation = ctx.plot.getOrientation();
        Rectangle2D rect = createRangeIntervalRect(ctx, low, high,
                orientation);
        if (rect == null) {
            return;
        }

        final Composite originalComposite = ctx.g2.getComposite();
        ctx.g2.setComposite(AlphaComposite.getInstance(
                AlphaComposite.SRC_OVER, marker.getAlpha()));
        fillIntervalMarker(ctx.g2, marker, rect);
        drawRangeIntervalOutlines(ctx, new IntervalOutlineContext(marker,
                start2d, end2d, orientation));
        drawRangeMarkerLabel(ctx, rect, marker, marker.getLabelOffsetType());
        ctx.g2.setComposite(originalComposite);
    }

    /**
     * Creates the rectangle for an interval marker on the range axis.
     *
     * @param ctx  the axis draw context.
     * @param low  the low Java2D coordinate.
     * @param high  the high Java2D coordinate.
     * @param orientation  the plot orientation.
     *
     * @return The rectangle, or <code>null</code> if the orientation is unknown.
     */
    private Rectangle2D createRangeIntervalRect(AxisDrawContext ctx,
            double low, double high, PlotOrientation orientation) {
        if (orientation == PlotOrientation.HORIZONTAL) {
            low = Math.max(low, ctx.dataArea.getMinX());
            high = Math.min(high, ctx.dataArea.getMaxX());
            return new Rectangle2D.Double(low, ctx.dataArea.getMinY(),
                    high - low, ctx.dataArea.getHeight());
        }
        else if (orientation == PlotOrientation.VERTICAL) {
            low = Math.max(low, ctx.dataArea.getMinY());
            high = Math.min(high, ctx.dataArea.getMaxY());
            return new Rectangle2D.Double(ctx.dataArea.getMinX(), low,
                    ctx.dataArea.getWidth(), high - low);
        }
        return null;
    }

    /**
     * Draws the outlines for an interval marker on the range axis.
     *
     * @param ctx  the axis draw context.
     * @param oc  the outline context.
     */
    private void drawRangeIntervalOutlines(AxisDrawContext ctx,
            IntervalOutlineContext oc) {
        IntervalMarker im = oc.marker;
        if (im.getOutlinePaint() == null || im.getOutlineStroke() == null) {
            return;
        }

        Range range = ctx.axis.getRange();
        Line2D line = new Line2D.Double();
        ctx.g2.setPaint(im.getOutlinePaint());
        ctx.g2.setStroke(im.getOutlineStroke());

        if (oc.orientation == PlotOrientation.VERTICAL) {
            double x0 = ctx.dataArea.getMinX();
            double x1 = ctx.dataArea.getMaxX();
            if (range.contains(im.getStartValue())) {
                line.setLine(x0, oc.start2d, x1, oc.start2d);
                ctx.g2.draw(line);
            }
            if (range.contains(im.getEndValue())) {
                line.setLine(x0, oc.end2d, x1, oc.end2d);
                ctx.g2.draw(line);
            }
        }
        else { // PlotOrientation.HORIZONTAL
            double y0 = ctx.dataArea.getMinY();
            double y1 = ctx.dataArea.getMaxY();
            if (range.contains(im.getStartValue())) {
                line.setLine(oc.start2d, y0, oc.start2d, y1);
                ctx.g2.draw(line);
            }
            if (range.contains(im.getEndValue())) {
                line.setLine(oc.end2d, y0, oc.end2d, y1);
                ctx.g2.draw(line);
            }
        }
    }

    /**
     * Draws a marker label for the range axis.
     *
     * @param ctx  the axis draw context.
     * @param markerArea  the marker area.
     * @param marker  the marker.
     * @param offsetType  the label offset type.
     */
    private void drawRangeMarkerLabel(AxisDrawContext ctx,
            Rectangle2D markerArea, Marker marker,
            LengthAdjustmentType offsetType) {
        String label = marker.getLabel();
        RectangleAnchor anchor = marker.getLabelAnchor();
        if (label != null) {
            Font labelFont = marker.getLabelFont();
            ctx.g2.setFont(labelFont);
            ctx.g2.setPaint(marker.getLabelPaint());
            Point2D coordinates = calculateRangeMarkerTextAnchorPoint(
                    new MarkerAnchorBase(ctx.g2, ctx.plot.getOrientation(),
                            ctx.dataArea, markerArea),
                    new MarkerAnchorOffset(marker.getLabelOffset(), offsetType,
                            anchor));
            TextUtilities.drawAlignedString(label, ctx.g2,
                    (float) coordinates.getX(), (float) coordinates.getY(),
                    marker.getLabelTextAnchor());
        }
    }

    /**
     * Calculates the (x, y) coordinates for drawing a range marker label.
     *
     * @param base  the base anchor data.
     * @param offset  the offset anchor data.
     *
     * @return The coordinates for drawing the marker label.
     */
    private Point2D calculateRangeMarkerTextAnchorPoint(MarkerAnchorBase base,
            MarkerAnchorOffset offset) {
        Rectangle2D anchorRect = null;
        if (base.orientation == PlotOrientation.HORIZONTAL) {
            anchorRect = offset.markerOffset.createAdjustedRectangle(
                    base.markerArea, offset.labelOffsetType,
                    LengthAdjustmentType.CONTRACT);
        }
        else if (base.orientation == PlotOrientation.VERTICAL) {
            anchorRect = offset.markerOffset.createAdjustedRectangle(
                    base.markerArea, LengthAdjustmentType.CONTRACT,
                    offset.labelOffsetType);
        }
        return RectangleAnchor.coordinates(anchorRect, offset.anchor);
    }

    /**
     * Returns a clone of the renderer.
     *
     * @return A clone.
     *
     * @throws CloneNotSupportedException if the renderer does not support
     *         cloning.
     */
    @Override
    protected Object clone() throws CloneNotSupportedException {
        AbstractXYItemRenderer clone = (AbstractXYItemRenderer) super.clone();
        // 'plot' : just retain reference, not a deep copy

        if (this.itemLabelGenerator != null
                && this.itemLabelGenerator instanceof PublicCloneable) {
            PublicCloneable pc = (PublicCloneable) this.itemLabelGenerator;
            clone.itemLabelGenerator = (XYItemLabelGenerator) pc.clone();
        }
        clone.itemLabelGeneratorMap = CloneUtils.cloneMapValues(
                this.itemLabelGeneratorMap);
        if (this.baseItemLabelGenerator != null
                && this.baseItemLabelGenerator instanceof PublicCloneable) {
            PublicCloneable pc = (PublicCloneable) this.baseItemLabelGenerator;
            clone.baseItemLabelGenerator = (XYItemLabelGenerator) pc.clone();
        }

        if (this.toolTipGenerator != null
                && this.toolTipGenerator instanceof PublicCloneable) {
            PublicCloneable pc = (PublicCloneable) this.toolTipGenerator;
            clone.toolTipGenerator = (XYToolTipGenerator) pc.clone();
        }
        clone.toolTipGeneratorMap = CloneUtils.cloneMapValues(
                this.toolTipGeneratorMap);
        if (this.baseToolTipGenerator != null
                && this.baseToolTipGenerator instanceof PublicCloneable) {
            PublicCloneable pc = (PublicCloneable) this.baseToolTipGenerator;
            clone.baseToolTipGenerator = (XYToolTipGenerator) pc.clone();
        }

        if (this.legendItemLabelGenerator instanceof PublicCloneable) {
            clone.legendItemLabelGenerator = (XYSeriesLabelGenerator)
                    ObjectUtilities.clone(this.legendItemLabelGenerator);
        }
        if (this.legendItemToolTipGenerator instanceof PublicCloneable) {
            clone.legendItemToolTipGenerator = (XYSeriesLabelGenerator)
                    ObjectUtilities.clone(this.legendItemToolTipGenerator);
        }
        if (this.legendItemURLGenerator instanceof PublicCloneable) {
            clone.legendItemURLGenerator = (XYSeriesLabelGenerator)
                    ObjectUtilities.clone(this.legendItemURLGenerator);
        }

        clone.foregroundAnnotations = (List) ObjectUtilities.deepClone(
                this.foregroundAnnotations);
        clone.backgroundAnnotations = (List) ObjectUtilities.deepClone(
                this.backgroundAnnotations);

        return clone;
    }

    /**
     * Tests this renderer for equality with another object.
     *
     * @param obj  the object (<code>null</code> permitted).
     *
     * @return <code>true</code> or <code>false</code>.
     */
    @Override
    public boolean equals(Object obj) {
        if (obj == this) {
            return true;
        }
        if (!(obj instanceof AbstractXYItemRenderer)) {
            return false;
        }
        AbstractXYItemRenderer that = (AbstractXYItemRenderer) obj;
        if (!ObjectUtilities.equal(this.itemLabelGenerator,
                that.itemLabelGenerator)) {
            return false;
        }
        if (!this.itemLabelGeneratorMap.equals(that.itemLabelGeneratorMap)) {
            return false;
        }
        if (!ObjectUtilities.equal(this.baseItemLabelGenerator,
                that.baseItemLabelGenerator)) {
            return false;
        }
        if (!ObjectUtilities.equal(this.toolTipGenerator,
                that.toolTipGenerator)) {
            return false;
        }
        if (!this.toolTipGeneratorMap.equals(that.toolTipGeneratorMap)) {
            return false;
        }
        if (!ObjectUtilities.equal(this.baseToolTipGenerator,
                that.baseToolTipGenerator)) {
            return false;
        }
        if (!ObjectUtilities.equal(this.urlGenerator, that.urlGenerator)) {
            return false;
        }
        if (!this.foregroundAnnotations.equals(that.foregroundAnnotations)) {
            return false;
        }
        if (!this.backgroundAnnotations.equals(that.backgroundAnnotations)) {
            return false;
        }
        if (!ObjectUtilities.equal(this.legendItemLabelGenerator,
                that.legendItemLabelGenerator)) {
            return false;
        }
        if (!ObjectUtilities.equal(this.legendItemToolTipGenerator,
                that.legendItemToolTipGenerator)) {
            return false;
        }
        if (!ObjectUtilities.equal(this.legendItemURLGenerator,
                that.legendItemURLGenerator)) {
            return false;
        }
        return super.equals(obj);
    }

