            throws CloneNotSupportedException {
        if (source.domainAxis != null) {
            copy.domainAxis = (ValueAxis) source.domainAxis.clone();
            copy.domainAxis.setPlot(copy);
            copy.domainAxis.addChangeListener(copy);
        }
        if (source.rangeAxis != null) {
