private void updateRowHeightsForColumnStart(ContourRenderState state, ValueAxis verticalAxis, double[] y, int k, Rectangle2D dataArea) {
    double transY = verticalAxis.valueToJava2D(y[k], dataArea, RectangleEdge.LEFT);
    state.transDYm1 = Math.abs(0.5 * (transY - transY)); // zero
    state.transDYp1 = Math.abs(0.5 * (transY - verticalAxis.valueToJava2D(y[k + 1], dataArea, RectangleEdge.LEFT)));
}

private void updateRowHeightsForEndOfColumn(ContourRenderState state, ValueAxis verticalAxis, double[] y, int k, Rectangle2D dataArea) {
    double transY = verticalAxis.valueToJava2D(y[k], dataArea, RectangleEdge.LEFT);
    double transYm1 = verticalAxis.valueToJava2D(y[k - 1], dataArea, RectangleEdge.LEFT);
    state.transDYm1 = Math.abs(0.5 * (transY - transYm1));
    state.transDYp1 = Math.abs(0.5 * (transY - transY)); // zero
}

private void updateRowHeightsForMiddleRow(ContourRenderState state, ValueAxis verticalAxis, double[] y, int k, Rectangle2D dataArea) {
    double transY = verticalAxis.valueToJava2D(y[k], dataArea, RectangleEdge.LEFT);
    state.transDYm1 = state.transDYp1;
    state.transDYp1 = Math.abs(0.5 * (transY - verticalAxis.valueToJava2D(y[k + 1], dataArea, RectangleEdge.LEFT));
}

private Rectangle2D.Double createRowRectangle(ContourRenderState state, ValueAxis verticalAxis, double yValue, Rectangle2D dataArea, boolean vertInverted) {
    double transY = verticalAxis.valueToJava2D(yValue, dataArea, RectangleEdge.LEFT);
    if (vertInverted) {
        transY -= state.transDYm1;
    } else {
        transY -= state.transDYp1;
    }
    double transDY = state.transDYm1 + state.transDYp1;
    return new Rectangle2D.Double(state.transX, transY, state.transDX, transDY);
}

