private void addPointEntity(EntityCollection entities, RectangularShape rect, ContourDataset data, int index) {
    if (entities != null) {
        String tip = null;
        if (getToolTipGenerator() != null) {
            tip = this.toolTipGenerator.generateToolTip(data, index);
        }
        String url = null;
        ContourEntity entity = new ContourEntity(
                (RectangularShape) rect.clone(), tip, url);
        entity.setIndex(index);
        entities.add(entity);
    }
}

