```
@Override
public Object clone() throws CloneNotSupportedException {
    return copy(this);
}

/**
 * Creates a deep copy of the given plot.
 *
 * @param original  the plot to copy (<code>null</code> not permitted).
 *
 * @return A deep copy.
 */
public static ContourPlot copy(ContourPlot original) {
    if (original == null) {
        throw new IllegalArgumentException("Null 'original' argument.");
    }
    ContourPlot clone = original.createPlotClone();
    clone.deepCopyStateFrom(original);
    return clone;
}

/**
 * Creates a shallow copy of the plot state inherited from {@link Plot}.
 *
 * @return A shallow copy.
 */
private ContourPlot createPlotClone() {
    try {
        return (ContourPlot) super.clone();
    } catch (CloneNotSupportedException e) {
        throw new RuntimeException(e);
    }
}

/**
 * Deep-copies the ContourPlot-specific state from the source into this plot.
 *
 * @param source  the source plot.
 */
private void deepCopyStateFrom(ContourPlot source) {
    if (source.domainAxis != null) {
        this.domainAxis = (ValueAxis) source.domainAxis.clone();
        this.domainAxis.setPlot(this);
        this.domainAxis.addChangeListener(this);
    }
    if (source.rangeAxis != null) {
        this.rangeAxis = (ValueAxis) source.rangeAxis.clone();
        this.rangeAxis.setPlot(this);
        this.rangeAxis.addChangeListener(this);
    }
    if (this.dataset != null) {
        this.dataset.addChangeListener(this);
    }
    if (source.colorBar != null) {
        this.colorBar = (ColorBar) source.colorBar.clone();
    }
    this.domainMarkers = (List) ObjectUtilities.deepClone(source.domainMarkers);
    this.rangeMarkers = (List) ObjectUtilities.deepClone(source.rangeMarkers);
    this.annotations = (List) ObjectUtilities.deepClone(source.annotations);
    if (source.clipPath != null) {
        this.clipPath = (ClipPath) source.clipPath.clone();
    }
}
```
