 *
 * @param state  the state to update.
 * @param x  the x-values.
 * @param y  the y-values.
 * @param k  the data index.
 * @param i  the column index.
 * @param iMax  the maximum column index.
 * @param indexX  the column start indices.
 * @param horizontalAxis  the horizontal axis.
 * @param dataArea  the data area.
 * @param horizInverted  a flag indicating whether the horizontal axis is inverted.
 *
 * @return <code>false</code> if there is no following row and rendering should skip this point.
 */
private boolean updateColumnState(ContourItemState state, double[] x, double[] y,
                                  int k, int i, int iMax, int[] indexX,
                                  ValueAxis horizontalAxis,
                                  Rectangle2D dataArea,
                                  boolean horizInverted) {
