private ColumnGeometry calculateColumnGeometry(ValueAxis horizontalAxis, Rectangle2D dataArea, double[] x, int[] indexX, int i, int k, boolean horizInverted, double previousTransDXp1) {
    double transX;
    double transDXm1;
    double transDXp1;
    int iMax = indexX[indexX.length - 1];
    if (i == 0) {
        transX = horizontalAxis.valueToJava2D(x[k], dataArea, RectangleEdge.BOTTOM);
        double transXm1 = transX;
        double transXp1 = horizontalAxis.valueToJava2D(x[indexX[i + 1]], dataArea, RectangleEdge.BOTTOM);
        transDXm1 = Math.abs(0.5 * (transX - transXm1));
        transDXp1 = Math.abs(0.5 * (transX - transXp1));
    } else if (i == iMax) {
        transX = horizontalAxis.valueToJava2D(x[k], dataArea, RectangleEdge.BOTTOM);
        double transXm1 = horizontalAxis.valueToJava2D(x[indexX[i - 1]], dataArea, RectangleEdge.BOTTOM);
        double transXp1 = transX;
        transDXm1 = Math.abs(0.5 * (transX - transXm1));
        transDXp1 = Math.abs(0.5 * (transX - transXp1));
    } else {
        transX = horizontalAxis.valueToJava2D(x[k], dataArea, RectangleEdge.BOTTOM);
        double transXp1 = horizontalAxis.valueToJava2D(x[indexX[i + 1]], dataArea, RectangleEdge.BOTTOM);
        transDXm1 = previousTransDXp1;
        transDXp1 = Math.abs(0.5 * (transX - transXp1));
    }
    if (horizInverted) {
        transX -= transDXp1;
    } else {
        transX -= transDXm1;
    }
    double transDX = transDXm1 + transDXp1;
    return new ColumnGeometry(transX, transDX, transDXp1);
}

