public void contourRenderer(Graphics2D g2, Rectangle2D dataArea, PlotRenderingInfo info, ContourPlot plot, ValueAxis horizontalAxis, ValueAxis verticalAxis, ColorBar colorBar, ContourDataset data, CrosshairState crosshairState) {

    Object antiAlias = g2.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
    g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
            RenderingHints.VALUE_ANTIALIAS_OFF);

    double[] x = extractXValues(data);
    double[] y = extractYValues(data);
    Number[] zNumber = data.getZValues();
    int[] xIndex = data.indexX();
    int[] indexX = data.getXIndices();

    boolean vertInverted = ((NumberAxis) verticalAxis).isInverted();
    boolean horizInverted = isHorizontalAxisInverted(horizontalAxis);

    ColumnGeometry columnGeometry = null;
    RowGeometry rowGeometry = null;
    double previousColumnTransDXp1 = 0.0;

    for (int k = 0; k < x.length; k++) {
        int i = xIndex[k];
        if (indexX[i] == k) { // new column
            columnGeometry = calculateColumnGeometry(horizontalAxis, dataArea,
                    x, indexX, i, k, horizInverted, previousColumnTransDXp1);
            previousColumnTransDXp1 = columnGeometry.transDXp1;
            if (k + 1 == y.length) {
                continue;
            }
            rowGeometry = calculateRowGeometry(verticalAxis, dataArea, y, k,
                    vertInverted, true, false, 0.0);
        } else if ((i < indexX.length - 1
                && indexX[i + 1] - 1 == k) || k == x.length - 1) {
            rowGeometry = calculateRowGeometry(verticalAxis, dataArea, y, k,
                    vertInverted, false, true,
                    rowGeometry != null ? rowGeometry.transDYp1 : 0.0);
        } else {
            rowGeometry = calculateRowGeometry(verticalAxis, dataArea, y, k,
                    vertInverted, false, false,
                    rowGeometry != null ? rowGeometry.transDYp1 : 0.0);
        }

        drawContourCell(g2, dataArea, info, plot, colorBar, data,
                crosshairState, x, y, zNumber, k, columnGeometry,
                rowGeometry);
    }

    g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, antiAlias);
}

