private void drawValueMarkerLine(Graphics2D g2, ValueAxis axis,
                                 Marker marker, Rectangle2D dataArea,
                                 RectangleEdge edge, boolean horizontal) {
    if (!(marker instanceof ValueMarker)) {
        return;
    }
    ValueMarker vm = (ValueMarker) marker;
    double value = vm.getValue();
    Range range = axis.getRange();
    if (!range.contains(value)) {
        return;
    }

    double coordinate = axis.valueToJava2D(value, dataArea, edge);
    Line2D line;
    if (horizontal) {
        line = new Line2D.Double(dataArea.getMinX(), coordinate,
                dataArea.getMaxX(), coordinate);
    } else {
        line = new Line2D.Double(coordinate, dataArea.getMinY(),
                coordinate, dataArea.getMaxY());
    }

    Paint paint = marker.getOutlinePaint();
    Stroke stroke = marker.getOutlineStroke();
    g2.setPaint(paint != null ? paint : Plot.DEFAULT_OUTLINE_PAINT);
    g2.setStroke(stroke != null ? stroke : Plot.DEFAULT_OUTLINE_STROKE);
    g2.draw(line);
}

