    /**
     * Draws the plot on a Java 2D graphics device (such as the screen or a
     * printer).
     * <P>
     * The optional <code>info</code> argument collects information about the
     * rendering of the plot (dimensions, tooltip information etc).  Just pass
     * in <code>null</code> if you do not need this information.
     *
     * @param g2  the graphics device.
     * @param area  the area within which the plot (including axis labels)
     *              should be drawn.
     * @param anchor  the anchor point (<code>null</code> permitted).
     * @param parentState  the state from the parent plot, if there is one.
     * @param info  collects chart drawing information (<code>null</code>
     *              permitted).
     */
    @Override
    public void draw(Graphics2D g2, Rectangle2D area, Point2D anchor,
                     PlotState parentState, PlotRenderingInfo info) {
        drawImpl(new DrawContext(g2, area, anchor, parentState, info));
    }

    /**
     * Performs the actual drawing using a structured draw context.
     *
     * @param ctx  the draw context.
     */
    private void drawImpl(DrawContext ctx) {
        Rectangle2D area = ctx.area;
        if (isAreaTooSmall(area)) {
            return;
        }

        if (ctx.info != null) {
            ctx.info.setPlotArea(area);
        }

        RectangleInsets insets = getInsets();
        insets.trim(area);

        AxisSpace space = new AxisSpace();
        space = this.domainAxis.reserveSpace(ctx.g2, this, area,
                RectangleEdge.BOTTOM, space);
        space = this.rangeAxis.reserveSpace(ctx.g2, this, area,
                RectangleEdge.LEFT, space);

        Rectangle2D estimatedDataArea = space.shrink(area, null);

        AxisSpace space2 = new AxisSpace();
        space2 = this.colorBar.reserveSpace(ctx.g2, this, area,
                estimatedDataArea, this.colorBarLocation, space2);
        Rectangle2D adjustedPlotArea = space2.shrink(area, null);

        Rectangle2D dataArea = space.shrink(adjustedPlotArea, null);

        Rectangle2D colorBarArea = space2.reserved(area, this.colorBarLocation);

        if (getDataAreaRatio() != 0.0) {
            adjustDataAreaForRatio(dataArea);
        }

        if (ctx.info != null) {
            ctx.info.setDataArea(dataArea);
        }

        CrosshairState crosshairState = new CrosshairState();
        crosshairState.setCrosshairDistance(Double.POSITIVE_INFINITY);

        drawBackground(ctx.g2, dataArea);

        drawAxes(new AxisDrawContext(ctx.g2, adjustedPlotArea, dataArea,
                colorBarArea, ctx.info));

        Shape originalClip = ctx.g2.getClip();
        Composite originalComposite = ctx.g2.getComposite();

        ctx.g2.clip(dataArea);
        ctx.g2.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER,
                getForegroundAlpha()));
        render(ctx.g2, dataArea, ctx.info, crosshairState);

        drawDomainMarkers(ctx.g2, dataArea);
        drawRangeMarkers(ctx.g2, dataArea);

// TO DO:  these annotations only work with XYPlot, see if it is possible to
// make ContourPlot a subclass of XYPlot (DG);

//        // draw the annotations...
//        if (this.annotations != null) {
//            Iterator iterator = this.annotations.iterator();
//            while (iterator.hasNext()) {
//                Annotation annotation = (Annotation) iterator.next();
//                if (annotation instanceof XYAnnotation) {
//                    XYAnnotation xya = (XYAnnotation) annotation;
//                    // get the annotation to draw itself...
//                    xya.draw(g2, this, dataArea, getDomainAxis(),
//                             getRangeAxis());
//                }
//            }
//        }

        ctx.g2.setClip(originalClip);
        ctx.g2.setComposite(originalComposite);
        drawOutline(ctx.g2, dataArea);
    }

    /**
     * Returns true if the supplied area is too small to draw.
     *
     * @param area  the area to check.
     *
     * @return <code>true</code> if the area is too small.
     */
    private boolean isAreaTooSmall(Rectangle2D area) {
        return area.getWidth() <= MINIMUM_WIDTH_TO_DRAW
                || area.getHeight() <= MINIMUM_HEIGHT_TO_DRAW;
    }

    /**
     * Adjusts the data area to match the configured data area ratio.
     *
     * @param dataArea  the data area to adjust (modified in place).
     */
    private void adjustDataAreaForRatio(Rectangle2D dataArea) {
        double ratio = getDataAreaRatio();
        Rectangle2D tmpDataArea = (Rectangle2D) dataArea.clone();
        double h = tmpDataArea.getHeight();
        double w = tmpDataArea.getWidth();

        if (ratio > 0) {
            if (w * ratio <= h) {
                h = ratio * w;
            } else {
                w = h / ratio;
            }
        } else {
            ratio *= -1.0;
            double xLength = getDomainAxis().getRange().getLength();
            double yLength = getRangeAxis().getRange().getLength();
            double unitRatio = yLength / xLength;

            ratio = unitRatio * ratio;

            if (w * ratio <= h) {
                h = ratio * w;
            } else {
                w = h / ratio;
            }
        }

        dataArea.setRect(tmpDataArea.getX() + tmpDataArea.getWidth() / 2.0
                - w / 2.0, tmpDataArea.getY(), w, h);
    }

    /**
     * Draws the plot axes.
     *
     * @param ctx  the axis draw context.
     */
    private void drawAxes(AxisDrawContext ctx) {
        double cursor = ctx.dataArea.getMaxY();
        if (this.domainAxis != null) {
            this.domainAxis.draw(ctx.g2, cursor, ctx.adjustedPlotArea,
                    ctx.dataArea, RectangleEdge.BOTTOM, ctx.info);
        }

        if (this.rangeAxis != null) {
            cursor = ctx.dataArea.getMinX();
            this.rangeAxis.draw(ctx.g2, cursor, ctx.adjustedPlotArea,
                    ctx.dataArea, RectangleEdge.LEFT, ctx.info);
        }

        if (this.colorBar != null) {
            cursor = 0.0;
            this.colorBar.draw(ctx.g2, cursor, ctx.adjustedPlotArea,
                    ctx.dataArea, ctx.colorBarArea, this.colorBarLocation);
        }
    }

    /**
     * Draws all domain markers.
     *
     * @param g2  the graphics device.
     * @param dataArea  the data area.
     */
    private void drawDomainMarkers(Graphics2D g2, Rectangle2D dataArea) {
        if (this.domainMarkers != null) {
            Iterator iterator = this.domainMarkers.iterator();
            while (iterator.hasNext()) {
                Marker marker = (Marker) iterator.next();
                drawDomainMarker(g2, this, getDomainAxis(), marker, dataArea);
            }
        }
    }

    /**
     * Draws all range markers.
     *
     * @param g2  the graphics device.
     * @param dataArea  the data area.
     */
    private void drawRangeMarkers(Graphics2D g2, Rectangle2D dataArea) {
        if (this.rangeMarkers != null) {
            Iterator iterator = this.rangeMarkers.iterator();
            while (iterator.hasNext()) {
                Marker marker = (Marker) iterator.next();
                drawRangeMarker(g2, this, getRangeAxis(), marker, dataArea);
            }
        }
    }

    /**
     * Draws a representation of the data within the dataArea region, using the
     * current renderer.
     * <P>
     * The <code>info</code> and <code>crosshairState</code> arguments may be
     * <code>null</code>.
     *
     * @param g2  the graphics device.
     * @param dataArea  the region in which the data is to be drawn.
     * @param info  an optional object for collection dimension information.
     * @param crosshairState  an optional object for collecting crosshair info.
     */
    public void render(Graphics2D g2, Rectangle2D dataArea,
                       PlotRenderingInfo info, CrosshairState crosshairState) {
        renderImpl(new RenderContext(g2, dataArea, info, crosshairState));
    }

    /**
     * Renders the plot using the supplied render context.
     *
     * @param rc  the render context.
     */
    private void renderImpl(RenderContext rc) {
        ContourDataset data = getDataset();
        if (data != null) {
            renderData(rc, data);
            drawCrosshairs(rc);
        } else if (this.clipPath != null) {
            getClipPath().draw(rc.g2, rc.dataArea, this.domainAxis,
                    this.rangeAxis);
        }
    }

    /**
     * Renders the dataset (clip path and contour or point renderer).
     *
     * @param rc  the render context.
     * @param data  the dataset.
     */
    private void renderData(RenderContext rc, ContourDataset data) {
        ColorBar zAxis = getColorBar();

        if (this.clipPath != null) {
            GeneralPath clipper = getClipPath().draw(rc.g2, rc.dataArea,
                    this.domainAxis, this.rangeAxis);
            if (this.clipPath.isClip()) {
                rc.g2.clip(clipper);
            }
        }

        ContourDataContext dataContext = new ContourDataContext(this,
                this.domainAxis, this.rangeAxis, zAxis, data);
        if (this.renderAsPoints) {
            pointRendererImpl(rc, dataContext);
        } else {
            contourRendererImpl(rc, dataContext);
        }
    }

    /**
     * Draws the crosshairs after rendering the data.
     *
     * @param rc  the render context.
     */
    private void drawCrosshairs(RenderContext rc) {
        setDomainCrosshairValue(rc.crosshairState.getCrosshairX(), false);
        if (isDomainCrosshairVisible()) {
            drawVerticalLine(rc.g2, rc.dataArea,
                    getDomainCrosshairValue(),
                    getDomainCrosshairStroke(),
                    getDomainCrosshairPaint());
        }

        setRangeCrosshairValue(rc.crosshairState.getCrosshairY(), false);
        if (isRangeCrosshairVisible()) {
            drawHorizontalLine(rc.g2, rc.dataArea,
                    getRangeCrosshairValue(),
                    getRangeCrosshairStroke(),
                    getRangeCrosshairPaint());
        }
    }

