    /**
     * Renders the contour data using structured context objects.
     *
     * @param rc  the render context.
     * @param dc  the contour data context.
     */
    private void contourRendererImpl(RenderContext rc, ContourDataContext dc) {
        EntityCollection entities = null;
        if (rc.info != null) {
            entities = rc.info.getOwner().getEntityCollection();
        }

        Rectangle2D.Double rect = new Rectangle2D.Double();

        Object antiAlias = rc.g2.getRenderingHint(RenderingHints.KEY_ANTIALIASING);
        rc.g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING,
                RenderingHints.VALUE_ANTIALIAS_OFF);

        Number[] xNumber = dc.data.getXValues();
        Number[] yNumber = dc.data.getYValues();
        Number[] zNumber = dc.data.getZValues();

        double[] x = new double[xNumber.length];
        double[] y = new double[yNumber.length];

        for (int i = 0; i < x.length; i++) {
            x[i] = xNumber[i].doubleValue();
            y[i] = yNumber[i].doubleValue();
        }

        int[] xIndex = dc.data.indexX();
        int[] indexX = dc.data.getXIndices();
        boolean vertInverted = ((NumberAxis) dc.verticalAxis).isInverted();
        boolean horizInverted = false;
        if (dc.horizontalAxis instanceof NumberAxis) {
            horizInverted = ((NumberAxis) dc.horizontalAxis).isInverted();
        }

        GeometryContext geometryContext = new GeometryContext(x, y, indexX,
                xIndex[xIndex.length - 1], x.length, rc.dataArea,
                dc.horizontalAxis, dc.verticalAxis, horizInverted,
                vertInverted);

        CellState state = new CellState();

        for (int k = 0; k < x.length; k++) {
            int i = xIndex[k];

            updateHorizontalGeometry(state, k, i, geometryContext);

            if (isLastRowInNewColumn(k, i, geometryContext)) {
                continue;
            }

            updateVerticalGeometry(state, k, i, geometryContext);

            rect.setRect(state.transX, state.transY, state.transDX,
                    state.transDY);

            fillCell(rc.g2, rect, zNumber[k]);

            addContourEntity(entities, rect, dc.data, k);

            updateCrosshairs(rc.crosshairState, new CrosshairPointContext(
                    x[k], y[k], state.transX, state.transY));
        }

        rc.g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, antiAlias);
    }

    /**
     * Updates the horizontal geometry for the current cell.
     *
     * @param state  the current cell state.
     * @param k  the data index.
     * @param i  the column index.
     * @param context  the geometry context.
     */
    private void updateHorizontalGeometry(CellState state, int k, int i,
                                          GeometryContext context) {
        if (context.indexX[i] != k) {
            return;
        }

        double transX = context.horizontalAxis.valueToJava2D(context.x[k],
                context.dataArea, RectangleEdge.BOTTOM);
        double transDXm1;
        double transDXp1;

        if (i == 0) {
            double transXp1 = context.horizontalAxis.valueToJava2D(
                    context.x[context.indexX[i + 1]], context.dataArea,
                    RectangleEdge.BOTTOM);
            transDXm1 = Math.abs(0.5 * (transX - transX));
            transDXp1 = Math.abs(0.5 * (transX - transXp1));
        } else if (i == context.iMax) {
            double transXm1 = context.horizontalAxis.valueToJava2D(
                    context.x[context.indexX[i - 1]], context.dataArea,
                    RectangleEdge.BOTTOM);
            transDXm1 = Math.abs(0.5 * (transX - transXm1));
            transDXp1 = Math.abs(0.5 * (transX - transX));
        } else {
            double transXp1 = context.horizontalAxis.valueToJava2D(
                    context.x[context.indexX[i + 1]], context.dataArea,
                    RectangleEdge.BOTTOM);
            transDXm1 = state.prevTransDXp1;
            transDXp1 = Math.abs(0.5 * (transX - transXp1));
        }

        if (context.horizInverted) {
            transX -= transDXp1;
        } else {
            transX -= transDXm1;
        }

        state.transX = transX;
        state.transDX = transDXm1 + transDXp1;
        state.prevTransDXp1 = transDXp1;
    }

    /**
     * Returns true if this is the last row of a new column.
     *
     * @param k  the data index.
     * @param i  the column index.
     * @param context  the geometry context.
     *
     * @return <code>true</code> if this is the last row of a new column.
     */
    private boolean isLastRowInNewColumn(int k, int i,
                                         GeometryContext context) {
        return context.indexX[i] == k && k + 1 == context.y.length;
    }

    /**
     * Updates the vertical geometry for the current cell.
     *
     * @param state  the current cell state.
     * @param k  the data index.
     * @param i  the column index.
     * @param context  the geometry context.
     */
    private void updateVerticalGeometry(CellState state, int k, int i,
                                        GeometryContext context) {
        double transY;
        double transDYm1;
        double transDYp1;

        if (context.indexX[i] == k) {
            transY = context.verticalAxis.valueToJava2D(context.y[k],
                    context.dataArea, RectangleEdge.LEFT);
            transDYm1 = Math.abs(0.5 * (transY - transY));
            double transYp1 = context.verticalAxis.valueToJava2D(
                    context.y[k + 1], context.dataArea, RectangleEdge.LEFT);
            transDYp1 = Math.abs(0.5 * (transY - transYp1));
        } else if ((i < context.indexX.length - 1
                && context.indexX[i + 1] - 1 == k)
                || k == context.xLength - 1) {
            transY = context.verticalAxis.valueToJava2D(context.y[k],
                    context.dataArea, RectangleEdge.LEFT);
            double transYm1 = context.verticalAxis.valueToJava2D(
                    context.y[k - 1], context.dataArea, RectangleEdge.LEFT);
            transDYm1 = Math.abs(0.5 * (transY - transYm1));
            transDYp1 = Math.abs(0.5 * (transY - transY));
        } else {
            transY = context.verticalAxis.valueToJava2D(context.y[k],
                    context.dataArea, RectangleEdge.LEFT);
            double transYp1 = context.verticalAxis.valueToJava2D(
                    context.y[k + 1], context.dataArea, RectangleEdge.LEFT);
            transDYm1 = state.prevTransDYp1;
            transDYp1 = Math.abs(0.5 * (transY - transYp1));
        }

        if (context.vertInverted) {
            transY -= transDYm1;
        } else {
            transY -= transDYp1;
        }

        state.transY = transY;
        state.transDY = transDYm1 + transDYp1;
        state.prevTransDYp1 = transDYp1;
    }

    /**
     * Fills a single contour cell.
     *
     * @param g2  the graphics device.
     * @param rect  the cell rectangle.
     * @param z  the z-value.
     */
    private void fillCell(Graphics2D g2, Rectangle2D.Double rect, Number z) {
        if (z != null) {
            g2.setPaint(this.colorBar.getPaint(z.doubleValue()));
            g2.fill(rect);
        } else if (this.missingPaint != null) {
            g2.setPaint(this.missingPaint);
            g2.fill(rect);
        }
    }

    /**
     * Adds a contour entity for the current item.
     *
     * @param entities  the entity collection.
     * @param rect  the cell rectangle.
     * @param data  the dataset.
     * @param index  the item index.
     */
    private void addContourEntity(EntityCollection entities,
                                  Rectangle2D.Double rect,
                                  ContourDataset data, int index) {
        if (entities == null) {
            return;
        }
        String tip = "";
        if (getToolTipGenerator() != null) {
            tip = this.toolTipGenerator.generateToolTip(data, index);
        }
        String url = null;
        Rectangle2D.Double entityArea = new Rectangle2D.Double(rect.x, rect.y,
                rect.width, rect.height);
        ContourEntity entity = new ContourEntity(entityArea, tip, url);
        entity.setIndex(index);
        entities.add(entity);
    }

    /**
     * Updates the crosshair state for the current point.
     *
     * @param state  the crosshair state.
     * @param point  the current point context.
     */
    private void updateCrosshairs(CrosshairState state,
                                  CrosshairPointContext point) {
        if (isDomainCrosshairLockedOnData()) {
            if (isRangeCrosshairLockedOnData()) {
                state.updateCrosshairPoint(point.x, point.y, point.transX,
                        point.transY, PlotOrientation.VERTICAL);
            } else {
                state.updateCrosshairX(point.transX);
            }
        } else {
            if (isRangeCrosshairLockedOnData()) {
                state.updateCrosshairY(point.transY);
            }
        }
    }

