        drawVerticalLineImpl(new CrosshairLineContext(g2, dataArea, value,
                stroke, paint));
    }

    /**
     * Draws a vertical crosshair line.
     *
     * @param ctx  the crosshair line context.
     */
    private void drawVerticalLineImpl(CrosshairLineContext ctx) {
        double xx = getDomainAxis().valueToJava2D(ctx.value, ctx.dataArea,
                RectangleEdge.BOTTOM);
        Line2D line = new Line2D.Double(xx, ctx.dataArea.getMinY(), xx,
                ctx.dataArea.getMaxY());
        ctx.g2.setStroke(ctx.stroke);
        ctx.g2.setPaint(ctx.paint);
        ctx.g2.draw(line);
    }

    /**
     * Utility method for drawing a crosshair on the chart (if required).
