     * @param stroke  The stroke to use.
     * @param paint  The paint to use.
     */
    protected void drawHorizontalLine(Graphics2D g2, Rectangle2D dataArea,
                                      double value, Stroke stroke,
                                      Paint paint) {
        drawHorizontalLineImpl(new CrosshairLineContext(g2, dataArea, value,
                stroke, paint));
    }

    /**
     * Draws a horizontal crosshair line.
     *
     * @param ctx  the crosshair line context.
     */
    private void drawHorizontalLineImpl(CrosshairLineContext ctx) {
        double yy = getRangeAxis().valueToJava2D(ctx.value, ctx.dataArea,
                RectangleEdge.LEFT);
        Line2D line = new Line2D.Double(ctx.dataArea.getMinX(), yy,
                ctx.dataArea.getMaxX(), yy);
        ctx.g2.setStroke(ctx.stroke);
        ctx.g2.setPaint(ctx.paint);
        ctx.g2.draw(line);
    }

