            long nextTickTime = tickDate.getTime();
            addMinorTicksAfterMajor(currentTickTime, nextTickTime, minorTickSpaces, result);
        } else {
            tickDate = unit.rollDate(tickDate, this.timeZone);
            hasRolled = true;
        }
    }
    return result;
}
