private int calculateMinorTickSpaces(DateTickUnit unit) {
    int minorTickSpaces = getMinorTickCount();
    if (minorTickSpaces <= 0) {
        minorTickSpaces = unit.getMinorTickCount();
    }
    return minorTickSpaces;
}

private String formatTickLabel(Date tickDate) {
    DateFormat formatter = getDateFormatOverride();
    if (formatter != null) {
        return formatter.format(tickDate);
    }
    return this.tickUnit.dateToString(tickDate);
}

private void addMinorTicksBeforeMajor(long lowestTickTime, long distance,
        int minorTickSpaces, List result) {
    for (int minorTick = 1; minorTick < minorTickSpaces; minorTick++) {
        long minorTickTime = lowestTickTime - distance
                * minorTick / minorTickSpaces;
        if (minorTickTime > 0 && getRange().contains(minorTickTime)
                && (!isHiddenValue(minorTickTime))) {
            result.add(new DateTick(TickType.MINOR,
                    new Date(minorTickTime), "", TextAnchor.TOP_CENTER,
                    TextAnchor.CENTER, 0.0));
        }
    }
}

private void addMinorTicksAfterMajor(long currentTickTime, long nextTickTime,
        int minorTickSpaces, List result) {
    for (int minorTick = 1; minorTick < minorTickSpaces; minorTick++) {
        long minorTickTime = currentTickTime
                + (nextTickTime - currentTickTime)
                * minorTick / minorTickSpaces;
        if (getRange().contains(minorTickTime)
                && (!isHiddenValue(minorTickTime))) {
            result.add(new DateTick(TickType.MINOR,
                    new Date(minorTickTime), "",
                    TextAnchor.TOP_CENTER, TextAnchor.CENTER,
                    0.0));
        }
    }
}

private Tick createHorizontalMajorTick(Date tickDate, RectangleEdge edge) {
    String tickLabel = formatTickLabel(tickDate);
    TextAnchor anchor;
    TextAnchor rotationAnchor;
    double angle = 0.0;
    if (isVerticalTickLabels()) {
        anchor = TextAnchor.CENTER_RIGHT;
        rotationAnchor = TextAnchor.CENTER_RIGHT;
        if (edge == RectangleEdge.TOP) {
            angle = Math.PI / 2.0;
        } else {
            angle = -Math.PI / 2.0;
        }
    } else {
        if (edge == RectangleEdge.TOP) {
            anchor = TextAnchor.BOTTOM_CENTER;
            rotationAnchor = TextAnchor.BOTTOM_CENTER;
        } else {
            anchor = TextAnchor.TOP_CENTER;
            rotationAnchor = TextAnchor.TOP_CENTER;
        }
    }
    return new DateTick(tickDate, tickLabel, anchor,
            rotationAnchor, angle);
}

private Tick createVerticalMajorTick(Date tickDate, RectangleEdge edge) {
    String tickLabel = formatTickLabel(tickDate);
    TextAnchor anchor;
    TextAnchor rotationAnchor;
    double angle = 0.0;
    if (isVerticalTickLabels()) {
        anchor = TextAnchor.BOTTOM_CENTER;
        rotationAnchor = TextAnchor.BOTTOM_CENTER;
        if (edge == RectangleEdge.LEFT) {
            angle = -Math.PI / 2.0;
        } else {
            angle = Math.PI / 2.0;
        }
    } else {
        if (edge == RectangleEdge.LEFT) {
            anchor = TextAnchor.CENTER_RIGHT;
            rotationAnchor = TextAnchor.CENTER_RIGHT;
        } else {
            anchor = TextAnchor.CENTER_LEFT;
            rotationAnchor = TextAnchor.CENTER_LEFT;
        }
    }
    return new DateTick(tickDate, tickLabel, anchor,
            rotationAnchor, angle);
}

