protected Date previousStandardDate(Date date, DateTickUnit unit) {
    Calendar calendar = Calendar.getInstance(this.timeZone, this.locale);
    calendar.setTime(date);
    int count = unit.getCount();
    int current = calendar.get(unit.getCalendarField());
    int value = count * (current / count);

    switch (unit.getUnit()) {
        case DateTickUnit.MILLISECOND:
            return previousStandardDateForMillisecond(date, calendar, value);
        case DateTickUnit.SECOND:
            return previousStandardDateForSecond(date, calendar, value);
        case DateTickUnit.MINUTE:
            return previousStandardDateForMinute(date, calendar, value);
        case DateTickUnit.HOUR:
            return previousStandardDateForHour(date, calendar, value);
        case DateTickUnit.DAY:
            return previousStandardDateForDay(date, calendar, value);
        case DateTickUnit.MONTH:
            return previousStandardDateForMonth(date, calendar, value);
        case DateTickUnit.YEAR:
            return previousStandardDateForYear(date, calendar, value);
        default:
            return null;
    }
}

