    /**
     * Returns <code>true</code> if the axis hides this value, and
     * <code>false</code> otherwise.
     *
     * @param millis  the data value.
     *
     * @return A value.
     */
    public boolean isHiddenValue(long millis) {
        return (!this.timeline.containsDomainValue(new Date(millis)));
    }

    /**
     * Translates the data value to the display coordinates (Java 2D User Space)
     * of the chart.
     *
     * @param value  the date to be plotted.
     * @param area  the rectangle (in Java2D space) where the data is to be
     *              plotted.
     * @param edge  the axis location.
     *
     * @return The coordinate corresponding to the supplied data value.
     */
    @Override
    public double valueToJava2D(double value, Rectangle2D area,
            RectangleEdge edge) {

        value = this.timeline.toTimelineValue((long) value);

        DateRange range = (DateRange) getRange();
        double axisMin = this.timeline.toTimelineValue(range.getLowerMillis());
        double axisMax = this.timeline.toTimelineValue(range.getUpperMillis());
        double result = 0.0;
        if (RectangleEdge.isTopOrBottom(edge)) {
            double minX = area.getX();
            double maxX = area.getMaxX();
            if (isInverted()) {
                result = maxX + ((value - axisMin) / (axisMax - axisMin))
                         * (minX - maxX);
            }
            else {
                result = minX + ((value - axisMin) / (axisMax - axisMin))
                         * (maxX - minX);
            }
        }
        else if (RectangleEdge.isLeftOrRight(edge)) {
            double minY = area.getMinY();
            double maxY = area.getMaxY();
            if (isInverted()) {
                result = minY + (((value - axisMin) / (axisMax - axisMin))
                         * (maxY - minY));
            }
            else {
                result = maxY - (((value - axisMin) / (axisMax - axisMin))
                         * (maxY - minY));
            }
        }
        return result;
    }

    /**
     * Translates a date to Java2D coordinates, based on the range displayed by
     * this axis for the specified data area.
     *
     * @param date  the date.
     * @param area  the rectangle (in Java2D space) where the data is to be
     *              plotted.
     * @param edge  the axis location.
     *
     * @return The coordinate corresponding to the supplied date.
     */
    public double dateToJava2D(Date date, Rectangle2D area, 
            RectangleEdge edge) {
        double value = date.getTime();
        return valueToJava2D(value, area, edge);
    }

    /**
     * Translates a Java2D coordinate into the corresponding data value.  To
     * perform this translation, you need to know the area used for plotting
     * data, and which edge the axis is located on.
     *
     * @param java2DValue  the coordinate in Java2D space.
     * @param area  the rectangle (in Java2D space) where the data is to be
     *              plotted.
     * @param edge  the axis location.
     *
     * @return A data value.
     */
    @Override
    public double java2DToValue(double java2DValue, Rectangle2D area, 
            RectangleEdge edge) {

        DateRange range = (DateRange) getRange();
        double axisMin = this.timeline.toTimelineValue(range.getLowerMillis());
        double axisMax = this.timeline.toTimelineValue(range.getUpperMillis());

        double min = 0.0;
        double max = 0.0;
        if (RectangleEdge.isTopOrBottom(edge)) {
            min = area.getX();
            max = area.getMaxX();
        }
        else if (RectangleEdge.isLeftOrRight(edge)) {
            min = area.getMaxY();
            max = area.getY();
        }

        double result;
        if (isInverted()) {
             result = axisMax - ((java2DValue - min) / (max - min)
                      * (axisMax - axisMin));
        }
        else {
             result = axisMin + ((java2DValue - min) / (max - min)
                      * (axisMax - axisMin));
        }

        return this.timeline.toMillisecond((long) result);
    }

    /**
     * Calculates the value of the lowest visible tick on the axis.
     *
     * @param unit  date unit to use.
     *
     * @return The value of the lowest visible tick on the axis.
     */
    public Date calculateLowestVisibleTickValue(DateTickUnit unit) {
        return nextStandardDate(getMinimumDate(), unit);
    }

    /**
     * Calculates the value of the highest visible tick on the axis.
     *
     * @param unit  date unit to use.
     *
     * @return The value of the highest visible tick on the axis.
     */
    public Date calculateHighestVisibleTickValue(DateTickUnit unit) {
        return previousStandardDate(getMaximumDate(), unit);
    }

    /**
     * Strategy for computing the previous standard date for a particular tick
     * unit.
     */
    private static interface PreviousStandardDateStrategy {

        /**
         * Returns the previous standard date.
         *
         * @param axis  the axis.
         * @param calendar  a calendar positioned at the reference date.
         * @param date  the reference date.
         * @param unit  the tick unit.
         * @param value  the aligned field value.
         *
         * @return The previous standard date.
         */
        Date previousStandardDate(DateAxis axis, Calendar calendar,
                Date date, DateTickUnit unit, int value);
    }

    /**
     * Strategy for millisecond tick units.
     */
    private static class MillisecondPreviousStandardDateStrategy
            implements PreviousStandardDateStrategy {

        @Override
        public Date previousStandardDate(DateAxis axis, Calendar calendar,
                Date date, DateTickUnit unit, int value) {
            int years = calendar.get(Calendar.YEAR);
            int months = calendar.get(Calendar.MONTH);
            int days = calendar.get(Calendar.DATE);
            int hours = calendar.get(Calendar.HOUR_OF_DAY);
            int minutes = calendar.get(Calendar.MINUTE);
            int seconds = calendar.get(Calendar.SECOND);
            calendar.set(years, months, days, hours, minutes, seconds);
            calendar.set(Calendar.MILLISECOND, value);
            Date result = calendar.getTime();
            if (result.getTime() >= date.getTime()) {
                calendar.set(Calendar.MILLISECOND, value - 1);
                result = calendar.getTime();
            }
            return result;
        }
    }

    /**
     * Strategy for second tick units.
     */
    private static class SecondPreviousStandardDateStrategy
            implements PreviousStandardDateStrategy {

        @Override
        public Date previousStandardDate(DateAxis axis, Calendar calendar,
                Date date, DateTickUnit unit, int value) {
            int years = calendar.get(Calendar.YEAR);
            int months = calendar.get(Calendar.MONTH);
            int days = calendar.get(Calendar.DATE);
            int hours = calendar.get(Calendar.HOUR_OF_DAY);
            int minutes = calendar.get(Calendar.MINUTE);
            int milliseconds = axis.getTickMarkPositionValue(0, 500, 999);
            calendar.set(Calendar.MILLISECOND, milliseconds);
            calendar.set(years, months, days, hours, minutes, value);
            Date result = calendar.getTime();
            if (result.getTime() >= date.getTime()) {
                calendar.set(Calendar.SECOND, value - 1);
                result = calendar.getTime();
            }
            return result;
        }
    }

    /**
     * Strategy for minute tick units.
     */
    private static class MinutePreviousStandardDateStrategy
            implements PreviousStandardDateStrategy {

        @Override
        public Date previousStandardDate(DateAxis axis, Calendar calendar,
                Date date, DateTickUnit unit, int value) {
            int years = calendar.get(Calendar.YEAR);
            int months = calendar.get(Calendar.MONTH);
            int days = calendar.get(Calendar.DATE);
            int hours = calendar.get(Calendar.HOUR_OF_DAY);
            int seconds = axis.getTickMarkPositionValue(0, 30, 59);
            calendar.clear(Calendar.MILLISECOND);
            calendar.set(years, months, days, hours, value, seconds);
            Date result = calendar.getTime();
            if (result.getTime() >= date.getTime()) {
                calendar.set(Calendar.MINUTE, value - 1);
                result = calendar.getTime();
            }
            return result;
        }
    }

    /**
     * Strategy for hour tick units.
     */
    private static class HourPreviousStandardDateStrategy
            implements PreviousStandardDateStrategy {

        @Override
        public Date previousStandardDate(DateAxis axis, Calendar calendar,
                Date date, DateTickUnit unit, int value) {
            int years = calendar.get(Calendar.YEAR);
            int months = calendar.get(Calendar.MONTH);
            int days = calendar.get(Calendar.DATE);
            int minutes = axis.getTickMarkPositionValue(0, 30, 59);
            int seconds = axis.getTickMarkPositionValue(0, 0, 59);
            calendar.clear(Calendar.MILLISECOND);
            calendar.set(years, months, days, value, minutes, seconds);
            Date result = calendar.getTime();
            if (result.getTime() >= date.getTime()) {
                calendar.set(Calendar.HOUR_OF_DAY, value - 1);
                result = calendar.getTime();
            }
            return result;
        }
    }

    /**
     * Strategy for day tick units.
     */
    private static class DayPreviousStandardDateStrategy
            implements PreviousStandardDateStrategy {

        @Override
        public Date previousStandardDate(DateAxis axis, Calendar calendar,
                Date date, DateTickUnit unit, int value) {
            int years = calendar.get(Calendar.YEAR);
            int months = calendar.get(Calendar.MONTH);
            int hours = axis.getTickMarkPositionValue(0, 12, 23);
            calendar.clear(Calendar.MILLISECOND);
            calendar.set(years, months, value, hours, 0, 0);
            Date result = calendar.getTime();
            if (result.getTime() >= date.getTime()) {
                calendar.set(Calendar.DATE, value - 1);
                result = calendar.getTime();
            }
            return result;
        }
    }

    /**
     * Strategy for month tick units.
     */
    private static class MonthPreviousStandardDateStrategy
            implements PreviousStandardDateStrategy {

        @Override
        public Date previousStandardDate(DateAxis axis, Calendar calendar,
                Date date, DateTickUnit unit, int value) {
            int years = calendar.get(Calendar.YEAR);
            calendar.clear(Calendar.MILLISECOND);
            calendar.set(years, value, 1, 0, 0, 0);
            Month month = new Month(calendar.getTime(), axis.timeZone,
                    axis.locale);
            Date standardDate = axis.calculateDateForPosition(month,
                    axis.tickMarkPosition);
            long millis = standardDate.getTime();
            if (millis >= date.getTime()) {
                month = (Month) month.previous();
                // need to peg the month in case the time zone isn't the
                // default - see bug 2078057
                month.peg(Calendar.getInstance(axis.timeZone));
                standardDate = axis.calculateDateForPosition(month,
                        axis.tickMarkPosition);
            }
            return standardDate;
        }
    }

    /**
     * Strategy for year tick units.
     */
    private static class YearPreviousStandardDateStrategy
            implements PreviousStandardDateStrategy {

        @Override
        public Date previousStandardDate(DateAxis axis, Calendar calendar,
                Date date, DateTickUnit unit, int value) {
            int months = axis.getTickMarkPositionValue(0, 6, 11);
            int days = axis.getTickMarkPositionValue(1, 1, 31);
            calendar.clear(Calendar.MILLISECOND);
            calendar.set(value, months, days, 0, 0, 0);
            Date result = calendar.getTime();
            if (result.getTime() >= date.getTime()) {
                calendar.set(Calendar.YEAR, value - 1);
                result = calendar.getTime();
            }
            return result;
        }
    }

    /** Lookup table for previous-standard-date strategies. */
    private static final java.util.Map PREVIOUS_STANDARD_DATE_STRATEGIES;
    static {
        java.util.Map map = new java.util.HashMap();
        map.put(new Integer(DateTickUnit.MILLISECOND),
                new MillisecondPreviousStandardDateStrategy());
        map.put(new Integer(DateTickUnit.SECOND),
                new SecondPreviousStandardDateStrategy());
        map.put(new Integer(DateTickUnit.MINUTE),
                new MinutePreviousStandardDateStrategy());
        map.put(new Integer(DateTickUnit.HOUR),
                new HourPreviousStandardDateStrategy());
        map.put(new Integer(DateTickUnit.DAY),
                new DayPreviousStandardDateStrategy());
        map.put(new Integer(DateTickUnit.MONTH),
                new MonthPreviousStandardDateStrategy());
        map.put(new Integer(DateTickUnit.YEAR),
                new YearPreviousStandardDateStrategy());
        PREVIOUS_STANDARD_DATE_STRATEGIES = map;
    }

    /**
     * Returns the value to use for a calendar field according to the current
     * tick mark position.
     *
     * @param startValue  the value for the start position.
     * @param middleValue  the value for the middle position.
     * @param endValue  the value for the end position.
     *
     * @return The appropriate field value.
     */
    private int getTickMarkPositionValue(int startValue, int middleValue,
            int endValue) {
        if (this.tickMarkPosition == DateTickMarkPosition.START) {
            return startValue;
        }
        if (this.tickMarkPosition == DateTickMarkPosition.MIDDLE) {
            return middleValue;
        }
        return endValue;
    }

    /**
     * Returns the previous "standard" date, for a given date and tick unit.
     *
     * @param date  the reference date.
     * @param unit  the tick unit.
     *
     * @return The previous "standard" date.
     */
    protected Date previousStandardDate(Date date, DateTickUnit unit) {

        Calendar calendar = Calendar.getInstance(this.timeZone, this.locale);
        calendar.setTime(date);
        int count = unit.getCount();
        int current = calendar.get(unit.getCalendarField());
        int value = count * (current / count);

        PreviousStandardDateStrategy strategy =
                (PreviousStandardDateStrategy)
                PREVIOUS_STANDARD_DATE_STRATEGIES.get(
                new Integer(unit.getUnit()));
        if (strategy != null) {
            return strategy.previousStandardDate(this, calendar, date,
                    unit, value);
        }
        return null;

    }

    /**
     * Strategy for adjusting a tick date for a particular tick mark position.
     */
    private static interface PositionDateCalculator {

        /**
         * Returns the millisecond value for the supplied period.
         *
         * @param period  the time period.
         *
         * @return The millisecond value.
         */
        long getMillisecond(RegularTimePeriod period);
    }

