    private static final java.util.Map POSITION_DATE_CALCULATORS;
    static {
        java.util.Map map = new java.util.HashMap();
        map.put(DateTickMarkPosition.START, new PositionDateCalculator() {
            @Override
            public long getMillisecond(RegularTimePeriod period) {
                return period.getFirstMillisecond();
            }
        });
        map.put(DateTickMarkPosition.MIDDLE, new PositionDateCalculator() {
            @Override
            public long getMillisecond(RegularTimePeriod period) {
                return period.getMiddleMillisecond();
            }
        });
        map.put(DateTickMarkPosition.END, new PositionDateCalculator() {
            @Override
            public long getMillisecond(RegularTimePeriod period) {
                return period.getLastMillisecond();
            }
        });
        POSITION_DATE_CALCULATORS = map;
    }

    /**
     * Returns a {@link java.util.Date} corresponding to the specified position
     * within a {@link RegularTimePeriod}.
     *
     * @param period  the period.
     * @param position  the position (<code>null</code> not permitted).
     *
     * @return A date.
     */
    private Date calculateDateForPosition(RegularTimePeriod period,
            DateTickMarkPosition position) {
        ParamChecks.nullNotPermitted(period, "period");
        PositionDateCalculator calculator = (PositionDateCalculator)
                POSITION_DATE_CALCULATORS.get(position);
        if (calculator != null) {
            return new Date(calculator.getMillisecond(period));
        }
        return null;

    }

