/**
 * The base class for axes that display dates.  You will find it easier to
 * understand how this axis works if you bear in mind that it really
 * displays/measures integer (or long) data, where the integers are
 * milliseconds since midnight, 1-Jan-1970.  When displaying tick labels, the
 * millisecond values are converted back to dates using a
 * <code>DateFormat</code> instance.
 * <P>
 * You can also create a {@link org.jfree.chart.axis.Timeline} and supply in
 * the constructor to create an axis that only contains certain domain values.
 * For example, this allows you to create a date axis that only contains
 * working days.
 */
public class DateAxis extends ValueAxis implements Cloneable, Serializable {

    /** For serialization. */
    private static final long serialVersionUID = -1013460999649007604L;

    /** The default axis range. */
    public static final DateRange DEFAULT_DATE_RANGE = new DateRange();

    /** The default minimum auto range size. */
    public static final double
            DEFAULT_AUTO_RANGE_MINIMUM_SIZE_IN_MILLISECONDS = 2.0;

    /** 
     * The default date tick unit.
     * 
     * @deprecated As pointed out in bug #977, the SimpleDateFormat in this
     *     object uses Calendar which is not thread safe...so you should 
     *     avoid reusing this instance and create a new instance as required.
     */
    public static final DateTickUnit DEFAULT_DATE_TICK_UNIT
            = new DateTickUnit(DateTickUnitType.DAY, 1, new SimpleDateFormat());

    /** The default anchor date. */
    public static final Date DEFAULT_ANCHOR_DATE = new Date();

    /** The current tick unit. */
    private DateTickUnit tickUnit;

    /** The override date format. */
    private DateFormat dateFormatOverride;

    /**
     * Tick marks can be displayed at the start or the middle of the time
     * period.
     */
    private DateTickMarkPosition tickMarkPosition = DateTickMarkPosition.START;

    /**
     * A timeline that includes all milliseconds (as defined by
     * <code>java.util.Date</code>) in the real time line.
     */
    private static class DefaultTimeline implements Timeline, Serializable {

        /**
         * Converts a millisecond into a timeline value.
         *
         * @param millisecond  the millisecond.
         *
         * @return The timeline value.
         */
        @Override
        public long toTimelineValue(long millisecond) {
            return millisecond;
        }

        /**
         * Converts a date into a timeline value.
         *
         * @param date  the domain value.
         *
         * @return The timeline value.
         */
        @Override
        public long toTimelineValue(Date date) {
            return date.getTime();
        }

        /**
         * Converts a timeline value into a millisecond (as encoded by
         * <code>java.util.Date</code>).
         *
         * @param value  the value.
         *
         * @return The millisecond.
         */
        @Override
        public long toMillisecond(long value) {
            return value;
        }

        /**
         * Returns <code>true</code> if the timeline includes the specified
         * domain value.
         *
         * @param millisecond  the millisecond.
         *
         * @return <code>true</code>.
         */
        @Override
        public boolean containsDomainValue(long millisecond) {
            return true;
        }

        /**
         * Returns <code>true</code> if the timeline includes the specified
         * domain value.
         *
         * @param date  the date.
         *
         * @return <code>true</code>.
         */
        @Override
        public boolean containsDomainValue(Date date) {
            return true;
        }

        /**
         * Returns <code>true</code> if the timeline includes the specified
         * domain value range.
         *
         * @param from  the start value.
         * @param to  the end value.
         *
         * @return <code>true</code>.
         */
        @Override
        public boolean containsDomainRange(long from, long to) {
            return true;
        }

        /**
         * Returns <code>true</code> if the timeline includes the specified
         * domain value range.
         *
         * @param from  the start date.
         * @param to  the end date.
         *
         * @return <code>true</code>.
         */
        @Override
        public boolean containsDomainRange(Date from, Date to) {
            return true;
        }

        /**
         * Tests an object for equality with this instance.
         *
         * @param object  the object.
         *
         * @return A boolean.
         */
        @Override
        public boolean equals(Object object) {
            if (object == null) {
                return false;
            }
            if (object == this) {
                return true;
            }
            if (object instanceof DefaultTimeline) {
                return true;
            }
            return false;
        }
    }

    /** A static default timeline shared by all standard DateAxis */
    private static final Timeline DEFAULT_TIMELINE = new DefaultTimeline();

    /**
     * Strategy for calculating the previous standard date for a given tick
     * unit.
     */
    private interface PreviousStandardDateStrategy {
        /**
         * Returns the previous standard date.
         *
         * @param date  the reference date.
         * @param unit  the tick unit.
         * @param position  the tick mark position.
         * @param timeZone  the time zone.
         * @param locale  the locale.
         *
         * @return The previous standard date.
         */
        Date previousStandardDate(Date date, DateTickUnit unit,
                DateTickMarkPosition position, TimeZone timeZone, Locale locale);
    }

    /**
     * Base strategy for aligning a single calendar field.
     */
    private static abstract class CalendarFieldStrategy
            implements PreviousStandardDateStrategy {

        /** The calendar field to align. */
        private final int calendarField;

        /**
         * Creates a strategy for the specified calendar field.
         *
         * @param calendarField  the calendar field.
         */
        CalendarFieldStrategy(int calendarField) {
            this.calendarField = calendarField;
        }

        @Override
        public Date previousStandardDate(Date date, DateTickUnit unit,
                DateTickMarkPosition position, TimeZone timeZone,
                Locale locale) {
            Calendar calendar = Calendar.getInstance(timeZone, locale);
            calendar.setTime(date);
            int count = unit.getCount();
            int current = calendar.get(this.calendarField);
            int value = count * (current / count);
            setSmallerFields(calendar, position);
            calendar.set(this.calendarField, value);
            Date result = calendar.getTime();
            if (result.getTime() >= date.getTime()) {
                calendar.set(this.calendarField, value - 1);
                result = calendar.getTime();
            }
            return result;
        }

        /**
         * Sets the calendar fields smaller than the aligned field.
         *
         * @param calendar  the calendar.
         * @param position  the tick mark position.
         */
        protected abstract void setSmallerFields(Calendar calendar,
                DateTickMarkPosition position);
    }

    /**
     * Strategy for monthly tick units.
     */
    private static class MonthStrategy implements PreviousStandardDateStrategy {
        @Override
        public Date previousStandardDate(Date date, DateTickUnit unit,
                DateTickMarkPosition position, TimeZone timeZone,
                Locale locale) {
            Calendar calendar = Calendar.getInstance(timeZone, locale);
            calendar.setTime(date);
            int count = unit.getCount();
            int current = calendar.get(Calendar.MONTH);
            int value = count * (current / count);
            calendar.clear(Calendar.MILLISECOND);
            calendar.set(calendar.get(Calendar.YEAR), value, 1, 0, 0, 0);
            Month month = new Month(calendar.getTime(), timeZone, locale);
            Date standardDate = calculateDateForPosition(month, position);
            if (standardDate.getTime() >= date.getTime()) {
                month = (Month) month.previous();
                month.peg(Calendar.getInstance(timeZone));
                standardDate = calculateDateForPosition(month, position);
            }
            return standardDate;
        }
    }

    /**
     * Returns the offset to use for a tick mark position.
     *
     * @param position  the tick mark position.
     * @param startValue  the value for the start position.
     * @param middleValue  the value for the middle position.
     * @param endValue  the value for the end position.
     *
     * @return The offset.
     */
    private static int offsetForPosition(DateTickMarkPosition position,
            int startValue, int middleValue, int endValue) {
        if (position == DateTickMarkPosition.START) {
            return startValue;
        }
        if (position == DateTickMarkPosition.MIDDLE) {
            return middleValue;
        }
        return endValue;
    }

    /** Strategies for previous standard date calculation, indexed by tick unit. */
    private static final PreviousStandardDateStrategy[]
            PREVIOUS_STANDARD_DATE_STRATEGIES
            = new PreviousStandardDateStrategy[7];
    static {
        PREVIOUS_STANDARD_DATE_STRATEGIES[DateTickUnit.MILLISECOND]
                = new CalendarFieldStrategy(Calendar.MILLISECOND) {
            @Override
            protected void setSmallerFields(Calendar calendar,
                    DateTickMarkPosition position) {
                // no smaller fields
            }
        };
        PREVIOUS_STANDARD_DATE_STRATEGIES[DateTickUnit.SECOND]
                = new CalendarFieldStrategy(Calendar.SECOND) {
            @Override
            protected void setSmallerFields(Calendar calendar,
                    DateTickMarkPosition position) {
                calendar.set(Calendar.MILLISECOND,
                        offsetForPosition(position, 0, 500, 999));
            }
        };
        PREVIOUS_STANDARD_DATE_STRATEGIES[DateTickUnit.MINUTE]
                = new CalendarFieldStrategy(Calendar.MINUTE) {
            @Override
            protected void setSmallerFields(Calendar calendar,
                    DateTickMarkPosition position) {
                calendar.clear(Calendar.MILLISECOND);
                calendar.set(Calendar.SECOND,
                        offsetForPosition(position, 0, 30, 59));
            }
        };
        PREVIOUS_STANDARD_DATE_STRATEGIES[DateTickUnit.HOUR]
                = new CalendarFieldStrategy(Calendar.HOUR_OF_DAY) {
            @Override
            protected void setSmallerFields(Calendar calendar,
                    DateTickMarkPosition position) {
                calendar.clear(Calendar.MILLISECOND);
                calendar.set(Calendar.MINUTE,
                        offsetForPosition(position, 0, 30, 59));
                calendar.set(Calendar.SECOND,
                        offsetForPosition(position, 0, 0, 59));
            }
        };
        PREVIOUS_STANDARD_DATE_STRATEGIES[DateTickUnit.DAY]
                = new CalendarFieldStrategy(Calendar.DATE) {
            @Override
            protected void setSmallerFields(Calendar calendar,
                    DateTickMarkPosition position) {
                calendar.clear(Calendar.MILLISECOND);
                calendar.set(Calendar.HOUR_OF_DAY,
                        offsetForPosition(position, 0, 12, 23));
                calendar.set(Calendar.MINUTE, 0);
                calendar.set(Calendar.SECOND, 0);
            }
        };
        PREVIOUS_STANDARD_DATE_STRATEGIES[DateTickUnit.MONTH]
                = new MonthStrategy();
        PREVIOUS_STANDARD_DATE_STRATEGIES[DateTickUnit.YEAR]
                = new CalendarFieldStrategy(Calendar.YEAR) {
            @Override
            protected void setSmallerFields(Calendar calendar,
                    DateTickMarkPosition position) {
                calendar.clear(Calendar.MILLISECOND);
                calendar.set(Calendar.MONTH,
                        offsetForPosition(position, 0, 6, 11));
                calendar.set(Calendar.DATE,
                        offsetForPosition(position, 1, 1, 31));
                calendar.set(Calendar.HOUR_OF_DAY, 0);
                calendar.set(Calendar.MINUTE, 0);
                calendar.set(Calendar.SECOND, 0);
            }
        };
    }

    /**
     * Strategy for correcting a tick date for the tick mark position.
     */
    private interface TickDateCorrector {
        /**
         * Corrects the tick date.
         *
         * @param tickDate  the tick date.
         * @param unit  the tick unit.
         * @param position  the tick mark position.
         * @param timeZone  the time zone.
         * @param locale  the locale.
         *
         * @return The corrected date.
         */
        Date correct(Date tickDate, DateTickUnit unit,
                DateTickMarkPosition position, TimeZone timeZone, Locale locale);
    }

    /** Correctors for tick date positions, indexed by tick unit. */
    private static final TickDateCorrector[] TICK_DATE_CORRECTORS
            = new TickDateCorrector[7];
    static {
        TickDateCorrector identity = new TickDateCorrector() {
            @Override
            public Date correct(Date tickDate, DateTickUnit unit,
                    DateTickMarkPosition position, TimeZone timeZone,
                    Locale locale) {
                return tickDate;
            }
        };
        TICK_DATE_CORRECTORS[DateTickUnit.MILLISECOND] = identity;
        TICK_DATE_CORRECTORS[DateTickUnit.SECOND] = identity;
        TICK_DATE_CORRECTORS[DateTickUnit.MINUTE] = identity;
        TICK_DATE_CORRECTORS[DateTickUnit.HOUR] = identity;
        TICK_DATE_CORRECTORS[DateTickUnit.DAY] = identity;
        TICK_DATE_CORRECTORS[DateTickUnit.MONTH] = new TickDateCorrector() {
            @Override
            public Date correct(Date tickDate, DateTickUnit unit,
                    DateTickMarkPosition position, TimeZone timeZone,
                    Locale locale) {
                return calculateDateForPosition(
                        new Month(tickDate, timeZone, locale), position);
            }
        };
        TICK_DATE_CORRECTORS[DateTickUnit.YEAR] = new TickDateCorrector() {
            @Override
            public Date correct(Date tickDate, DateTickUnit unit,
                    DateTickMarkPosition position, TimeZone timeZone,
                    Locale locale) {
                return calculateDateForPosition(
                        new Year(tickDate, timeZone, locale), position);
            }
        };
    }

    /**
     * Calculates a date for a position within a regular time period.
     */
    private interface DatePositionCalculator {
        /**
         * Calculates the date.
         *
         * @param period  the time period.
         *
         * @return The date.
         */
        Date calculate(RegularTimePeriod period);
    }

    /** Maps tick mark positions to date calculators. */
    private static final java.util.Map<DateTickMarkPosition, DatePositionCalculator>
            DATE_POSITION_CALCULATORS
            = new java.util.HashMap<DateTickMarkPosition, DatePositionCalculator>();
    static {
        DATE_POSITION_CALCULATORS.put(DateTickMarkPosition.START,
                new DatePositionCalculator() {
            @Override
            public Date calculate(RegularTimePeriod period) {
                return new Date(period.getFirstMillisecond());
            }
        });
        DATE_POSITION_CALCULATORS.put(DateTickMarkPosition.MIDDLE,
                new DatePositionCalculator() {
            @Override
            public Date calculate(RegularTimePeriod period) {
                return new Date(period.getMiddleMillisecond());
            }
        });
        DATE_POSITION_CALCULATORS.put(DateTickMarkPosition.END,
                new DatePositionCalculator() {
            @Override
            public Date calculate(RegularTimePeriod period) {
                return new Date(period.getLastMillisecond());
            }
        });
    }

