    /**
     * Strategy for computing the previous standard date for a specific tick
     * unit type.
     */
    private interface PreviousDateStrategy {
        /**
         * Computes the previous standard date.
         *
         * @param axis  the source axis.
         * @param date  the reference date.
         * @param unit  the tick unit.
         * @param calendar  a calendar positioned at the reference date.
         * @param value  the aligned value for the target calendar field.
         *
         * @return The previous standard date.
         */
        Date previousStandardDate(DateAxis axis, Date date, DateTickUnit unit,
                Calendar calendar, int value);
    }

    /**
     * Returns the millisecond value to use for the current tick mark position.
     *
     * @return The millisecond value.
     */
    private int getTickMarkMilliseconds() {
        if (this.tickMarkPosition == DateTickMarkPosition.MIDDLE) {
            return 500;
        }
        if (this.tickMarkPosition == DateTickMarkPosition.END) {
            return 999;
        }
        return 0;
    }

    /**
     * Returns the second value to use for the current tick mark position.
     *
     * @return The second value.
     */
    private int getTickMarkSeconds() {
        if (this.tickMarkPosition == DateTickMarkPosition.MIDDLE) {
            return 30;
        }
        if (this.tickMarkPosition == DateTickMarkPosition.END) {
            return 59;
        }
        return 0;
    }

    /**
     * Returns the minute value to use for the current tick mark position.
     *
     * @return The minute value.
     */
    private int getTickMarkMinutes() {
        if (this.tickMarkPosition == DateTickMarkPosition.MIDDLE) {
            return 30;
        }
        if (this.tickMarkPosition == DateTickMarkPosition.END) {
            return 59;
        }
        return 0;
    }

    /**
     * Returns the hour value to use for the current tick mark position.
     *
     * @return The hour value.
     */
    private int getTickMarkHours() {
        if (this.tickMarkPosition == DateTickMarkPosition.MIDDLE) {
            return 12;
        }
        if (this.tickMarkPosition == DateTickMarkPosition.END) {
            return 23;
        }
        return 0;
    }

    /**
     * Returns the month value to use for the current tick mark position.
     *
     * @return The month value.
     */
    private int getTickMarkMonths() {
        if (this.tickMarkPosition == DateTickMarkPosition.MIDDLE) {
            return 6;
        }
        if (this.tickMarkPosition == DateTickMarkPosition.END) {
            return 11;
        }
        return 0;
