    /**
     * Returns the day-of-month value to use for the current tick mark position
     * when aligning years.
     *
     * @return The day-of-month value.
     */
    private int getTickMarkYearDay() {
        if (this.tickMarkPosition == DateTickMarkPosition.END) {
            return 31;
        }
        return 1;
    }

    /**
     * Strategy for millisecond tick units.
     */
    private static class MillisecondStrategy implements PreviousDateStrategy {
        @Override
        public Date previousStandardDate(DateAxis axis, Date date,
                DateTickUnit unit, Calendar calendar, int value) {
            int years = calendar.get(Calendar.YEAR);
            int months = calendar.get(Calendar.MONTH);
            int days = calendar.get(Calendar.DATE);
            int hours = calendar.get(Calendar.HOUR_OF_DAY);
            int minutes = calendar.get(Calendar.MINUTE);
            int seconds = calendar.get(Calendar.SECOND);
            calendar.set(years, months, days, hours, minutes, seconds);
            calendar.set(Calendar.MILLISECOND, value);
            Date result = calendar.getTime();
            if (result.getTime() >= date.getTime()) {
                calendar.set(Calendar.MILLISECOND, value - 1);
                result = calendar.getTime();
            }
            return result;
        }
    }

    /**
     * Strategy for second tick units.
     */
    private static class SecondStrategy implements PreviousDateStrategy {
        @Override
        public Date previousStandardDate(DateAxis axis, Date date,
                DateTickUnit unit, Calendar calendar, int value) {
            int years = calendar.get(Calendar.YEAR);
            int months = calendar.get(Calendar.MONTH);
            int days = calendar.get(Calendar.DATE);
            int hours = calendar.get(Calendar.HOUR_OF_DAY);
            int minutes = calendar.get(Calendar.MINUTE);
            calendar.set(Calendar.MILLISECOND, axis.getTickMarkMilliseconds());
            calendar.set(years, months, days, hours, minutes, value);
            Date result = calendar.getTime();
            if (result.getTime() >= date.getTime()) {
                calendar.set(Calendar.SECOND, value - 1);
                result = calendar.getTime();
            }
            return result;
        }
    }

    /**
     * Strategy for minute tick units.
     */
    private static class MinuteStrategy implements PreviousDateStrategy {
        @Override
        public Date previousStandardDate(DateAxis axis, Date date,
                DateTickUnit unit, Calendar calendar, int value) {
            int years = calendar.get(Calendar.YEAR);
            int months = calendar.get(Calendar.MONTH);
            int days = calendar.get(Calendar.DATE);
            int hours = calendar.get(Calendar.HOUR_OF_DAY);
            calendar.clear(Calendar.MILLISECOND);
            calendar.set(years, months, days, hours, value,
                    axis.getTickMarkSeconds());
            Date result = calendar.getTime();
            if (result.getTime() >= date.getTime()) {
                calendar.set(Calendar.MINUTE, value - 1);
                result = calendar.getTime();
            }
            return result;
        }
    }

    /**
     * Strategy for hour tick units.
     */
    private static class HourStrategy implements PreviousDateStrategy {
        @Override
        public Date previousStandardDate(DateAxis axis, Date date,
                DateTickUnit unit, Calendar calendar, int value) {
            int years = calendar.get(Calendar.YEAR);
            int months = calendar.get(Calendar.MONTH);
            int days = calendar.get(Calendar.DATE);
            calendar.clear(Calendar.MILLISECOND);
            calendar.set(years, months, days, value,
                    axis.getTickMarkMinutes(), axis.getTickMarkSeconds());
            Date result = calendar.getTime();
            if (result.getTime() >= date.getTime()) {
                calendar.set(Calendar.HOUR_OF_DAY, value - 1);
                result = calendar.getTime();
            }
            return result;
        }
    }

    /**
     * Strategy for day tick units.
     */
    private static class DayStrategy implements PreviousDateStrategy {
        @Override
        public Date previousStandardDate(DateAxis axis, Date date,
                DateTickUnit unit, Calendar calendar, int value) {
            int years = calendar.get(Calendar.YEAR);
            int months = calendar.get(Calendar.MONTH);
            calendar.clear(Calendar.MILLISECOND);
            calendar.set(years, months, value, axis.getTickMarkHours(), 0, 0);
            Date result = calendar.getTime();
            if (result.getTime() >= date.getTime()) {
                calendar.set(Calendar.DATE, value - 1);
                result = calendar.getTime();
            }
            return result;
        }
    }

    /**
     * Strategy for month tick units.
     */
    private static class MonthStrategy implements PreviousDateStrategy {
        @Override
        public Date previousStandardDate(DateAxis axis, Date date,
                DateTickUnit unit, Calendar calendar, int value) {
            int years = calendar.get(Calendar.YEAR);
            calendar.clear(Calendar.MILLISECOND);
            calendar.set(years, value, 1, 0, 0, 0);
            Month month = new Month(calendar.getTime(), axis.timeZone,
                    axis.locale);
            Date standardDate = axis.calculateDateForPosition(month,
                    axis.tickMarkPosition);
            long millis = standardDate.getTime();
            if (millis >= date.getTime()) {
                month = (Month) month.previous();
                month.peg(Calendar.getInstance(axis.timeZone));
                standardDate = axis.calculateDateForPosition(month,
                        axis.tickMarkPosition);
            }
            return standardDate;
        }
    }

    /**
     * Strategy for year tick units.
     */
    private static class YearStrategy implements PreviousDateStrategy {
        @Override
        public Date previousStandardDate(DateAxis axis, Date date,
                DateTickUnit unit, Calendar calendar, int value) {
            calendar.clear(Calendar.MILLISECOND);
            calendar.set(value, axis.getTickMarkMonths(),
                    axis.getTickMarkYearDay(), 0, 0, 0);
            Date result = calendar.getTime();
            if (result.getTime() >= date.getTime()) {
                calendar.set(Calendar.YEAR, value - 1);
                result = calendar.getTime();
            }
            return result;
        }
    }

    /** Lookup table for previous-date strategies, indexed by tick unit code. */
    private static final PreviousDateStrategy[] PREVIOUS_DATE_STRATEGIES
            = createPreviousDateStrategies();

    /**
     * Creates the strategy lookup table for {@link #previousStandardDate}.
     *
     * @return The strategy lookup table.
     */
    private static PreviousDateStrategy[] createPreviousDateStrategies() {
        PreviousDateStrategy[] strategies = new PreviousDateStrategy[7];
        strategies[DateTickUnit.MILLISECOND] = new MillisecondStrategy();
        strategies[DateTickUnit.SECOND] = new SecondStrategy();
        strategies[DateTickUnit.MINUTE] = new MinuteStrategy();
        strategies[DateTickUnit.HOUR] = new HourStrategy();
        strategies[DateTickUnit.DAY] = new DayStrategy();
        strategies[DateTickUnit.MONTH] = new MonthStrategy();
        strategies[DateTickUnit.YEAR] = new YearStrategy();
        return strategies;
    }

    /**
     * Returns the strategy for the supplied tick unit code.
     *
     * @param unit  the tick unit code.
     *
     * @return The strategy, or <code>null</code> if the unit is unknown.
     */
    private static PreviousDateStrategy getPreviousDateStrategy(int unit) {
        if (unit < 0 || unit >= PREVIOUS_DATE_STRATEGIES.length) {
            return null;
        }
        return PREVIOUS_DATE_STRATEGIES[unit];
    }

    /**
     * Returns the previous "standard" date, for a given date and tick unit.
     *
     * @param date  the reference date.
     * @param unit  the tick unit.
     *
     * @return The previous "standard" date.
     */
    protected Date previousStandardDate(Date date, DateTickUnit unit) {
        Calendar calendar = Calendar.getInstance(this.timeZone, this.locale);
        calendar.setTime(date);
        int count = unit.getCount();
        int current = calendar.get(unit.getCalendarField());
        int value = count * (current / count);
        PreviousDateStrategy strategy = getPreviousDateStrategy(unit.getUnit());
        if (strategy == null) {
            return null;
        }
        return strategy.previousStandardDate(this, date, unit, calendar, value);
    }

    /**
     * Returns a {@link java.util.Date} corresponding to the specified position
     * within a {@link RegularTimePeriod}.
     *
     * @param period  the period.
     * @param position  the position (<code>null</code> not permitted).
     *
     * @return A date.
     */
    private Date calculateDateForPosition(RegularTimePeriod period,
            DateTickMarkPosition position) {
        ParamChecks.nullNotPermitted(period, "period");
        Date result = null;
        if (position == DateTickMarkPosition.START) {
            result = new Date(period.getFirstMillisecond());
        }
        else if (position == DateTickMarkPosition.MIDDLE) {
            result = new Date(period.getMiddleMillisecond());
        }
        else if (position == DateTickMarkPosition.END) {
            result = new Date(period.getLastMillisecond());
        }
        return result;

    }

    /**
     * Returns the first "standard" date (based on the specified field and
     * units).
     *
     * @param date  the reference date.
     * @param unit  the date tick unit.
     *
     * @return The next "standard" date.
     */
    protected Date nextStandardDate(Date date, DateTickUnit unit) {
        Date previous = previousStandardDate(date, unit);
        Calendar calendar = Calendar.getInstance(this.timeZone, this.locale);
        calendar.setTime(previous);
        calendar.add(unit.getCalendarField(), unit.getMultiple());
        return calendar.getTime();
    }

    /**
     * Returns a collection of standard date tick units that uses the default
     * time zone.  This collection will be used by default, but you are free
     * to create your own collection if you want to (see the
     * {@link ValueAxis#setStandardTickUnits(TickUnitSource)} method inherited
     * from the {@link ValueAxis} class).
     *
     * @return A collection of standard date tick units.
     */
    public static TickUnitSource createStandardDateTickUnits() {
        return createStandardDateTickUnits(TimeZone.getDefault(),
                Locale.getDefault());
    }

    /**
     * Returns a collection of standard date tick units.  This collection will
     * be used by default, but you are free to create your own collection if
     * you want to (see the
     * {@link ValueAxis#setStandardTickUnits(TickUnitSource)} method inherited
     * from the {@link ValueAxis} class).
     *
     * @param zone  the time zone (<code>null</code> not permitted).
     * @param locale  the locale (<code>null</code> not permitted).
     *
     * @return A collection of standard date tick units.
     *
     * @since 1.0.11
     */
    public static TickUnitSource createStandardDateTickUnits(TimeZone zone,
            Locale locale) {

        ParamChecks.nullNotPermitted(zone, "zone");
        ParamChecks.nullNotPermitted(locale, "locale");
        TickUnits units = new TickUnits();

        // date formatters
        DateFormat f1 = new SimpleDateFormat("HH:mm:ss.SSS", locale);
        DateFormat f2 = new SimpleDateFormat("HH:mm:ss", locale);
        DateFormat f3 = new SimpleDateFormat("HH:mm", locale);
        DateFormat f4 = new SimpleDateFormat("d-MMM, HH:mm", locale);
        DateFormat f5 = new SimpleDateFormat("d-MMM", locale);
        DateFormat f6 = new SimpleDateFormat("MMM-yyyy", locale);
        DateFormat f7 = new SimpleDateFormat("yyyy", locale);

        f1.setTimeZone(zone);
        f2.setTimeZone(zone);
        f3.setTimeZone(zone);
        f4.setTimeZone(zone);
        f5.setTimeZone(zone);
        f6.setTimeZone(zone);
        f7.setTimeZone(zone);

        // milliseconds
        units.add(new DateTickUnit(DateTickUnitType.MILLISECOND, 1, f1));
        units.add(new DateTickUnit(DateTickUnitType.MILLISECOND, 5,
                DateTickUnitType.MILLISECOND, 1, f1));
        units.add(new DateTickUnit(DateTickUnitType.MILLISECOND, 10,
                DateTickUnitType.MILLISECOND, 1, f1));
        units.add(new DateTickUnit(DateTickUnitType.MILLISECOND, 25,
                DateTickUnitType.MILLISECOND, 5, f1));
        units.add(new DateTickUnit(DateTickUnitType.MILLISECOND, 50,
                DateTickUnitType.MILLISECOND, 10, f1));
        units.add(new DateTickUnit(DateTickUnitType.MILLISECOND, 100,
                DateTickUnitType.MILLISECOND, 10, f1));
        units.add(new DateTickUnit(DateTickUnitType.MILLISECOND, 250,
                DateTickUnitType.MILLISECOND, 10, f1));
        units.add(new DateTickUnit(DateTickUnitType.MILLISECOND, 500,
                DateTickUnitType.MILLISECOND, 50, f1));

        // seconds
        units.add(new DateTickUnit(DateTickUnitType.SECOND, 1,
                DateTickUnitType.MILLISECOND, 50, f2));
        units.add(new DateTickUnit(DateTickUnitType.SECOND, 5,
                DateTickUnitType.SECOND, 1, f2));
        units.add(new DateTickUnit(DateTickUnitType.SECOND, 10,
                DateTickUnitType.SECOND, 1, f2));
        units.add(new DateTickUnit(DateTickUnitType.SECOND, 30,
                DateTickUnitType.SECOND, 5, f2));

        // minutes
        units.add(new DateTickUnit(DateTickUnitType.MINUTE, 1,
                DateTickUnitType.SECOND, 5, f3));
        units.add(new DateTickUnit(DateTickUnitType.MINUTE, 2,
                DateTickUnitType.SECOND, 10, f3));
        units.add(new DateTickUnit(DateTickUnitType.MINUTE, 5,
                DateTickUnitType.MINUTE, 1, f3));
        units.add(new DateTickUnit(DateTickUnitType.MINUTE, 10,
                DateTickUnitType.MINUTE, 1, f3));
        units.add(new DateTickUnit(DateTickUnitType.MINUTE, 15,
                DateTickUnitType.MINUTE, 5, f3));
        units.add(new DateTickUnit(DateTickUnitType.MINUTE, 20,
                DateTickUnitType.MINUTE, 5, f3));
        units.add(new DateTickUnit(DateTickUnitType.MINUTE, 30,
                DateTickUnitType.MINUTE, 5, f3));

        // hours
        units.add(new DateTickUnit(DateTickUnitType.HOUR, 1,
                DateTickUnitType.MINUTE, 5, f3));
        units.add(new DateTickUnit(DateTickUnitType.HOUR, 2,
                DateTickUnitType.MINUTE, 10, f3));
        units.add(new DateTickUnit(DateTickUnitType.HOUR, 4,
                DateTickUnitType.MINUTE, 30, f3));
        units.add(new DateTickUnit(DateTickUnitType.HOUR, 6,
                DateTickUnitType.HOUR, 1, f3));
        units.add(new DateTickUnit(DateTickUnitType.HOUR, 12,
                DateTickUnitType.HOUR, 1, f4));

        // days
        units.add(new DateTickUnit(DateTickUnitType.DAY, 1,
                DateTickUnitType.HOUR, 1, f5));
        units.add(new DateTickUnit(DateTickUnitType.DAY, 2,
                DateTickUnitType.HOUR, 1, f5));
        units.add(new DateTickUnit(DateTickUnitType.DAY, 7,
                DateTickUnitType.DAY, 1, f5));
        units.add(new DateTickUnit(DateTickUnitType.DAY, 15,
                DateTickUnitType.DAY, 1, f5));

        // months
        units.add(new DateTickUnit(DateTickUnitType.MONTH, 1,
                DateTickUnitType.DAY, 1, f6));
        units.add(new DateTickUnit(DateTickUnitType.MONTH, 2,
                DateTickUnitType.DAY, 1, f6));
        units.add(new DateTickUnit(DateTickUnitType.MONTH, 3,
                DateTickUnitType.MONTH, 1, f6));
        units.add(new DateTickUnit(DateTickUnitType.MONTH, 4,
                DateTickUnitType.MONTH, 1, f6));
        units.add(new DateTickUnit(DateTickUnitType.MONTH, 6,
                DateTickUnitType.MONTH, 1, f6));

        // years
        units.add(new DateTickUnit(DateTickUnitType.YEAR, 1,
                DateTickUnitType.MONTH, 1, f7));
        units.add(new DateTickUnit(DateTickUnitType.YEAR, 2,
                DateTickUnitType.MONTH, 3, f7));
        units.add(new DateTickUnit(DateTickUnitType.YEAR, 5,
                DateTickUnitType.YEAR, 1, f7));
        units.add(new DateTickUnit(DateTickUnitType.YEAR, 10,
                DateTickUnitType.YEAR, 1, f7));
        units.add(new DateTickUnit(DateTickUnitType.YEAR, 25,
                DateTickUnitType.YEAR, 5, f7));
        units.add(new DateTickUnit(DateTickUnitType.YEAR, 50,
                DateTickUnitType.YEAR, 10, f7));
        units.add(new DateTickUnit(DateTickUnitType.YEAR, 100,
                DateTickUnitType.YEAR, 20, f7));

        return units;

    }

    /**
     * Rescales the axis to ensure that all data is visible.
     */
    @Override
    protected void autoAdjustRange() {

        Plot plot = getPlot();

        if (plot == null) {
            return;  // no plot, no data
        }

        if (plot instanceof ValueAxisPlot) {
            ValueAxisPlot vap = (ValueAxisPlot) plot;

            Range r = vap.getDataRange(this);
            if (r == null) {
                if (this.timeline instanceof SegmentedTimeline) {
                    //Timeline hasn't method getStartTime()
                    r = new DateRange((
                            (SegmentedTimeline) this.timeline).getStartTime(),
                            ((SegmentedTimeline) this.timeline).getStartTime()
                            + 1);
                }
                else {
                    r = new DateRange();
                }
            }

            long upper = this.timeline.toTimelineValue(
                    (long) r.getUpperBound());
            long lower;
            long fixedAutoRange = (long) getFixedAutoRange();
            if (fixedAutoRange > 0.0) {
                lower = upper - fixedAutoRange;
            }
            else {
                lower = this.timeline.toTimelineValue((long) r.getLowerBound());
                double range = upper - lower;
                long minRange = (long) getAutoRangeMinimumSize();
                if (range < minRange) {
                    long expand = (long) (minRange - range) / 2;
                    upper = upper + expand;
                    lower = lower - expand;
                }
                upper = upper + (long) (range * getUpperMargin());
                lower = lower - (long) (range * getLowerMargin());
            }

            upper = this.timeline.toMillisecond(upper);
            lower = this.timeline.toMillisecond(lower);
            DateRange dr = new DateRange(new Date(lower), new Date(upper));
            setRange(dr, false, false);
        }

    }

    /**
     * Selects an appropriate tick value for the axis.  The strategy is to
     * display as many ticks as possible (selected from an array of 'standard'
     * tick units) without the labels overlapping.
     *
     * @param g2  the graphics device.
     * @param dataArea  the area defined by the axes.
     * @param edge  the axis location.
     */
    protected void selectAutoTickUnit(Graphics2D g2, Rectangle2D dataArea,
            RectangleEdge edge) {

        if (RectangleEdge.isTopOrBottom(edge)) {
            selectHorizontalAutoTickUnit(g2, dataArea, edge);
        }
        else if (RectangleEdge.isLeftOrRight(edge)) {
            selectVerticalAutoTickUnit(g2, dataArea, edge);
        }

    }

    /**
     * Selects an appropriate tick size for the axis.  The strategy is to
     * display as many ticks as possible (selected from a collection of
     * 'standard' tick units) without the labels overlapping.
     *
     * @param g2  the graphics device.
     * @param dataArea  the area defined by the axes.
     * @param edge  the axis location.
     */
    protected void selectHorizontalAutoTickUnit(Graphics2D g2,
            Rectangle2D dataArea, RectangleEdge edge) {

        long shift = 0;
        if (this.timeline instanceof SegmentedTimeline) {
            shift = ((SegmentedTimeline) this.timeline).getStartTime();
        }
        double zero = valueToJava2D(shift + 0.0, dataArea, edge);
        double tickLabelWidth = estimateMaximumTickLabelWidth(g2,
                getTickUnit());

        // start with the current tick unit...
        TickUnitSource tickUnits = getStandardTickUnits();
        TickUnit unit1 = tickUnits.getCeilingTickUnit(getTickUnit());
        double x1 = valueToJava2D(shift + unit1.getSize(), dataArea, edge);
        double unit1Width = Math.abs(x1 - zero);

        // then extrapolate...
        double guess = (tickLabelWidth / unit1Width) * unit1.getSize();
        DateTickUnit unit2 = (DateTickUnit) tickUnits.getCeilingTickUnit(guess);
        double x2 = valueToJava2D(shift + unit2.getSize(), dataArea, edge);
        double unit2Width = Math.abs(x2 - zero);
        tickLabelWidth = estimateMaximumTickLabelWidth(g2, unit2);
        if (tickLabelWidth > unit2Width) {
            unit2 = (DateTickUnit) tickUnits.getLargerTickUnit(unit2);
        }
        setTickUnit(unit2, false, false);
    }

    /**
     * Selects an appropriate tick size for the axis.  The strategy is to
     * display as many ticks as possible (selected from a collection of
     * 'standard' tick units) without the labels overlapping.
     *
     * @param g2  the graphics device.
     * @param dataArea  the area in which the plot should be drawn.
     * @param edge  the axis location.
     */
    protected void selectVerticalAutoTickUnit(Graphics2D g2,
            Rectangle2D dataArea, RectangleEdge edge) {

        // start with the current tick unit...
        TickUnitSource tickUnits = getStandardTickUnits();
        double zero = valueToJava2D(0.0, dataArea, edge);

        // start with a unit that is at least 1/10th of the axis length
        double estimate1 = getRange().getLength() / 10.0;
        DateTickUnit candidate1
            = (DateTickUnit) tickUnits.getCeilingTickUnit(estimate1);
        double labelHeight1 = estimateMaximumTickLabelHeight(g2, candidate1);
        double y1 = valueToJava2D(candidate1.getSize(), dataArea, edge);
        double candidate1UnitHeight = Math.abs(y1 - zero);

        // now extrapolate based on label height and unit height...
        double estimate2
            = (labelHeight1 / candidate1UnitHeight) * candidate1.getSize();
        DateTickUnit candidate2
            = (DateTickUnit) tickUnits.getCeilingTickUnit(estimate2);
        double labelHeight2 = estimateMaximumTickLabelHeight(g2, candidate2);
        double y2 = valueToJava2D(candidate2.getSize(), dataArea, edge);
        double unit2Height = Math.abs(y2 - zero);

       // make final selection...
       DateTickUnit finalUnit;
       if (labelHeight2 < unit2Height) {
           finalUnit = candidate2;
       }
       else {
           finalUnit = (DateTickUnit) tickUnits.getLargerTickUnit(candidate2);
       }
       setTickUnit(finalUnit, false, false);

    }

    /**
     * Estimates the maximum width of the tick labels, assuming the specified
     * tick unit is used.
     * <P>
     * Rather than computing the string bounds of every tick on the axis, we
     * just look at two values: the lower bound and the upper bound for the
     * axis.  These two values will usually be representative.
     *
     * @param g2  the graphics device.
     * @param unit  the tick unit to use for calculation.
     *
     * @return The estimated maximum width of the tick labels.
     */
    private double estimateMaximumTickLabelWidth(Graphics2D g2, 
            DateTickUnit unit) {

        RectangleInsets tickLabelInsets = getTickLabelInsets();
        double result = tickLabelInsets.getLeft() + tickLabelInsets.getRight();

        Font tickLabelFont = getTickLabelFont();
        FontRenderContext frc = g2.getFontRenderContext();
        LineMetrics lm = tickLabelFont.getLineMetrics("ABCxyz", frc);
        if (isVerticalTickLabels()) {
            // all tick labels have the same width (equal to the height of
            // the font)...
            result += lm.getHeight();
        }
        else {
            // look at lower and upper bounds...
            DateRange range = (DateRange) getRange();
            Date lower = range.getLowerDate();
            Date upper = range.getUpperDate();
            String lowerStr, upperStr;
            DateFormat formatter = getDateFormatOverride();
            if (formatter != null) {
                lowerStr = formatter.format(lower);
                upperStr = formatter.format(upper);
            }
            else {
                lowerStr = unit.dateToString(lower);
                upperStr = unit.dateToString(upper);
            }
            FontMetrics fm = g2.getFontMetrics(tickLabelFont);
            double w1 = fm.stringWidth(lowerStr);
            double w2 = fm.stringWidth(upperStr);
            result += Math.max(w1, w2);
        }

        return result;

    }

    /**
     * Estimates the maximum width of the tick labels, assuming the specified
     * tick unit is used.
     * <P>
     * Rather than computing the string bounds of every tick on the axis, we
     * just look at two values: the lower bound and the upper bound for the
     * axis.  These two values will usually be representative.
     *
     * @param g2  the graphics device.
     * @param unit  the tick unit to use for calculation.
     *
     * @return The estimated maximum width of the tick labels.
     */
    private double estimateMaximumTickLabelHeight(Graphics2D g2,
            DateTickUnit unit) {

        RectangleInsets tickLabelInsets = getTickLabelInsets();
        double result = tickLabelInsets.getTop() + tickLabelInsets.getBottom();

        Font tickLabelFont = getTickLabelFont();
        FontRenderContext frc = g2.getFontRenderContext();
        LineMetrics lm = tickLabelFont.getLineMetrics("ABCxyz", frc);
        if (!isVerticalTickLabels()) {
            // all tick labels have the same width (equal to the height of
            // the font)...
            result += lm.getHeight();
        }
        else {
            // look at lower and upper bounds...
            DateRange range = (DateRange) getRange();
            Date lower = range.getLowerDate();
            Date upper = range.getUpperDate();
            String lowerStr, upperStr;
            DateFormat formatter = getDateFormatOverride();
            if (formatter != null) {
                lowerStr = formatter.format(lower);
                upperStr = formatter.format(upper);
            }
            else {
                lowerStr = unit.dateToString(lower);
                upperStr = unit.dateToString(upper);
            }
            FontMetrics fm = g2.getFontMetrics(tickLabelFont);
            double w1 = fm.stringWidth(lowerStr);
            double w2 = fm.stringWidth(upperStr);
            result += Math.max(w1, w2);
        }

        return result;

    }

    /**
     * Calculates the positions of the tick labels for the axis, storing the
     * results in the tick label list (ready for drawing).
     *
     * @param g2  the graphics device.
     * @param state  the axis state.
     * @param dataArea  the area in which the plot should be drawn.
     * @param edge  the location of the axis.
     *
     * @return A list of ticks.
     */
    @Override
    public List refreshTicks(Graphics2D g2, AxisState state, 
            Rectangle2D dataArea, RectangleEdge edge) {

        List result = null;
        if (RectangleEdge.isTopOrBottom(edge)) {
            result = refreshTicksHorizontal(g2, dataArea, edge);
        }
        else if (RectangleEdge.isLeftOrRight(edge)) {
            result = refreshTicksVertical(g2, dataArea, edge);
        }
        return result;

    }

    /**
     * Strategy for correcting a tick date based on the tick unit type.
     */
    private interface TickDateCorrector {
        /**
         * Corrects the supplied tick date.
         *
         * @param time  the tick date.
         * @param axis  the source axis.
         * @param position  the tick mark position.
         *
         * @return The corrected date.
         */
        Date correct(Date time, DateAxis axis, DateTickMarkPosition position);
    }

    /**
     * Corrector that leaves the date unchanged.
     */
    private static class IdentityTickDateCorrector implements TickDateCorrector {
        @Override
        public Date correct(Date time, DateAxis axis,
                DateTickMarkPosition position) {
            return time;
        }
    }

    /**
     * Corrector for month tick units.
     */
    private static class MonthTickDateCorrector implements TickDateCorrector {
        @Override
        public Date correct(Date time, DateAxis axis,
                DateTickMarkPosition position) {
            return axis.calculateDateForPosition(new Month(time,
                    axis.timeZone, axis.locale), position);
        }
    }

    /**
     * Corrector for year tick units.
     */
    private static class YearTickDateCorrector implements TickDateCorrector {
        @Override
        public Date correct(Date time, DateAxis axis,
                DateTickMarkPosition position) {
            return axis.calculateDateForPosition(new Year(time,
                    axis.timeZone, axis.locale), position);
        }
    }

    /** Lookup table for tick-date correctors, indexed by tick unit code. */
    private static final TickDateCorrector[] TICK_DATE_CORRECTORS
            = createTickDateCorrectors();

    /**
     * Creates the lookup table for {@link #correctTickDateForPosition}.
     *
     * @return The corrector lookup table.
     */
    private static TickDateCorrector[] createTickDateCorrectors() {
        TickDateCorrector[] correctors = new TickDateCorrector[7];
        TickDateCorrector identity = new IdentityTickDateCorrector();
        correctors[DateTickUnit.MILLISECOND] = identity;
        correctors[DateTickUnit.SECOND] = identity;
        correctors[DateTickUnit.MINUTE] = identity;
        correctors[DateTickUnit.HOUR] = identity;
        correctors[DateTickUnit.DAY] = identity;
        correctors[DateTickUnit.MONTH] = new MonthTickDateCorrector();
        correctors[DateTickUnit.YEAR] = new YearTickDateCorrector();
        return correctors;
    }

    /**
     * Returns the corrector for the supplied tick unit code.
     *
     * @param unit  the tick unit code.
     *
     * @return The corrector, or <code>null</code> if the unit is unknown.
     */
    private static TickDateCorrector getTickDateCorrector(int unit) {
        if (unit < 0 || unit >= TICK_DATE_CORRECTORS.length) {
            return null;
        }
        return TICK_DATE_CORRECTORS[unit];
    }

    /**
     * Corrects the given tick date for the position setting.
     *
     * @param time  the tick date/time.
     * @param unit  the tick unit.
     * @param position  the tick position.
     *
     * @return The adjusted time.
     */
    private Date correctTickDateForPosition(Date time, DateTickUnit unit,
            DateTickMarkPosition position) {
        TickDateCorrector corrector = getTickDateCorrector(unit.getUnit());
        if (corrector == null) {
            return time;
        }
        return corrector.correct(time, this, position);
    }

    /**
     * Formats a tick date using the override formatter, if set, or the
     * current tick unit's formatter otherwise.
     *
     * @param tickDate  the tick date.
     *
     * @return The formatted label.
     */
    private String formatTickLabel(Date tickDate) {
        DateFormat formatter = getDateFormatOverride();
        if (formatter != null) {
            return formatter.format(tickDate);
        }
        return this.tickUnit.dateToString(tickDate);
    }

    /**
     * Returns the anchor to use for tick labels.
     *
     * @param edge  the axis edge.
     * @param verticalTickLabels  vertical labels flag.
     *
     * @return The anchor.
     */
    private TextAnchor getTickLabelAnchor(RectangleEdge edge,
            boolean verticalTickLabels) {
        if (verticalTickLabels) {
            if (RectangleEdge.isTopOrBottom(edge)) {
                return TextAnchor.CENTER_RIGHT;
            }
            return TextAnchor.BOTTOM_CENTER;
        }
        if (RectangleEdge.isTopOrBottom(edge)) {
            return (edge == RectangleEdge.TOP) ? TextAnchor.BOTTOM_CENTER
                    : TextAnchor.TOP_CENTER;
        }
        return (edge == RectangleEdge.LEFT) ? TextAnchor.CENTER_RIGHT
                : TextAnchor.CENTER_LEFT;
    }

    /**
     * Returns the rotation angle to use for tick labels.
     *
     * @param edge  the axis edge.
     * @param verticalTickLabels  vertical labels flag.
     *
     * @return The angle.
     */
    private double getTickLabelAngle(RectangleEdge edge,
            boolean verticalTickLabels) {
        if (!verticalTickLabels) {
            return 0.0;
        }
        if (RectangleEdge.isTopOrBottom(edge)) {
            return (edge == RectangleEdge.TOP) ? Math.PI / 2.0
                    : -Math.PI / 2.0;
        }
        return (edge == RectangleEdge.LEFT) ? -Math.PI / 2.0
                : Math.PI / 2.0;
    }

    /**
     * Adds leading minor ticks before the current major tick.
     *
     * @param result  the tick list.
     * @param lowestTickTime  the major tick time.
     * @param distance  the distance to the next major tick.
     * @param minorTickSpaces  the number of minor tick spaces.
     */
    private void addLeadingMinorTicks(List result, long lowestTickTime,
            long distance, int minorTickSpaces) {
        for (int minorTick = 1; minorTick < minorTickSpaces; minorTick++) {
            long minorTickTime = lowestTickTime - distance
                    * minorTick / minorTickSpaces;
            if (minorTickTime > 0 && getRange().contains(minorTickTime)
                    && (!isHiddenValue(minorTickTime))) {
                result.add(new DateTick(TickType.MINOR,
                        new Date(minorTickTime), "", TextAnchor.TOP_CENTER,
                        TextAnchor.CENTER, 0.0));
            }
        }
    }

    /**
     * Adds trailing minor ticks after the current major tick.
     *
     * @param result  the tick list.
     * @param currentTickTime  the current major tick time.
     * @param nextTickTime  the next major tick time.
     * @param minorTickSpaces  the number of minor tick spaces.
     */
    private void addTrailingMinorTicks(List result, long currentTickTime,
            long nextTickTime, int minorTickSpaces) {
        for (int minorTick = 1; minorTick < minorTickSpaces; minorTick++) {
            long minorTickTime = currentTickTime
                    + (nextTickTime - currentTickTime)
                    * minorTick / minorTickSpaces;
            if (getRange().contains(minorTickTime)
                    && (!isHiddenValue(minorTickTime))) {
                result.add(new DateTick(TickType.MINOR,
                        new Date(minorTickTime), "", TextAnchor.TOP_CENTER,
                        TextAnchor.CENTER, 0.0));
            }
        }
    }

    /**
     * Recalculates the ticks for the date axis.
     *
     * @param g2  the graphics device.
     * @param dataArea  the area in which the data is to be drawn.
     * @param edge  the location of the axis.
     *
     * @return A list of ticks.
     */
    protected List refreshTicksHorizontal(Graphics2D g2,
                Rectangle2D dataArea, RectangleEdge edge) {

        List result = new java.util.ArrayList();

        Font tickLabelFont = getTickLabelFont();
        g2.setFont(tickLabelFont);

        if (isAutoTickUnitSelection()) {
            selectAutoTickUnit(g2, dataArea, edge);
        }

        DateTickUnit unit = getTickUnit();
        Date tickDate = calculateLowestVisibleTickValue(unit);
        Date upperDate = getMaximumDate();

        boolean hasRolled = false;
        while (tickDate.before(upperDate)) {
            // could add a flag to make the following correction optional...
            if (!hasRolled) {
                tickDate = correctTickDateForPosition(tickDate, unit,
                     this.tickMarkPosition);
            }

            long lowestTickTime = tickDate.getTime();
            long distance = unit.addToDate(tickDate, this.timeZone).getTime()
                    - lowestTickTime;
            int minorTickSpaces = getMinorTickCount();
            if (minorTickSpaces <= 0) {
                minorTickSpaces = unit.getMinorTickCount();
            }
            addLeadingMinorTicks(result, lowestTickTime, distance,
                    minorTickSpaces);

            if (!isHiddenValue(tickDate.getTime())) {
                // work out the value, label and position
                String tickLabel = formatTickLabel(tickDate);
                TextAnchor anchor = getTickLabelAnchor(edge,
                        isVerticalTickLabels());
                double angle = getTickLabelAngle(edge, isVerticalTickLabels());

                Tick tick = new DateTick(tickDate, tickLabel, anchor,
                        anchor, angle);
                result.add(tick);
                hasRolled = false;

                long currentTickTime = tickDate.getTime();
                tickDate = unit.addToDate(tickDate, this.timeZone);
                long nextTickTime = tickDate.getTime();
                addTrailingMinorTicks(result, currentTickTime, nextTickTime,
                        minorTickSpaces);

            }
            else {
                tickDate = unit.rollDate(tickDate, this.timeZone);
                hasRolled = true;
                continue;
            }

        }
        return result;

    }

    /**
     * Recalculates the ticks for the date axis.
     *
     * @param g2  the graphics device.
     * @param dataArea  the area in which the plot should be drawn.
     * @param edge  the location of the axis.
     *
     * @return A list of ticks.
     */
    protected List refreshTicksVertical(Graphics2D g2,
            Rectangle2D dataArea, RectangleEdge edge) {

        List result = new java.util.ArrayList();

        Font tickLabelFont = getTickLabelFont();
        g2.setFont(tickLabelFont);

        if (isAutoTickUnitSelection()) {
            selectAutoTickUnit(g2, dataArea, edge);
        }
        DateTickUnit unit = getTickUnit();
        Date tickDate = calculateLowestVisibleTickValue(unit);
        Date upperDate = getMaximumDate();

        boolean hasRolled = false;
        while (tickDate.before(upperDate)) {

            // could add a flag to make the following correction optional...
            if (!hasRolled) {
                tickDate = correctTickDateForPosition(tickDate, unit,
                    this.tickMarkPosition);
            }

            long lowestTickTime = tickDate.getTime();
            long distance = unit.addToDate(tickDate, this.timeZone).getTime()
                    - lowestTickTime;
            int minorTickSpaces = getMinorTickCount();
            if (minorTickSpaces <= 0) {
