        }
        DateAxis that = (DateAxis) obj;
        if (!ObjectUtilities.equal(this.timeZone, that.timeZone)) {
            return false;
        }
        if (!ObjectUtilities.equal(this.locale, that.locale)) {
            return false;
        }
        if (!ObjectUtilities.equal(this.tickUnit, that.tickUnit)) {
            return false;
        }
