    protected Date previousStandardDate(Date date, DateTickUnit unit) {
        Calendar calendar = Calendar.getInstance(this.timeZone, this.locale);
        calendar.setTime(date);
        int count = unit.getCount();
        int current = calendar.get(unit.getCalendarField());
        int value = count * (current / count);
        PreviousDateStrategy strategy = getPreviousDateStrategy(unit.getUnit());
        if (strategy == null) {
            return null;
        }
        return strategy.previousStandardDate(this, date, unit, calendar, value);
    }

    private PreviousDateStrategy getPreviousDateStrategy(int unit) {
        if (unit < 0 || unit >= PREVIOUS_DATE_STRATEGIES.length) {
            return null;
        }
        return PREVIOUS_DATE_STRATEGIES[unit];
    }

