    if (isScriptsNode(child)) {
        processScriptsNode(child);
    } else if (isAppendersNode(child)) {
        appenders = child.getObject();
    } else if (child.isInstanceOf(Filter.class)) {
        addFilter(child.getObject(Filter.class));
    } else if (isLoggersNode(child)) {
        processLoggersNode(child, state);
    } else if (isCustomLevelsNode(child)) {
        processCustomLevelsNode(child);
    } else if (child.isInstanceOf(CustomLevelConfig.class)) {
        processCustomLevelNode(child);
    } else {
        processUnknownNode(child);
    }
