private void stopRemainingAppenders(final String cls, final Appender[] appendersArray) {
    LOGGER.trace("{} stopping remaining Appenders.", cls);
    int appenderCount = 0;
    for (int i = appendersArray.length - 1; i >= 0; --i) {
        if (appendersArray[i].isStarted()) { // then stop remaining Appenders
            appendersArray[i].stop();
            appenderCount++;
        }
