protected void doConfigure() {
    preConfigure(rootNode);
    configurationScheduler.start();
    if (rootNode.hasChildren() && rootNode.getChildren().get(0).getName().equalsIgnoreCase("Properties")) {
        final Node first = rootNode.getChildren().get(0);
        createConfiguration(first, null);
        if (first.getObject() != null) {
            subst.setVariableResolver((StrLookup) first.getObject());
        }
    } else {
        final Map<String, String> map = this.getComponent(CONTEXT_PROPERTIES);
        final StrLookup lookup = map == null ? null : new MapLookup(map);
        subst.setVariableResolver(new Interpolator(lookup, pluginPackages));
    }

    final ConfigurationDispatchContext ctx = new ConfigurationDispatchContext();
    for (final Node child : rootNode.getChildren()) {
        if (isPropertiesNode(child)) {
            reportPropertiesOutOfOrderIfNeeded();
            continue;
        }
        createConfiguration(child, null);
        if (child.getObject() == null) {
            continue;
        }
        dispatchChild(child, ctx);
    }

    if (!ensureLoggersConfigured(ctx)) {
        return;
    }

    attachAppendersToLoggers();
    setParents();
}

