private enum ChildHandler {
    SCRIPTS("Scripts") {
        @Override
        void handle(final Node child, final AbstractConfiguration config, final ConfigurationDispatchContext ctx) {
            for (final AbstractScript script : child.getObject(AbstractScript[].class)) {
                if (script instanceof ScriptRef) {
                    LOGGER.error("Script reference to {} not added. Scripts definition cannot contain script references",
                            script.getName());
                } else {
                    config.scriptManager.addScript(script);
                }
            }
        }
    },
    APPENDERS("Appenders") {
        @Override
        void handle(final Node child, final AbstractConfiguration config, final ConfigurationDispatchContext ctx) {
            config.appenders = child.getObject();
        }
    },
    FILTERS(null) {
        @Override
        boolean matches(final Node child) {
            return child.isInstanceOf(Filter.class);
        }
        @Override
        void handle(final Node child, final AbstractConfiguration config, final ConfigurationDispatchContext ctx) {
            config.addFilter(child.getObject(Filter.class));
        }
    },
    LOGGERS("Loggers") {
        @Override
        void handle(final Node child, final AbstractConfiguration config, final ConfigurationDispatchContext ctx) {
            final Loggers loggers = child.getObject();
            config.loggerConfigs = loggers.getMap();
            ctx.loggersSet = true;
            if (loggers.getRoot() != null) {
                config.root = loggers.getRoot();
                ctx.rootSet = true;
            }
        }
    },
    CUSTOM_LEVELS("CustomLevels") {
        @Override
        void handle(final Node child, final AbstractConfiguration config, final ConfigurationDispatchContext ctx) {
            config.customLevels = child.getObject(CustomLevels.class).getCustomLevels();
        }
    },
    CUSTOM_LEVEL_CONFIG(null) {
        @Override
        boolean matches(final Node child) {
            return child.isInstanceOf(CustomLevelConfig.class);
        }
        @Override
        void handle(final Node child, final AbstractConfiguration config, final ConfigurationDispatchContext ctx) {
            final List<CustomLevelConfig> copy = new ArrayList<>(config.customLevels);
            copy.add(child.getObject(CustomLevelConfig.class));
            config.customLevels = copy;
        }
    },
    UNKNOWN(null) {
        @Override
        boolean matches(final Node child) {
            return true;
        }
        @Override
        void handle(final Node child, final AbstractConfiguration config, final ConfigurationDispatchContext ctx) {
            LOGGER.error("Unknown object \"{}\" of type {} is ignored: try nesting it inside one of: {}.",
                    child.getName(), child.getObject().getClass().getName(), EXPECTED_CHILD_NAMES);
        }
    };

    private final String name;

    ChildHandler(final String name) {
        this.name = name;
    }

    boolean matches(final Node child) {
        return name != null && child.getName().equalsIgnoreCase(name);
    }

    abstract void handle(final Node child, final AbstractConfiguration config, final ConfigurationDispatchContext ctx);
}

