    protected void preConfigure(Node node) {
        for (final Node child : node.getChildren()) {
            Class<?> clazz = child.getType().getPluginClass();
            if (clazz.isAnnotationPresent(Scheduled.class)) {
                configurationScheduler.incrementScheduledItems();
            }
            preConfigure(child);
        }
    }

    protected void doConfigure() {
        preConfigure(rootNode);
        configurationScheduler.start();
        configureSubstitutor();
        final ConfigurationProcessState state = new ConfigurationProcessState();
        for (final Node child : rootNode.getChildren()) {
            processChildNode(child, state);
        }

        if (!state.setLoggers) {
            LOGGER.warn("No Loggers were configured, using default. Is the Loggers element missing?");
            setToDefault();
            return;
        } else if (!state.setRoot) {
            LOGGER.warn("No Root logger was configured, creating default ERROR-level Root logger with Console appender");
            setToDefault();
            // return; // LOG4J2-219: creating default root=ok, but don't exclude configured Loggers
        }

        attachAppendersToLoggers();
        setParents();
    }

    /**
     * Configures the {@link StrSubstitutor} from the first child node or from the context properties.
     */
    private void configureSubstitutor() {
        if (rootNode.hasChildren() && rootNode.getChildren().get(0).getName().equalsIgnoreCase("Properties")) {
            final Node first = rootNode.getChildren().get(0);
            createConfiguration(first, null);
            if (first.getObject() != null) {
                subst.setVariableResolver((StrLookup) first.getObject());
            }
        } else {
            final Map<String, String> map = this.getComponent(CONTEXT_PROPERTIES);
            final StrLookup lookup = map == null ? null : new MapLookup(map);
            subst.setVariableResolver(new Interpolator(lookup, pluginPackages));
        }
    }

    /**
     * Processes a single top-level configuration child node.
     */
    private void processChildNode(final Node child, final ConfigurationProcessState state) {
        if (isPropertiesNode(child)) {
            if (isPropertiesOutOfOrder()) {
                LOGGER.error("Properties declaration must be the first element in the configuration");
            }
            return;
        }
        createConfiguration(child, null);
        if (child.getObject() == null) {
            return;
        }
        dispatchChildNode(child, state);
    }

    /**
     * Determines whether the supplied node is a Properties declaration.
     */
    private boolean isPropertiesNode(final Node child) {
        return child.getName().equalsIgnoreCase("Properties");
    }

    /**
     * Determines whether a Properties declaration was not processed as the first child node.
     */
    private boolean isPropertiesOutOfOrder() {
        return tempLookup == subst.getVariableResolver();
    }

    /**
     * Dispatches a configured child node to the handler appropriate for its name or plugin type.
     */
    private void dispatchChildNode(final Node child, final ConfigurationProcessState state) {
        final ChildNodeHandler handler = CHILD_NODE_HANDLERS.get(child.getName());
        if (handler != null) {
            handler.handle(this, child, state);
        } else if (child.isInstanceOf(Filter.class)) {
            addFilter(child.getObject(Filter.class));
        } else if (child.isInstanceOf(CustomLevelConfig.class)) {
            addCustomLevel(child.getObject(CustomLevelConfig.class));
        } else {
            logUnknownNode(child);
        }
    }

    /**
     * Adds a custom level configuration to the list of custom levels.
     */
    private void addCustomLevel(final CustomLevelConfig customLevel) {
        final List<CustomLevelConfig> copy = new ArrayList<>(customLevels);
        copy.add(customLevel);
        customLevels = copy;
    }

    /**
     * Logs an error for an unrecognized top-level configuration node.
     */
    private void logUnknownNode(final Node child) {
        final List<String> expected = Arrays.asList("\"Appenders\"", "\"Loggers\"", "\"Properties\"",
                "\"Scripts\"", "\"CustomLevels\"");
        LOGGER.error("Unknown object \"{}\" of type {} is ignored: try nesting it inside one of: {}.",
                child.getName(), child.getObject().getClass().getName(), expected);
    }

    /**
     * Attaches referenced appenders to their configured loggers.
     */
    private void attachAppendersToLoggers() {
        for (final Map.Entry<String, LoggerConfig> entry : loggerConfigs.entrySet()) {
            final LoggerConfig loggerConfig = entry.getValue();
            for (final AppenderRef ref : loggerConfig.getAppenderRefs()) {
                final Appender app = appenders.get(ref.getRef());
                if (app != null) {
                    loggerConfig.addAppender(app, ref.getLevel(), ref.getFilter());
                } else {
                    LOGGER.error("Unable to locate appender \"{}\" for logger config \"{}\"", ref.getRef(),
                            loggerConfig);
                }
            }
        }
    }

    protected void setToDefault() {
        // LOG4J2-1176 facilitate memory leak investigation
        setName(DefaultConfiguration.DEFAULT_NAME + "@" + Integer.toHexString(hashCode()));
        final Layout<? extends Serializable> layout = PatternLayout.newBuilder()
                .withPattern(DefaultConfiguration.DEFAULT_PATTERN)
                .withConfiguration(this)
                .build();
        final Appender appender = ConsoleAppender.createDefaultAppenderForLayout(layout);
        appender.start();
        addAppender(appender);
        final LoggerConfig rootLoggerConfig = getRootLogger();
        rootLoggerConfig.addAppender(appender, null, null);

        final Level defaultLevel = Level.ERROR;
        final String levelName = PropertiesUtil.getProperties().getStringProperty(DefaultConfiguration.DEFAULT_LEVEL,
                defaultLevel.name());
        final Level level = Level.valueOf(levelName);
        rootLoggerConfig.setLevel(level != null ? level : defaultLevel);
    }

