    private static final class ScriptsHandler implements ChildNodeHandler {
        @Override
        public void handle(final AbstractConfiguration config, final Node child, final ConfigurationProcessState state) {
            for (final AbstractScript script : child.getObject(AbstractScript[].class)) {
