     */
    private static final class LoggersHandler implements ChildNodeHandler {
        @SuppressWarnings("unchecked")
        @Override
        public void handle(final AbstractConfiguration config, final Node child, final ConfigurationProcessState state) {
            final Loggers loggers = child.getObject();
            config.loggerConfigs = (ConcurrentMap<String, LoggerConfig>) loggers.getMap();
            state.setLoggers = true;
