        }
    }

    /**
     * Strategy for creating plugin objects from special collection-like plugin classes.
     */
    private interface PluginObjectCreator {
        boolean supports(Class<?> clazz);

        Object create(AbstractConfiguration config, PluginType<?> type, Node node) throws Exception;

        void logError(AbstractConfiguration config, PluginType<?> type, Class<?> clazz, Exception e);
    }

    /**
     * Creates plugin objects for types assignable to {@link Map}.
     */
    private static final class MapCreator implements PluginObjectCreator {
        @Override
        public boolean supports(final Class<?> clazz) {
            return Map.class.isAssignableFrom(clazz);
        }

        @Override
        public Object create(final AbstractConfiguration config, final PluginType<?> type, final Node node) throws Exception {
            return createPluginMap(node);
        }

        @Override
        public void logError(final AbstractConfiguration config, final PluginType<?> type, final Class<?> clazz, final Exception e) {
            config.LOGGER.warn("Unable to create Map for {} of class {}", type.getElementName(), clazz, e);
        }
    }

    /**
     * Creates plugin objects for types assignable to {@link Collection}.
     */
    private static final class CollectionCreator implements PluginObjectCreator {
        @Override
        public boolean supports(final Class<?> clazz) {
            return Collection.class.isAssignableFrom(clazz);
        }

        @Override
        public Object create(final AbstractConfiguration config, final PluginType<?> type, final Node node) throws Exception {
            return createPluginCollection(node);
        }

        @Override
        public void logError(final AbstractConfiguration config, final PluginType<?> type, final Class<?> clazz, final Exception e) {
            config.LOGGER.warn("Unable to create List for {} of class {}", type.getElementName(), clazz, e);
        }
    }

    /**
     * Reads an InputStream using buffered reads into a byte array buffer. The given InputStream will remain open after
     * invocation of this method.
     *
     * @param is the InputStream to read into a byte array buffer.
     * @return a byte array of the InputStream contents.
     * @throws IOException if the {@code read} method of the provided InputStream throws this exception.
     */
    protected static byte[] toByteArray(final InputStream is) throws IOException {
        final ByteArrayOutputStream buffer = new ByteArrayOutputStream();

        int nRead;
        final byte[] data = new byte[BUF_SIZE];

        while ((nRead = is.read(data, 0, data.length)) != -1) {
            buffer.write(data, 0, nRead);
        }

        return buffer.toByteArray();
    }

}

