```
/**
 * Resolves a possibly null logging level to {@code Level.OFF}.
 *
 * @param level the level to resolve
 * @return the supplied level, or {@code Level.OFF} if it is null
 */
private static Level resolveLevel(final Level level) {
    return level == null ? Level.OFF : level; // LOG4J2-462, LOG4J2-465
}

/**
 * Returns an empty context map when the provided map is null.
 *
 * @param contextMap the context map to resolve
 * @return the supplied map, or an empty map if it is null
 */
private static Map<String, String> resolveContextMap(final Map<String, String> contextMap) {
    return contextMap == null ? ThreadContext.EMPTY_MAP : contextMap;
}

/**
 * Returns an empty context stack when the provided stack is null.
 *
 * @param contextStack the context stack to resolve
 * @return the supplied stack, or an empty stack if it is null
 */
private static ThreadContext.ContextStack resolveContextStack(final ThreadContext.ContextStack contextStack) {
    return contextStack == null ? ThreadContext.EMPTY_STACK : contextStack;
}

/**
 * Resolves the event timestamp from a {@code TimestampMessage} or the supplied timestamp.
 *
 * @param message the message, which may implement {@code TimestampMessage}
 * @param timestampMillis the fallback timestamp
 * @return the message timestamp, or the supplied timestamp
 */
private static long resolveTimeMillis(final Message message, final long timestampMillis) {
    return message instanceof TimestampMessage
            ? ((TimestampMessage) message).getTimestamp()
            : timestampMillis;
}

/**
 * Sets the logger name on messages that are aware of their logger name.
 *
 * @param message the message
 * @param loggerName the logger name to set
 */
private static void setLoggerNameOnMessage(final Message message, final String loggerName) {
    if (message != null && message instanceof LoggerNameAwareMessage) {
        ((LoggerNameAwareMessage) message).setLoggerName(loggerName);
    }
}
