@Override
public boolean equals(final Object o) {
    if (this == o) {
        return true;
    }
    if (o == null || getClass() != o.getClass()) {
        return false;
    }

    final Log4jLogEvent that = (Log4jLogEvent) o;
    return primitiveFieldsEqual(that)
            && loggerAndMessageEqual(that)
            && metadataEqual(that)
            && contextEqual(that)
            && throwableFieldsEqual(that);
}

/**
 * Compares primitive fields for equality.
 */
private boolean primitiveFieldsEqual(final Log4jLogEvent that) {
    return endOfBatch == that.endOfBatch
            && includeLocation == that.includeLocation
            && timeMillis == that.timeMillis
            && nanoTime == that.nanoTime;
}

/**
 * Compares logger name and message for equality.
 */
private boolean loggerAndMessageEqual(final Log4jLogEvent that) {
    return loggerName.equals(that.loggerName) && message.equals(that.message);
}

/**
 * Compares metadata fields for equality.
 */
private boolean metadataEqual(final Log4jLogEvent that) {
    return Objects.equals(loggerFqcn, that.loggerFqcn)
            && Objects.equals(level, that.level)
            && Objects.equals(source, that.source)
            && Objects.equals(marker, that.marker);
}

/**
 * Compares ThreadContext fields for equality.
 */
private boolean contextEqual(final Log4jLogEvent that) {
    return Objects.equals(contextMap, that.contextMap)
            && Objects.equals(contextStack, that.contextStack)
            && Objects.equals(threadName, that.threadName);
}

/**
 * Compares throwable fields for equality.
 */
private boolean throwableFieldsEqual(final Log4jLogEvent that) {
    return Objects.equals(thrown, that.thrown) && Objects.equals(thrownProxy, that.thrownProxy);
}
