private void copyFromRingBufferLogEvent(final RingBufferLogEvent evt) {
    evt.initializeBuilder(this);
}

/**
 * Copies the standard {@code LogEvent} fields into this builder.
 */
private void copyStandardFields(final LogEvent other) {
    this.loggerFqcn = other.getLoggerFqcn();
    this.marker = other.getMarker();
    this.level = other.getLevel();
    this.loggerName = other.getLoggerName();
    this.message = other.getMessage();
