public static StackTraceElement calcLocation(final String fqcnOfLogger) {
    if (fqcnOfLogger == null) {
        return null;
    }
    return findCallerStackElement(fqcnOfLogger, new Throwable().getStackTrace());
}

private static StackTraceElement findCallerStackElement(final String fqcnOfLogger, final StackTraceElement[] stackTrace) {
    StackTraceElement last = null;
    for (int i = stackTrace.length - 1; i > 0; i--) {
        if (fqcnOfLogger.equals(stackTrace[i].getClassName())) {
            return last;
        }
        last = stackTrace[i];
    }
    return null;
}
```
Good.

