@Override
public boolean equals(final Object o) {
    if (this == o) {
        return true;
    }
    if (o == null || getClass() != o.getClass()) {
        return false;
    }
    final Log4jLogEvent that = (Log4jLogEvent) o;
    return hasSamePrimitiveFields(that)
            && hasSameLoggerFields(that)
            && hasSameMessageAndContextFields(that)
            && hasSameThrowableFields(that);
}

private boolean hasSamePrimitiveFields(final Log4jLogEvent that) {
    return endOfBatch == that.endOfBatch
            && includeLocation == that.includeLocation
            && timeMillis == that.timeMillis
            && nanoTime == that.nanoTime;
}

private boolean hasSameLoggerFields(final Log4jLogEvent that) {
    if (loggerFqcn != null ? !loggerFqcn.equals(that.loggerFqcn) : that.loggerFqcn != null) {
        return false;
    }
    if (level != null ? !level.equals(that.level) : that.level != null) {
        return false;
    }
    if (source != null ? !source.equals(that.source) : that.source != null) {
        return false;
    }
    if (marker != null ? !marker.equals(that.marker) : that.marker != null) {
        return false;
    }
    return true;
}

private boolean hasSameMessageAndContextFields(final Log4jLogEvent that) {
    if (contextMap != null ? !contextMap.equals(that.contextMap) : that.contextMap != null) {
        return false;
    }
    if (!message.equals(that.message)) {
        return false;
    }
    if (!loggerName.equals(that.loggerName)) {
        return false;
    }
    if (contextStack != null ? !contextStack.equals(that.contextStack) : that.contextStack != null) {
        return false;
    }
    if (threadName != null ? !threadName.equals(that.threadName) : that.threadName != null) {
        return false;
    }
    return true;
}

private boolean hasSameThrowableFields(final Log4jLogEvent that) {
    if (thrown != null ? !thrown.equals(that.thrown) : that.thrown != null) {
        return false;
    }
    if (thrownProxy != null ? !thrownProxy.equals(that.thrownProxy) : that.thrownProxy != null) {
        return false;
    }
    return true;
}

