            final Log4jLogEvent result = new Log4jLogEvent(
                    new LoggerInfo(proxy.loggerName, proxy.marker, proxy.loggerFQCN, proxy.level),
                    new MessageInfo(proxy.message, proxy.thrown, proxy.thrownProxy),
                    new ContextInfo(proxy.contextMap, proxy.contextStack),
                    new ThreadInfo(proxy.threadName, proxy.source, proxy.timeMillis, proxy.nanoTime));
            result.setEndOfBatch(proxy.isEndOfBatch);
            result.setIncludeLocation(proxy.isLocationRequired);
            return result;
        }
        throw new IllegalArgumentException("Event is not a serialized LogEvent: " + event.toString());
    }

    private void readObject(final ObjectInputStream stream) throws InvalidObjectException {
        throw new InvalidObjectException("Proxy required");
    }

    @Override
    public String toString() {
        final StringBuilder sb = new StringBuilder();
        final String n = loggerName.isEmpty() ? LoggerConfig.ROOT : loggerName;
        sb.append("Logger=").append(n);
        sb.append(" Level=").append(level.name());
        sb.append(" Message=").append(message.getFormattedMessage());
        return sb.toString();
    }

    private static boolean equalObject(final Object a, final Object b) {
        return a != null ? a.equals(b) : b == null;
    }

    private static boolean equalLong(final long a, final long b) {
        return a == b;
    }

    private static boolean equalBoolean(final boolean a, final boolean b) {
        return a == b;
    }

    private boolean equalsFlags(final Log4jLogEvent that) {
        return equalBoolean(endOfBatch, that.endOfBatch)
                && equalBoolean(includeLocation, that.includeLocation);
    }

    private boolean equalsLoggerInfo(final Log4jLogEvent that) {
        return equalObject(loggerFqcn, that.loggerFqcn)
                && equalObject(level, that.level)
                && loggerName.equals(that.loggerName);
    }

    private boolean equalsMessageInfo(final Log4jLogEvent that) {
        return message.equals(that.message)
                && equalObject(thrown, that.thrown)
                && equalObject(thrownProxy, that.thrownProxy);
    }

    private boolean equalsContextInfo(final Log4jLogEvent that) {
        return equalObject(marker, that.marker)
                && equalObject(contextMap, that.contextMap)
                && equalObject(contextStack, that.contextStack);
    }

    private boolean equalsThreadInfo(final Log4jLogEvent that) {
        return equalObject(threadName, that.threadName)
                && equalObject(source, that.source)
                && equalLong(timeMillis, that.timeMillis)
                && equalLong(nanoTime, that.nanoTime);
    }

    @Override
    public boolean equals(final Object o) {
        if (this == o) {
            return true;
        }
        if (o == null || getClass() != o.getClass()) {
            return false;
        }

        final Log4jLogEvent that = (Log4jLogEvent) o;
        return equalsFlags(that)
                && equalsLoggerInfo(that)
                && equalsMessageInfo(that)
                && equalsContextInfo(that)
                && equalsThreadInfo(that);
    }

    @Override
    public int hashCode() {
        // Check:OFF: MagicNumber
        int result = loggerFqcn != null ? loggerFqcn.hashCode() : 0;
        result = 31 * result + (marker != null ? marker.hashCode() : 0);
        result = 31 * result + (level != null ? level.hashCode() : 0);
        result = 31 * result + loggerName.hashCode();
        result = 31 * result + message.hashCode();
        result = 31 * result + (int) (timeMillis ^ (timeMillis >>> 32));
        result = 31 * result + (int) (nanoTime ^ (nanoTime >>> 32));
        result = 31 * result + (thrown != null ? thrown.hashCode() : 0);
        result = 31 * result + (thrownProxy != null ? thrownProxy.hashCode() : 0);
        result = 31 * result + (contextMap != null ? contextMap.hashCode() : 0);
        result = 31 * result + (contextStack != null ? contextStack.hashCode() : 0);
        result = 31 * result + (threadName != null ? threadName.hashCode() : 0);
        result = 31 * result + (source != null ? source.hashCode() : 0);
        result = 31 * result + (includeLocation ? 1 : 0);
        result = 31 * result + (endOfBatch ? 1 : 0);
        // Check:ON: MagicNumber
        return result;
    }

    /**
     * Proxy pattern used to serialize the LogEvent.
     */
    private static class LogEventProxy implements Serializable {

        private static final long serialVersionUID = -7139032940312647146L;
        private final String loggerFQCN;
        private final Marker marker;
        private final Level level;
        private final String loggerName;
        private final Message message;
        private final long timeMillis;
        private final transient Throwable thrown;
        private final ThrowableProxy thrownProxy;
        private final Map<String, String> contextMap;
        private final ThreadContext.ContextStack contextStack;
        private final String threadName;
        private final StackTraceElement source;
        private final boolean isLocationRequired;
        private final boolean isEndOfBatch;
        /** @since Log4J 2.4 */
        private final transient long nanoTime;

        public LogEventProxy(final Log4jLogEvent event, final boolean includeLocation) {
            this.loggerFQCN = event.loggerFqcn;
            this.marker = event.marker;
            this.level = event.level;
            this.loggerName = event.loggerName;
            this.message = event.message;
            this.timeMillis = event.timeMillis;
            this.thrown = event.thrown;
            this.thrownProxy = event.thrownProxy;
            this.contextMap = event.contextMap;
            this.contextStack = event.contextStack;
            this.source = includeLocation ? event.getSource() : null;
            this.threadName = event.getThreadName();
            this.isLocationRequired = includeLocation;
            this.isEndOfBatch = event.endOfBatch;
            this.nanoTime = event.nanoTime;
        }

        /**
         * Returns a Log4jLogEvent using the data in the proxy.
         * @return Log4jLogEvent.
         */
        protected Object readResolve() {
            final Log4jLogEvent result = new Log4jLogEvent(
                    new LoggerInfo(loggerName, marker, loggerFQCN, level),
                    new MessageInfo(message, thrown, thrownProxy),
                    new ContextInfo(contextMap, contextStack),
                    new ThreadInfo(threadName, source, timeMillis, nanoTime));
            result.setEndOfBatch(isEndOfBatch);
            result.setIncludeLocation(isLocationRequired);
            return result;
        }
    }
