            public void appendTo(final Object array, final StringBuilder str) {
                str.append(Arrays.toString((int[]) array));
            }
        });
        map.put(long[].class, new ArrayStringifier() {
            @Override
            public void appendTo(final Object array, final StringBuilder str) {
