     * @param buf  the string builder to substitute into, not null
     * @param offset  the start offset within the builder, must be valid
     * @param length  the length within the builder to be processed, must be valid
     * @return true if altered
     */
    protected boolean substitute(final LogEvent event, final StringBuilder buf, final int offset, final int length) {
        return substitute(event, buf, offset, length, null) > 0;
    }

    /**
     * Recursive handler for multiple levels of interpolation. This is the main
     * interpolation method, which resolves the values of all variable references
     * contained in the passed in text.
     *
     * @param event The current LogEvent, if there is one.
     * @param buf  the string builder to substitute into, not null
     * @param offset  the start offset within the builder, must be valid
     * @param length  the length within the builder to be processed, must be valid
     * @param priorVariables  the stack keeping track of the replaced variables, may be null
     * @return the length change that occurs, unless priorVariables is null when the int
     *  represents a boolean flag as to whether any change occurred.
     */
    private int substitute(final LogEvent event, final StringBuilder buf, final int offset, final int length,
                           List<String> priorVariables) {
        final StrMatcher prefixMatcher = getVariablePrefixMatcher();
        final StrMatcher suffixMatcher = getVariableSuffixMatcher();
        final char escape = getEscapeChar();
        final StrMatcher valueDelimiterMatcher = getValueDelimiterMatcher();
        final boolean substitutionInVariablesEnabled = isEnableSubstitutionInVariables();

        final boolean top = priorVariables == null;
        boolean altered = false;
        int lengthChange = 0;
        char[] chars = getChars(buf);
        int bufEnd = offset + length;
        int pos = offset;
        while (pos < bufEnd) {
            final int startMatchLen = prefixMatcher.isMatch(chars, pos, offset, bufEnd);
            if (startMatchLen == 0) {
                pos++;
                continue;
            }
            if (isEscaped(chars, pos, offset, escape)) {
                buf.deleteCharAt(pos - 1);
                chars = getChars(buf);
                lengthChange--;
                altered = true;
                bufEnd--;
                continue;
            }
            final EndMatch endMatch = findVariableEnd(chars, pos, startMatchLen, offset, bufEnd,
                    prefixMatcher, suffixMatcher, substitutionInVariablesEnabled);
            if (endMatch == null) {
                pos = bufEnd;
            } else {
                final VariableMatch match = processVariable(event, buf, chars, pos, endMatch, startMatchLen,
                        offset, bufEnd, lengthChange, priorVariables, valueDelimiterMatcher,
                        substitutionInVariablesEnabled, length, prefixMatcher);
                pos = match.pos;
                bufEnd = match.bufEnd;
                lengthChange = match.lengthChange;
                chars = match.chars;
                priorVariables = match.priorVariables;
                if (top && match.replaced) {
                    altered = true;
                }
            }
        }
        if (top) {
            return altered ? 1 : 0;
        }
        return lengthChange;
    }

    private static boolean isEscaped(final char[] chars, final int pos, final int offset, final char escape) {
        return pos > offset && chars[pos - 1] == escape;
    }

    private static EndMatch findVariableEnd(final char[] chars, final int startPos, final int startMatchLen,
            final int offset, final int bufEnd, final StrMatcher prefixMatcher, final StrMatcher suffixMatcher,
            final boolean substitutionInVariablesEnabled) {
        int pos = startPos + startMatchLen;
        int nestedVarCount = 0;
        while (pos < bufEnd) {
            int nestedMatchLen = 0;
            if (substitutionInVariablesEnabled
                    && (nestedMatchLen = prefixMatcher.isMatch(chars, pos, offset, bufEnd)) != 0) {
                nestedVarCount++;
                pos += nestedMatchLen;
                continue;
            }
            final int endMatchLen = suffixMatcher.isMatch(chars, pos, offset, bufEnd);
            if (endMatchLen == 0) {
                pos++;
                continue;
            }
            if (nestedVarCount == 0) {
                return new EndMatch(pos + endMatchLen, endMatchLen);
            }
            nestedVarCount--;
            pos += endMatchLen;
        }
        return null;
    }

    private VariableMatch processVariable(final LogEvent event, final StringBuilder buf, final char[] chars,
            final int startPos, final EndMatch endMatch, final int startMatchLen, final int offset, final int bufEnd,
            final int lengthChange, List<String> priorVariables, final StrMatcher valueDelimiterMatcher,
            final boolean substitutionInVariablesEnabled, final int length, final StrMatcher prefixMatcher) {
        final int endPos = endMatch.endPos;
        String varNameExpr = new String(chars, startPos + startMatchLen,
                endPos - startMatchLen - endMatch.suffixLen - startPos);
        if (substitutionInVariablesEnabled) {
            final StringBuilder bufName = new StringBuilder(varNameExpr);
            substitute(event, bufName, 0, bufName.length());
            varNameExpr = bufName.toString();
        }
        final VariableSpec spec = parseVariableSpec(varNameExpr, valueDelimiterMatcher,
                substitutionInVariablesEnabled, prefixMatcher);
        if (priorVariables == null) {
            priorVariables = new ArrayList<>();
            priorVariables.add(new String(chars, offset, length + lengthChange));
        }
        checkCyclicSubstitution(spec.varName, priorVariables);
        priorVariables.add(spec.varName);
        String varValue = resolveVariable(event, spec.varName, buf, startPos, endPos);
        if (varValue == null) {
            varValue = spec.defaultValue;
        }
        final VariableMatch match;
